// Content for Raising Neurodiverse Kids (node g67, Parent Layer, Chapter 8): NEW v2 build to GDD 67
// (mechanic-embodying), a Parent-Layer pillar and a warm callback to Same Same, Different (g04): difference is
// wonderful, grown up for parents. It reframes neurodivergence as DIFFERENCE, not deficiency: strengths-first and
// never deficit-shaming. 84 researched, India-grounded scenarios across understand-your-child → accommodate →
// advocate → drop-the-shame → strengths-and-wellbeing → support-and-you, each encoded as one of the shared v2 play
// actions (strike-rewrite / branch / sort / reflect / match / role-play / spot): no binary "tap the right card".
// Lead: strike-rewrite (bust the myth), branch (your move), sort. Six modes: understand your child (the common
// neurodivergences, strengths-first, your child's own profile & pace; different, not less; brains naturally vary),
// accommodate (adjust the environment & expectations to the child rather than forcing them to mask; sensory,
// attention, transitions, routines; accommodations give fair access like glasses, they don't spoil), advocate (you
// are your child's key advocate; school accommodations, family understanding, services: with rights under the
// Rights of Persons with Disabilities Act 2016, which recognises autism & learning disabilities and mandates
// reasonable accommodation; seek assessment without shame), drop the shame and blame (it's no one's fault: NOT
// caused by parenting, screens or vaccines; meltdowns are overwhelm not naughtiness; you don't grow out of it;
// stop hiding it), strengths and wellbeing (build on strengths & passions, meet meltdowns with calm co-regulation
// not punishment, take co-occurring anxiety seriously, see the whole wonderful child not a label), support and you
// (parent wellbeing matters and it is demanding: lean on peer parents & professionals; routes parent burnout to
// Looking After You g63). Strengths-based and NEVER deficit-shaming, never blaming parent or child, accurate &
// expert-reviewed; NOT a diagnostic tool: points to professionals. Builds on Same Same, Different (g04); a
// Parent-Layer pillar alongside Break the Cycle (g65) and Raising Gender-Diverse Kids (g66). India: neurodiversity
// is heavily stigmatised & under-recognised, with delayed diagnoses often blamed on parenting and school
// accommodations a fight: the node de-stigmatises, helps parents seek assessment & support without shame, and
// points to rights under the RPwD Act 2016. gameId "raising-neurodiverse-kids".
import type { V2GameConfig, Scenario } from "./v2-schema";

const SCENARIOS: Scenario[] = [
  {"id":"nd-001","cat":"understand-your-child","type":"strike-rewrite","hook":"\"A neurodiverse child is broken or less than other children.\"","myth":{"un":"A neurodiverse child is broken or less than other children.","re":"Neurodivergence is a different way a brain is wired, not a fault or a lesser version; different, not less.","why":"Different wiring isn't damaged wiring."},"relearn":"A neurodiverse child isn't broken or less; their brain is wired differently, different, not less.","persona":"Meena","source":"different not less"},
  {"id":"nd-002","cat":"understand-your-child","type":"strike-rewrite","hook":"\"Autism, ADHD and dyslexia are just labels for naughty or lazy kids.\"","myth":{"un":"Autism, ADHD and dyslexia are just labels for naughty or lazy kids.","re":"They're real, recognised ways of being and learning, not naughtiness or laziness; understanding them changes everything.","why":"A profile isn't a character flaw."},"relearn":"Autism, ADHD and dyslexia are real ways of being and learning, not naughtiness or laziness.","persona":"Meena","source":"real not naughty"},
  {"id":"nd-003","cat":"understand-your-child","type":"reflect","hook":"Lensy: understanding how your child is actually wired is the first, biggest act of love. Sit right?","prompt":"What do you think?","options":["Sits right","Understand first","Act of love"],"affirm":"Truly understanding how your child is wired, rather than judging them by a typical template, is a foundational act of love.","relearn":"Understanding how your child is actually wired is the first, biggest act of love.","persona":"Meena","source":"understand first"},
  {"id":"nd-004","cat":"understand-your-child","type":"sort","hook":"Sort: a strength a neurodiverse child may bring, or a 'deficit' the old view focuses on?","items":[{"id":"a","text":"Deep focus on a passion"},{"id":"b","text":"Only 'won't sit still'"},{"id":"c","text":"Pattern-spotting and memory"},{"id":"d","text":"Only 'can't pay attention'"},{"id":"e","text":"Honest, says what's true"},{"id":"f","text":"Only 'always in his own world'"}],"bins":[{"id":"strength","label":"A real strength","valence":"pos"},{"id":"deficit","label":"The deficit-only view","valence":"neg"}],"key":{"a":"strength","b":"deficit","c":"strength","d":"deficit","e":"strength","f":"deficit"},"relearn":"Deep focus, pattern-spotting and honesty are real strengths; 'won't sit still, can't focus, own world' sees only deficits.","persona":"any","source":"strength vs deficit"},
  {"id":"nd-005","cat":"understand-your-child","type":"match","hook":"Match each neurodivergence to a common strength (every child is individual).","pairs":[{"left":"Autism","right":"Deep focus, honesty, pattern recognition"},{"left":"ADHD","right":"Energy, creativity, quick thinking"},{"left":"Dyslexia","right":"Big-picture and spatial thinking"},{"left":"Dyspraxia","right":"Creative, determined problem-solving"},{"left":"Dyscalculia","right":"Strong words and storytelling"}],"relearn":"Autism, ADHD, dyslexia and other profiles each commonly come with real strengths, though every child's profile is their own.","persona":"any","source":"strengths by profile"},
  {"id":"nd-006","cat":"understand-your-child","type":"branch","hook":"You keep comparing your child to 'typical' milestones and feeling worried.","options":[{"text":"Understand and support your child's own profile and pace","consequence":"You meet your actual child, not a template.","outcome":"their-pace","best":true},{"text":"Keep measuring them against a standard mould","consequence":"Their own profile meets them where they are; a standard mould misses who they are."}],"debrief":"Support your child's own profile and pace rather than a typical template.","relearn":"Meet your actual child's profile and pace, not a one-size template that misses them.","persona":"Divya","source":"their own pace"},
  {"id":"nd-007","cat":"understand-your-child","type":"strike-rewrite","hook":"\"There's one normal way for a child's brain to work, and my child should fit it.\"","myth":{"un":"There's one normal way for a child's brain to work, and my child should fit it.","re":"Brains naturally vary; neurodiversity is part of human variation, and your child's way of thinking is valid.","why":"Variation is the norm, not the exception."},"relearn":"There's no single 'normal' brain; neurodiversity is natural human variation, and your child's mind is valid.","persona":"Meena","source":"variation is natural"},
  {"id":"nd-008","cat":"understand-your-child","type":"reflect","hook":"Lensy: when you see your child's strengths, not just their struggles, you change how they see themselves. Resonate?","prompt":"What's your take?","options":["Resonates","See strengths","Changes them"],"affirm":"Seeing a neurodiverse child's strengths, not only their struggles, shapes how they come to see themselves.","relearn":"When you see your child's strengths, not just struggles, you change how they see themselves.","persona":"Meena","source":"see strengths"},
  {"id":"nd-009","cat":"understand-your-child","type":"spot","hook":"Spot the two lines that fail to understand a neurodiverse child.","scene":[{"id":"a","text":"'Her brain works differently, that's okay'","trick":false},{"id":"b","text":"'She's being difficult on purpose'","trick":true},{"id":"c","text":"'Let me learn how she sees the world'","trick":false},{"id":"d","text":"'She'll be fine once I make her act normal'","trick":true},{"id":"e","text":"'What strengths can I build on?'","trick":false}],"why":"'Difficult on purpose' and 'make her act normal' misunderstand the child; the others understand and build on strengths.","relearn":"Serve a neurodiverse child by understanding their experience and strengths, not labelling them 'difficult' or forcing 'normal'.","persona":"Meena","source":"serving understanding"},
  {"id":"nd-010","cat":"understand-your-child","type":"branch","hook":"Your child has just been identified as neurodivergent and you feel overwhelmed.","options":[{"text":"Take it as information that helps you understand and support them","consequence":"The label becomes a key, not a sentence.","outcome":"a-key","best":true},{"text":"Treat it as a tragedy or a verdict","consequence":"As information it unlocks support; as a tragedy it projects fear onto the same child."}],"debrief":"Treat a neurodivergence as information that helps you support your child, not a tragedy or verdict.","relearn":"A diagnosis is a key to understanding and support, not a verdict; your child is unchanged.","persona":"Meena","source":"a key not a sentence"},
  {"id":"nd-011","cat":"accommodate","type":"strike-rewrite","hook":"\"My child must be forced to fit the standard environment and behave 'normally'.\"","myth":{"un":"My child must be forced to fit the standard environment and behave 'normally'.","re":"It works far better to adjust the environment and expectations to the child than to force the child to mask who they are.","why":"Flex the setting, not the child."},"relearn":"Adjust the environment and expectations to your child rather than forcing them to mask and fit a standard mould.","persona":"Meena","source":"flex the setting"},
  {"id":"nd-012","cat":"accommodate","type":"sort","hook":"Sort: a supportive accommodation, or forcing the child to mask?","items":[{"id":"a","text":"Noise-cancelling headphones for sensory overload"},{"id":"b","text":"Punishing stimming"},{"id":"c","text":"A visual schedule and routine"},{"id":"d","text":"Demanding constant eye contact"},{"id":"e","text":"Short tasks with movement breaks"},{"id":"f","text":"Forcing him to sit perfectly still"}],"bins":[{"id":"support","label":"Supportive accommodation","valence":"pos"},{"id":"mask","label":"Forcing masking","valence":"neg"}],"key":{"a":"support","b":"mask","c":"support","d":"mask","e":"support","f":"mask"},"relearn":"Headphones, visual schedules and movement breaks support; punishing stimming, demanding eye contact or forcing stillness force masking.","persona":"Meena","source":"support vs mask"},
  {"id":"nd-013","cat":"accommodate","type":"match","hook":"Match each need to a practical home accommodation.","pairs":[{"left":"Sensory overload","right":"A calm, low-stimulation space"},{"left":"Trouble with transitions","right":"Warnings and a visual routine"},{"left":"Attention differences","right":"Short steps, movement breaks"},{"left":"Mealtime stress","right":"Respect food needs, no forcing"},{"left":"Big feelings","right":"A calm-down space, not a scolding"}],"relearn":"Sensory overload, transitions, attention, mealtimes and big feelings each have a simple, practical accommodation that helps.","persona":"any","source":"need to accommodation"},
  {"id":"nd-014","cat":"accommodate","type":"strike-rewrite","hook":"\"Accommodations spoil a child or are unfair to others.\"","myth":{"un":"Accommodations spoil a child or are unfair to others.","re":"Accommodations give a child fair access to the same chances, like glasses for sight; they level the ground, not tilt it.","why":"Fair isn't always identical."},"relearn":"Accommodations don't spoil a child; like glasses, they give fair access to the same chances.","persona":"Vikram","source":"fair access"},
  {"id":"nd-015","cat":"accommodate","type":"branch","hook":"Your child melts down in loud, crowded places every time.","options":[{"text":"Adjust plans and bring sensory supports to prevent overload","consequence":"You set your child up to cope, not fail.","outcome":"prevent","best":true},{"text":"Keep forcing the situation and punishing the meltdown","consequence":"Supports prevent overload; forcing it and punishing the meltdown harms a child who is overwhelmed, not misbehaving."}],"debrief":"Prevent sensory overload by adjusting plans and bringing supports.","relearn":"Adjust for sensory overload instead of forcing it; a meltdown is overwhelm, not misbehaviour.","persona":"Meena","source":"prevent overload"},
  {"id":"nd-016","cat":"accommodate","type":"reflect","hook":"Lensy: a child who is accommodated can show you their best; one who is forced to mask is just surviving. Sit right?","prompt":"What do you think?","options":["Sits right","Their best","Not just surviving"],"affirm":"When a child's environment is accommodated they can flourish and show their strengths, rather than exhausting themselves masking.","relearn":"An accommodated child can show you their best; a child forced to mask is just surviving.","persona":"Meena","source":"show their best"},
  {"id":"nd-017","cat":"accommodate","type":"spot","hook":"Spot the two moves that drain your child instead of helping them thrive.","scene":[{"id":"a","text":"Adjusting the environment to their needs","trick":false},{"id":"b","text":"Forcing them to suppress who they are","trick":true},{"id":"c","text":"Building on their strengths and interests","trick":false},{"id":"d","text":"Punishing them for self-soothing","trick":true},{"id":"e","text":"A quiet break when overstimulated","trick":false}],"why":"Forcing suppression and punishing self-soothing drain a child; adjusting the setting and strengths help them thrive.","relearn":"Forcing suppression and punishing self-soothing drain a child; adjusting the setting and strengths help them thrive.","persona":"Meena","source":"thrive accommodation"},
  {"id":"nd-018","cat":"accommodate","type":"match","hook":"Match each setting to an accommodation that helps.","pairs":[{"left":"Mealtimes","right":"Respect food sensitivities, no force"},{"left":"Bedtime","right":"A predictable, calming routine"},{"left":"Homework","right":"Chunked tasks and breaks"},{"left":"Outings","right":"Headphones and a quiet exit plan"},{"left":"Mornings","right":"A visual step-by-step checklist"}],"relearn":"Mealtimes, bedtime, homework, outings and mornings each go better with accommodations that fit the child's wiring.","persona":"any","source":"setting to support"},
  {"id":"nd-019","cat":"accommodate","type":"strike-rewrite","hook":"\"If I accommodate my child, they'll never learn to cope with the real world.\"","myth":{"un":"If I accommodate my child, they'll never learn to cope with the real world.","re":"Accommodation builds the security and skills from which real coping grows; forcing distress teaches fear, not coping.","why":"Support is the launchpad, not the crutch."},"relearn":"Accommodation builds the security from which coping grows; forced distress teaches fear, not real-world skills.","persona":"Vikram","source":"support builds coping"},
  {"id":"nd-020","cat":"accommodate","type":"branch","hook":"You're unsure which accommodations your child actually needs.","options":[{"text":"Watch, ask your child, and try supports to see what helps","consequence":"You find what works for your real child.","outcome":"tailored","best":true},{"text":"Apply a generic checklist and ignore their cues","consequence":"Watching, asking and trying tailors support; a generic checklist that ignores their cues misses the mark."}],"debrief":"Find the right accommodations by watching, asking your child and trying supports.","relearn":"Tailor accommodations by observing and asking your child, not by applying a generic checklist.","persona":"Divya","source":"find what works"},
  {"id":"nd-021","cat":"advocate","type":"strike-rewrite","hook":"\"It's not my place to push for support; I should just accept whatever school gives.\"","myth":{"un":"It's not my place to push for support; I should just accept whatever school gives.","re":"You are your child's most important advocate; pushing kindly but firmly for the support they need is part of the job.","why":"No one will champion your child like you."},"relearn":"You are your child's key advocate; pushing kindly but firmly for the support they need is part of parenting.","persona":"Meena","source":"you are the advocate"},
  {"id":"nd-022","cat":"advocate","type":"strike-rewrite","hook":"\"My neurodiverse child has no real rights to support in India.\"","myth":{"un":"My neurodiverse child has no real rights to support in India.","re":"The Rights of Persons with Disabilities Act 2016 recognises autism and learning disabilities and mandates reasonable accommodation, including in schools.","why":"The law is on your child's side."},"relearn":"Your child has rights: the RPwD Act 2016 recognises autism and learning disabilities and mandates reasonable accommodation.","persona":"Meena","source":"RPwD rights"},
  {"id":"nd-023","cat":"advocate","type":"sort","persona":"any","source":"advocate vs giveup","hook":"Sort: effective advocacy, or giving up your child's support?","items":[{"id":"a","text":"Requesting accommodations in writing"},{"id":"b","text":"Accepting 'he's just naughty'"},{"id":"c","text":"Bringing evidence and staying calm"},{"id":"d","text":"Hiding the diagnosis from teachers"},{"id":"e","text":"Following up after a 'we'll see'"},{"id":"f","text":"Giving up after one 'no'"}],"bins":[{"id":"advocate","label":"Effective advocacy","valence":"pos"},{"id":"giveup","label":"Gives up support","valence":"neg"}],"key":{"a":"advocate","b":"giveup","c":"advocate","d":"giveup","e":"advocate","f":"giveup"},"relearn":"Written requests, calm evidence and following up are effective advocacy; accepting 'naughty', hiding it or giving up surrender support."},
  {"id":"nd-024","cat":"advocate","type":"branch","hook":"The school dismisses your child's needs as 'bad behaviour'.","options":[{"text":"Calmly explain the profile and request specific accommodations","consequence":"You shift them from blame to support.","outcome":"support","best":true},{"text":"Accept the blame and ask nothing","consequence":"Explaining the profile and requesting accommodations shifts school to support; accepting blame leaves your child unhelped."}],"debrief":"When school calls needs 'bad behaviour', explain the profile and request accommodations.","relearn":"Reframe 'bad behaviour' by explaining the profile and requesting accommodations.","persona":"Meena","source":"explain and request"},
  {"id":"nd-025","cat":"advocate","type":"match","persona":"Meena","source":"arena to move","hook":"Match each arena to an advocacy move.","pairs":[{"left":"School","right":"Request a learning-support plan"},{"left":"Family","right":"Share understanding, set respectful limits"},{"left":"Services","right":"Seek assessment and ongoing support"},{"left":"Exam board","right":"Apply for concessions with a report"},{"left":"Co-parent","right":"Agree the plan and share the load"}],"relearn":"School, family, services, the exam board and your co-parent each call for accommodations, understanding, assessment, concessions, shared load."},
  {"id":"nd-026","cat":"advocate","type":"role-play","hook":"A relative insists your child just needs 'strict discipline'. You want to advocate calmly.","setup":"Advocate calmly:","yourLine":[{"text":"\"His brain works differently, and what helps him is support and understanding, not harsher punishment.\"","best":true},{"text":"\"You're right, maybe I'm too soft on him.\""}],"relearn":"Calmly explaining that support, not harsher punishment, is what helps protects your child from misguided 'discipline'.","persona":"Meena","source":"calm advocacy"},
  {"id":"nd-027","cat":"advocate","type":"reflect","hook":"Lensy: every time you advocate, you teach your child that they're worth fighting for. Worth it?","prompt":"What do you think?","options":["Worth it","Worth fighting for","Yes"],"affirm":"Each act of advocacy teaches a neurodiverse child that they matter and are worth standing up for.","relearn":"Every time you advocate, you teach your child that they're worth fighting for.","persona":"Meena","source":"worth fighting for"},
  {"id":"nd-028","cat":"advocate","type":"spot","persona":"any","source":"effective advocacy","hook":"Spot the two red flags: 'advocacy' that leaves your child unsupported.","scene":[{"id":"a","text":"Knowing their rights and asking clearly","trick":false},{"id":"b","text":"Staying silent to avoid being 'that parent'","trick":true},{"id":"c","text":"Partnering with teachers on a plan","trick":false},{"id":"d","text":"Apologising until you drop the request","trick":true},{"id":"e","text":"Putting the agreed support in writing","trick":false}],"why":"Staying silent and over-apologising until you drop the ask leave your child unsupported; the rest get real support.","relearn":"Staying silent or apologising the request away give up support; knowing rights, partnering and writing it down secure it."},
  {"id":"nd-029","cat":"advocate","type":"branch","hook":"You suspect your child is neurodivergent but worry that assessment is 'making a problem'.","options":[{"text":"Seek a professional assessment to understand them","consequence":"You open the door to the right support.","outcome":"assess","best":true},{"text":"Avoid it so as not to 'label' them","consequence":"Assessment opens the door to support; dodging a 'label' delays the help your child needs."}],"debrief":"Seek assessment if you suspect neurodivergence; it opens the door to support, it isn't 'making a problem'.","relearn":"Pursue assessment rather than dodging a 'label'; understanding unlocks support.","persona":"Divya","source":"seek assessment"},
  {"id":"nd-030","cat":"advocate","type":"strike-rewrite","hook":"\"Asking for help with my child marks me as a failing parent.\"","myth":{"un":"Asking for help with my child marks me as a failing parent.","re":"Seeking support and accommodations is exactly what good, informed parents of neurodiverse kids do; it's strength, not failure.","why":"Getting help is wise parenting."},"relearn":"Asking for help and accommodations is what good parents of neurodiverse kids do; it's strength, not failure.","persona":"Vikram","source":"help is strength"},
  {"id":"nd-031","cat":"drop-the-shame","type":"strike-rewrite","hook":"\"My child's neurodivergence is caused by my bad parenting.\"","myth":{"un":"My child's neurodivergence is caused by my bad parenting.","re":"Neurodivergence isn't caused by parenting, screens, vaccines or anything you did; it's simply how your child is wired.","why":"It's no one's fault, least of all yours."},"relearn":"Neurodivergence isn't caused by your parenting or by screens or vaccines; it's simply how your child is wired.","persona":"Meena","source":"not your fault"},
  {"id":"nd-032","cat":"drop-the-shame","type":"strike-rewrite","hook":"\"A child who melts down or can't sit still is just badly behaved.\"","myth":{"un":"A child who melts down or can't sit still is just badly behaved.","re":"Meltdowns and restlessness are often the brain overwhelmed or wired differently, not naughtiness to be punished.","why":"Behaviour is communication, not defiance."},"relearn":"Meltdowns and restlessness are usually overwhelm or different wiring, not bad behaviour to punish.","persona":"Meena","source":"not bad behaviour"},
  {"id":"nd-033","cat":"drop-the-shame","type":"strike-rewrite","hook":"\"They'll just grow out of it if we ignore it.\"","myth":{"un":"They'll just grow out of it if we ignore it.","re":"Neurodivergence is lifelong; understanding and support help a child thrive, while ignoring it leaves them struggling alone.","why":"Support helps; waiting it out doesn't."},"relearn":"A child doesn't 'grow out of' neurodivergence; understanding and support help them thrive, ignoring it doesn't.","persona":"Vikram","source":"not grow out of it"},
  {"id":"nd-034","cat":"drop-the-shame","type":"sort","hook":"Sort each line: a fact that lifts shame, or a myth that piles it on.","items":[{"id":"a","text":"It's no one's fault"},{"id":"b","text":"'You spoiled or caused this'"},{"id":"c","text":"Your child can thrive with support"},{"id":"d","text":"'A good family hides it'"},{"id":"e","text":"A diagnosis is a key to support"},{"id":"f","text":"'Screens made him this way'"}],"bins":[{"id":"lifts","label":"Lifts shame","valence":"pos"},{"id":"piles","label":"Piles on shame","valence":"neg"}],"key":{"a":"lifts","b":"piles","c":"lifts","d":"piles","e":"lifts","f":"piles"},"relearn":"'No one's fault', 'can thrive with support' and 'a key to support' lift shame; 'you caused it', 'hide it' and 'screens' pile it on unfairly.","persona":"any","source":"lifts vs piles"},
  {"id":"nd-035","cat":"drop-the-shame","type":"reflect","hook":"Lensy: you didn't cause this, you can't 'cure' it, and you absolutely can help your child flourish. Land okay?","prompt":"What do you think?","options":["Lands okay","Not my fault","I can help"],"affirm":"You didn't cause your child's neurodivergence and can't cure it, but you can absolutely help them flourish.","relearn":"You didn't cause it, you can't cure it, and you can help your child flourish.","persona":"Meena","source":"didnt cause it"},
  {"id":"nd-036","cat":"drop-the-shame","type":"branch","hook":"Relatives blame you, or your child, for the neurodivergence.","options":[{"text":"Calmly correct the blame and protect your child from it","consequence":"You shield your child from undeserved shame.","outcome":"shield","best":true},{"text":"Absorb the blame and pass it to your child","consequence":"Correcting the blame shields your child; passing it on hands them shame they don't deserve."}],"debrief":"Correct relatives' blame calmly and protect your child from it; it's no one's fault.","relearn":"Shield your child from blame by correcting it calmly; don't pass undeserved shame on to them.","persona":"Meena","source":"shield from blame"},
  {"id":"nd-037","cat":"drop-the-shame","type":"spot","hook":"Spot the two shame-keeping moves (the ones that pile blame on the family).","scene":[{"id":"a","text":"Knowing it's no one's fault","trick":false},{"id":"b","text":"Hiding the child from relatives","trick":true},{"id":"c","text":"Talking about it openly and kindly","trick":false},{"id":"d","text":"Blaming yourself for 'causing' it","trick":true},{"id":"e","text":"Focusing energy on his support","trick":false}],"why":"Hiding the child and self-blame keep the shame alive; the rest, knowing it's no one's fault, openness, support, drop it.","relearn":"Catch shame-keeping moves like hiding the child and self-blame; families drop the shame by openness and support.","persona":"any","source":"catch shame-keepers"},
  {"id":"nd-038","cat":"drop-the-shame","type":"reflect","hook":"Lensy: shame helps no one; your energy is better spent understanding and championing your child. Agree?","prompt":"What's your take?","options":["Agree","Champion not shame","Energy well spent"],"affirm":"Shame and blame help no one; that energy is far better spent understanding and championing your child.","relearn":"Shame helps no one; spend that energy understanding and championing your child instead.","persona":"Meena","source":"champion not shame"},
  {"id":"nd-039","cat":"drop-the-shame","type":"strike-rewrite","hook":"\"I should hide my child's diagnosis so people don't judge us.\"","myth":{"un":"I should hide my child's diagnosis so people don't judge us.","re":"Hiding it reinforces stigma and isolates you both; openness, on your own terms, lets support and understanding in.","why":"Secrecy feeds the shame it fears."},"relearn":"Hiding a diagnosis reinforces stigma and isolation; sharing on your own terms lets in support and understanding.","persona":"Vikram","source":"openness over hiding"},
  {"id":"nd-040","cat":"drop-the-shame","type":"branch","hook":"You feel grief and guilt about your child's diagnosis.","options":[{"text":"Allow the feelings, drop the guilt, refocus on your child as they are","consequence":"You move from grief to engaged support.","outcome":"refocus","best":true},{"text":"Stay stuck in guilt and what-ifs","consequence":"Allowing feelings and dropping guilt frees you to support your child; staying stuck in guilt drains you."}],"debrief":"Allow grief but drop the guilt, and refocus on supporting the child in front of you.","relearn":"Feel what you feel, drop the guilt, refocus on your child as they are; what-ifs help no one.","persona":"Meena","source":"drop the guilt"},
  {"id":"nd-041","cat":"strengths-and-wellbeing","type":"strike-rewrite","hook":"\"I should focus only on fixing my neurodiverse child's weaknesses.\"","myth":{"un":"I should focus only on fixing my neurodiverse child's weaknesses.","re":"Building on a child's strengths and passions does more for their confidence and growth than fixating on deficits.","why":"Strengths are the foundation to build on."},"relearn":"Build on your child's strengths and passions, not only their weaknesses; that grows confidence and skills.","persona":"Meena","source":"build on strengths"},
  {"id":"nd-042","cat":"strengths-and-wellbeing","type":"sort","hook":"Sort: nurtures a neurodiverse child's wellbeing, or chips at their self-worth?","items":[{"id":"a","text":"Celebrating their passions"},{"id":"b","text":"Constantly comparing them to others"},{"id":"c","text":"Praising effort and strengths"},{"id":"d","text":"Making them feel like a problem"},{"id":"e","text":"Noticing one small win out loud"},{"id":"f","text":"Sighing 'why aren't you normal'"}],"bins":[{"id":"nurture","label":"Nurtures wellbeing","valence":"pos"},{"id":"chip","label":"Chips at self-worth","valence":"neg"}],"key":{"a":"nurture","b":"chip","c":"nurture","d":"chip","e":"nurture","f":"chip"},"relearn":"Celebrating passions and praising strengths nurture wellbeing; constant comparison and 'a problem' framing chip at self-worth.","persona":"Meena","source":"nurture vs chip"},
  {"id":"nd-043","cat":"strengths-and-wellbeing","type":"strike-rewrite","hook":"\"A meltdown is my child trying to manipulate or defy me.\"","myth":{"un":"A meltdown is my child trying to manipulate or defy me.","re":"A meltdown is usually distress and overwhelm spilling over, not manipulation; your child needs co-regulation, not punishment.","why":"Overwhelm needs comfort, not consequences."},"relearn":"A meltdown is overwhelm spilling over, not manipulation; your child needs calm co-regulation, not punishment.","persona":"Meena","source":"meltdown is distress"},
  {"id":"nd-044","cat":"strengths-and-wellbeing","type":"branch","hook":"Your child is melting down and you feel your own frustration rising.","options":[{"text":"Stay calm, keep them safe, and co-regulate until the wave passes","consequence":"You help your child through the storm.","outcome":"co-regulate","best":true},{"text":"Match their dysregulation with anger","consequence":"Calm co-regulation helps the wave pass; matching it with anger escalates and frightens the child."}],"debrief":"Meet a meltdown with calm co-regulation and safety, not anger; ride out the storm together.","relearn":"Co-regulate a meltdown with calm and safety; meeting overwhelm with anger only escalates it.","persona":"Meena","source":"co-regulate"},
  {"id":"nd-045","cat":"strengths-and-wellbeing","type":"match","hook":"Match each strength to a way to nurture it.","pairs":[{"left":"An intense interest in trains","right":"Give it space and resources"},{"left":"Honesty and a strong sense of fairness","right":"Praise and model it back"},{"left":"Creative, out-of-the-box thinking","right":"Open-ended play and projects"},{"left":"Deep focus on one task","right":"Protect quiet, uninterrupted time"},{"left":"Big-picture, spatial thinking","right":"Drawing, building and maps"}],"relearn":"An intense interest, honesty, creative thinking, deep focus and spatial thinking each grow when a parent nurtures rather than discourages them.","persona":"any","source":"nurture strengths"},
  {"id":"nd-046","cat":"strengths-and-wellbeing","type":"reflect","hook":"Lensy: a neurodiverse child who feels celebrated, not just corrected, grows up liking who they are. Worth it?","prompt":"What do you think?","options":["Worth it","Celebrated","Likes who they are"],"affirm":"A neurodiverse child who feels celebrated, not constantly corrected, grows up with self-worth and confidence.","relearn":"A child who feels celebrated, not just corrected, grows up liking who they are.","persona":"Meena","source":"feel celebrated"},
  {"id":"nd-047","cat":"strengths-and-wellbeing","type":"spot","hook":"Spot the two lines that harm a neurodiverse child's wellbeing.","scene":[{"id":"a","text":"Noticing and easing their anxiety","trick":false},{"id":"b","text":"Dismissing their distress as drama","trick":true},{"id":"c","text":"Celebrating who they are","trick":false},{"id":"d","text":"'Stop being so dramatic and sit still'","trick":true},{"id":"e","text":"Sitting close until the panic passes","trick":false}],"why":"Dismissing distress as drama and demanding they 'stop being dramatic' harm wellbeing; easing anxiety, celebrating them and sitting close all support it.","relearn":"Support a neurodiverse child's wellbeing by easing anxiety and celebrating them, not dismissing their distress.","persona":"any","source":"support wellbeing"},
  {"id":"nd-048","cat":"strengths-and-wellbeing","type":"branch","hook":"Your neurodiverse child often seems anxious or down.","options":[{"text":"Take their wellbeing seriously and seek support if it persists","consequence":"You catch a co-occurring need early.","outcome":"wellbeing","best":true},{"text":"Assume it's just part of the diagnosis and ignore it","consequence":"Taking wellbeing seriously catches anxiety early; 'just the diagnosis' can miss a treatable need."}],"debrief":"Take a neurodiverse child's anxiety or low mood seriously; co-occurring needs are real.","relearn":"Don't dismiss persistent anxiety as 'just the diagnosis'; take wellbeing seriously and seek support.","persona":"Meena","source":"wellbeing matters"},
  {"id":"nd-049","cat":"strengths-and-wellbeing","type":"reflect","hook":"Lensy: your child is so much more than a diagnosis; seeing the whole, wonderful person is everything. Sit right?","prompt":"What's your take?","options":["Sits right","Whole person","More than a label"],"affirm":"A neurodiverse child is a whole, wonderful person, not a diagnosis; seeing all of them is what matters most.","relearn":"Your child is so much more than a diagnosis; seeing the whole, wonderful person is everything.","persona":"Meena","source":"whole person"},
  {"id":"nd-050","cat":"support-and-you","type":"strike-rewrite","hook":"\"A devoted parent of a neurodiverse child should run on empty and never need support.\"","myth":{"un":"A devoted parent of a neurodiverse child should run on empty and never need support.","re":"Supporting a neurodiverse child can be exhausting; looking after yourself and getting support helps you keep showing up.","why":"Your wellbeing is part of your child's support."},"relearn":"Parenting a neurodiverse child is demanding; caring for yourself and getting support is essential, not optional.","persona":"Meena","source":"your wellbeing matters"},
  {"id":"nd-051","cat":"support-and-you","type":"match","hook":"Match each support to what it offers a parent.","pairs":[{"left":"Other parents of neurodiverse kids","right":"Understanding and practical tips"},{"left":"Professionals and therapists","right":"Assessment and tailored strategies"},{"left":"Your own wellbeing care (Looking After You)","right":"Energy to keep going"},{"left":"Willing family members","right":"Extra hands and shared love"},{"left":"Tele-MANAS","right":"Free mental-health help, 14416"}],"relearn":"Peer parents, professionals, your own wellbeing care, family and Tele-MANAS each give a parent real, different support.","persona":"any","source":"the supports"},
  {"id":"nd-052","cat":"support-and-you","type":"branch","hook":"You're burning out from the daily demands and the fight for support.","options":[{"text":"Reach for support and protect your own wellbeing too","consequence":"You sustain yourself so you can sustain them.","outcome":"sustain","best":true},{"text":"Push on alone until you crash","consequence":"Reaching for support sustains you for the long haul; pushing on alone to a crash helps neither of you."}],"debrief":"Protect your wellbeing and reach for support; a sustained parent sustains their child.","relearn":"Get support and tend your wellbeing; pushing on alone to a crash serves no one (see Looking After You).","persona":"Divya","source":"sustain yourself"},
  {"id":"nd-053","cat":"support-and-you","type":"strike-rewrite","hook":"\"This game can diagnose my child or replace a professional.\"","myth":{"un":"This game can diagnose my child or replace a professional.","re":"This offers understanding and support, not diagnosis; a qualified professional assesses and guides specific care.","why":"Understanding tools point to professionals; they don't replace them."},"relearn":"This supports understanding but doesn't diagnose; a qualified professional assesses and guides your child's care.","persona":"any","source":"not a diagnosis"},
  {"id":"nd-054","cat":"support-and-you","type":"sort","hook":"Sort: a wise step for a parent, or one to rethink?","items":[{"id":"a","text":"Joining a parent support group"},{"id":"b","text":"Trying a miracle 'cure' online"},{"id":"c","text":"Seeing a qualified professional"},{"id":"d","text":"Coping in isolation and silence"},{"id":"e","text":"Being honest you need help"},{"id":"f","text":"Running on empty, alone"}],"bins":[{"id":"wise","label":"Wise step","valence":"pos"},{"id":"rethink","label":"Rethink it","valence":"neg"}],"key":{"a":"wise","b":"rethink","c":"wise","d":"rethink","e":"wise","f":"rethink"},"relearn":"Support groups, professionals and honest asks are wise; miracle 'cures', silent isolation and running on empty need a rethink.","persona":"any","source":"wise step"},
  {"id":"nd-055","cat":"support-and-you","type":"reflect","hook":"Lensy: you don't have to know everything or do it perfectly; a learning, loving, supported parent is enough. Resonate?","prompt":"What do you think?","options":["Resonates","Enough","Learning is okay"],"affirm":"A learning, loving, supported parent is exactly what a neurodiverse child needs; you don't have to be perfect or all-knowing.","relearn":"You don't have to be perfect; a learning, loving, supported parent is enough.","persona":"any","source":"enough"},
  {"id":"nd-056","cat":"support-and-you","type":"role-play","hook":"Another exhausted parent of a neurodiverse child confides they feel alone. You want to support them.","setup":"Support them warmly:","yourLine":[{"text":"\"You're not alone, and you're doing a hard job with love, let's swap what helps and lean on each other.\"","best":true},{"text":"\"Yeah, it's impossible, I don't know how anyone does it.\""}],"relearn":"Telling an isolated parent they're not alone and offering to share what helps builds the network that sustains them both.","persona":"Priya","source":"support a parent"},
  {"id":"nd-057","cat":"support-and-you","type":"spot","hook":"Spot the 2 red flags: the ways that don't sustain raising a neurodiverse child.","scene":[{"id":"a","text":"Understanding, accommodating and advocating over time","trick":false},{"id":"b","text":"Chasing a 'cure' and burning out","trick":true},{"id":"c","text":"Building a support network for you both","trick":false},{"id":"d","text":"Carrying it all alone in silence","trick":true},{"id":"e","text":"Looking after your own wellbeing too","trick":false}],"why":"Chasing a 'cure' and carrying it alone in silence are the red flags: neither sustains a parent or child.","relearn":"Understanding, accommodation, advocacy, a network and self-care sustain you; chasing a 'cure' and silent isolation don't.","persona":"any","source":"sustainable way"},
  {"id":"nd-058","cat":"support-and-you","type":"reflect","hook":"Lensy: understand, accommodate, advocate, drop the shame, and look after yourself too. Your child is lucky to have you. Ready?","prompt":"What's your take?","options":["Ready","Lucky to have me","Let's go"],"affirm":"Understanding, accommodating, advocating, dropping the shame and caring for yourself is how you raise a neurodiverse child well.","relearn":"Understand, accommodate, advocate, drop the shame, and look after yourself; that's the whole of it.","persona":"any","source":"the whole of it"},
  {"id":"nd-059","cat":"support-and-you","type":"role-play","hook":"Your co-parent struggles to accept the diagnosis and stay involved. You want to bring them in.","setup":"Bring them in gently:","yourLine":[{"text":"\"Our child needs us both to understand and support them, let's learn this together, as a team.\"","best":true},{"text":"\"Fine, I'll deal with all of it myself then.\""}],"relearn":"Inviting a co-parent to learn and support together shares the load and doubles a neurodiverse child's champions.","persona":"Vikram","source":"bring co-parent in"},
  {"id":"nd-060","cat":"understand-your-child","type":"role-play","hook":"Your child's sibling calls them 'weird'. You want to reframe it with warmth.","setup":"Reframe it warmly:","yourLine":[{"text":"\"Their brain works in its own brilliant way, different isn't weird, it's just different, and we love it.\"","best":true},{"text":"\"Yes, your sibling is a bit odd, ignore it.\""}],"relearn":"Reframing 'weird' as a different, valued way of being teaches a sibling acceptance instead of othering.","persona":"Divya","source":"reframe weird"},
  {"id":"nd-061","cat":"understand-your-child","type":"role-play","hook":"Your child asks if something is 'wrong' with them. You want to answer with love and truth.","setup":"Answer with love:","yourLine":[{"text":"\"Nothing is wrong with you, your brain just works in its own way, and that comes with real gifts.\"","best":true},{"text":"\"We're working on fixing it, don't worry.\""}],"relearn":"Telling a child nothing is wrong, their brain just works its own way with real gifts, protects their self-worth.","persona":"Meena","source":"nothing is wrong"},
  {"id":"nd-062","cat":"understand-your-child","type":"sort","hook":"Sort: an accurate understanding of neurodivergence, or a myth?","items":[{"id":"a","text":"Brains naturally vary"},{"id":"b","text":"It's contagious or a trend"},{"id":"c","text":"Every profile is individual"},{"id":"d","text":"It means low intelligence"},{"id":"e","text":"Real strengths come with it"},{"id":"f","text":"Bad parenting causes it"}],"bins":[{"id":"accurate","label":"Accurate","valence":"pos"},{"id":"myth","label":"Myth","valence":"neg"}],"key":{"a":"accurate","b":"myth","c":"accurate","d":"myth","e":"accurate","f":"myth"},"relearn":"Brains varying, individual profiles and real strengths are accurate; 'contagious, low intelligence, bad parenting' are myths.","persona":"any","source":"accurate or myth"},
  {"id":"nd-063","cat":"understand-your-child","type":"spot","hook":"Spot the two lenses that fail to help you understand your child.","scene":[{"id":"a","text":"'How does my child experience the world?'","trick":false},{"id":"b","text":"'Why won't they just act normal?'","trick":true},{"id":"c","text":"'What are their strengths and needs?'","trick":false},{"id":"d","text":"'What did I do to cause this?'","trick":true},{"id":"e","text":"'How can I support who they really are?'","trick":false}],"why":"'Why won't they act normal' and 'what did I do' don't help; asking how they experience things, their strengths and needs does.","relearn":"Understand your child by asking how they experience the world and what they need, not 'why won't they act normal' or self-blame.","persona":"Meena","source":"helpful lens"},
  {"id":"nd-064","cat":"accommodate","type":"role-play","hook":"A relative tells you to stop 'pandering' with accommodations. You want to explain calmly.","setup":"Explain calmly:","yourLine":[{"text":"\"These aren't pampering, they're like glasses, they give him fair access so he can do his best.\"","best":true},{"text":"\"Maybe you're right, I should make him tough it out.\""}],"relearn":"Framing accommodations as fair access, like glasses, defends them against the 'pandering' myth without a fight.","persona":"Vikram","source":"not pandering"},
  {"id":"nd-065","cat":"accommodate","type":"sort","hook":"Sort: respects how the child is wired, or forces them to mask?","items":[{"id":"a","text":"Letting them fidget to focus"},{"id":"b","text":"Forcing stillness and 'normal' behaviour"},{"id":"c","text":"Quiet breaks when overstimulated"},{"id":"d","text":"Punishing self-soothing"},{"id":"e","text":"Respecting their safe foods"},{"id":"f","text":"Mocking their stims till they stop"}],"bins":[{"id":"respect","label":"Respects the wiring","valence":"pos"},{"id":"mask","label":"Forces masking","valence":"neg"}],"key":{"a":"respect","b":"mask","c":"respect","d":"mask","e":"respect","f":"mask"},"relearn":"Fidgeting, quiet breaks and respected foods honour the wiring; forcing stillness, punishing self-soothing or mocking stims force masking.","persona":"Meena","source":"respect or mask"},
  {"id":"nd-066","cat":"accommodate","type":"branch","hook":"Your child copes best with strict routine, but plans change suddenly today.","options":[{"text":"Prepare them with warning and a visual of the change","consequence":"You ease a hard transition for them.","outcome":"prepared","best":true},{"text":"Spring the change and expect them to just adapt","consequence":"Warning and a visual ease a hard transition; springing change on a routine-reliant child overwhelms them."}],"debrief":"Ease sudden changes for a routine-reliant child with warning and a visual.","relearn":"Prepare a routine-reliant child for change with warning and a visual; don't spring it.","persona":"Divya","source":"ease transitions"},
  {"id":"nd-067","cat":"accommodate","type":"match","hook":"Match each tricky moment to the accommodation that helps.","pairs":[{"left":"Overwhelming party","right":"A quiet exit plan and headphones"},{"left":"New place","right":"Visit or preview it in advance"},{"left":"Big feelings","right":"A calm-down space, not a telling-off"},{"left":"Sudden change","right":"A warning and a visual of it"},{"left":"Long wait","right":"A fidget toy and a known wait-time"}],"relearn":"Parties, new places, big feelings, sudden change and long waits each go better with a simple accommodation than with force.","persona":"any","source":"moment to accommodation"},
  {"id":"nd-068","cat":"advocate","type":"role-play","hook":"You're meeting your child's teacher to request support. You want to open as a partner, not a complainer.","setup":"Open as a partner:","yourLine":[{"text":"\"I'd love to work with you so he can do his best, here's what helps him, and what could we try together?\"","best":true},{"text":"\"Your class is failing my child and it's your fault.\""}],"relearn":"Opening as a collaborative partner, with what helps, gets a teacher on side far better than blame.","persona":"Meena","source":"partner with teacher"},
  {"id":"nd-069","cat":"advocate","type":"sort","persona":"any","source":"strong or weak","hook":"Sort: strengthens your advocacy, or weakens it?","items":[{"id":"a","text":"Documenting needs and what works"},{"id":"b","text":"Giving up after one 'no'"},{"id":"c","text":"Knowing your child's legal protections"},{"id":"d","text":"Apologising for asking at all"},{"id":"e","text":"Bringing your partner to the meeting"},{"id":"f","text":"Relying only on memory in the room"}],"bins":[{"id":"strong","label":"Strengthens it","valence":"pos"},{"id":"weak","label":"Weakens it","valence":"neg"}],"key":{"a":"strong","b":"weak","c":"strong","d":"weak","e":"strong","f":"weak"},"relearn":"Documentation, knowing the law and bringing your partner strengthen advocacy; giving up, over-apologising or relying on memory weaken it."},
  {"id":"nd-070","cat":"advocate","type":"branch","hook":"A service is slow and dismissive about assessing your child.","options":[{"text":"Persist politely, follow up, and seek another route if needed","consequence":"You keep the path to support open.","outcome":"persist","best":true},{"text":"Give up and assume nothing is available","consequence":"Persistence and alternate routes keep support reachable; giving up assumes a 'no' that may not be final."}],"debrief":"Persist politely and seek other routes when a service is slow; don't give up on the support needed.","relearn":"Keep advocating through slow services; one dismissal isn't the end of the road to support.","persona":"Divya","source":"persist politely"},
  {"id":"nd-071","cat":"advocate","type":"match","persona":"Meena","source":"right to place","hook":"Match each right or support to where it applies.","pairs":[{"left":"Reasonable accommodation","right":"School and services"},{"left":"A learning-support plan","right":"The classroom"},{"left":"Family understanding","right":"The home and gatherings"},{"left":"Exam concessions on assessment","right":"The exam board"},{"left":"Tailored strategies","right":"A qualified professional"}],"relearn":"Reasonable accommodation, a support plan, family understanding, exam concessions and tailored strategies each apply where your child needs championing."},
  {"id":"nd-072","cat":"drop-the-shame","type":"role-play","hook":"A relative whispers that your child's diagnosis is 'a punishment' or 'karma'. You want to shut it down kindly.","setup":"Shut it down kindly:","yourLine":[{"text":"\"It's no one's fault and no punishment, it's just how his brain works, and he's wonderful.\"","best":true},{"text":"\"Maybe, I do wonder what we did wrong.\""}],"relearn":"Naming that it's no one's fault and no punishment protects both you and your child from cruel, baseless blame.","persona":"Meena","source":"no punishment"},
  {"id":"nd-073","cat":"drop-the-shame","type":"sort","hook":"Sort each statement: a true, shame-lifting line, or a harmful blame myth.","items":[{"id":"a","text":"'You didn't cause this'"},{"id":"b","text":"'Bad mothers raise such kids'"},{"id":"c","text":"'Your child can thrive'"},{"id":"d","text":"'Hide it from everyone'"},{"id":"e","text":"'It's no one's fault'"},{"id":"f","text":"'It's karma for past sins'"}],"bins":[{"id":"true","label":"True, lifts shame","valence":"pos"},{"id":"blame","label":"Harmful blame","valence":"neg"}],"key":{"a":"true","b":"blame","c":"true","d":"blame","e":"true","f":"blame"},"relearn":"'You didn't cause this', 'your child can thrive' and 'no one's fault' lift shame; blaming mothers, 'hide it' and 'karma' are harmful.","persona":"any","source":"true or blame"},
  {"id":"nd-074","cat":"drop-the-shame","type":"spot","hook":"Spot the two moves that keep a family stuck in shame.","scene":[{"id":"a","text":"Accepting it's no one's fault","trick":false},{"id":"b","text":"Blaming yourself endlessly","trick":true},{"id":"c","text":"Focusing energy on support","trick":false},{"id":"d","text":"Hiding him so neighbours don't talk","trick":true},{"id":"e","text":"Telling him he's wonderful as he is","trick":false}],"why":"Endless self-blame and hiding the child keep a family stuck; accepting it's no one's fault and focusing on support free them.","relearn":"Catch the stuck-in-shame moves, self-blame and hiding; freedom comes from 'no one's fault' and focusing on support.","persona":"any","source":"catch the stuck moves"},
  {"id":"nd-075","cat":"drop-the-shame","type":"branch","hook":"You feel pressure to keep your child's diagnosis a secret from everyone.","options":[{"text":"Share it on your own terms with people who can support you","consequence":"You let understanding and help in.","outcome":"share","best":true},{"text":"Keep it hidden and carry it alone","consequence":"Sharing on your terms lets in understanding and help; total secrecy isolates you and reinforces stigma."}],"debrief":"Share the diagnosis on your own terms with supportive people; secrecy isolates you and feeds stigma.","relearn":"Choose openness on your terms over secrecy; hiding it carries the shame it's trying to avoid.","persona":"Vikram","source":"share on your terms"},
  {"id":"nd-076","cat":"strengths-and-wellbeing","type":"role-play","hook":"Your child is fixated on one topic and others call it 'obsessive'. You want to honour it.","setup":"Honour the passion:","yourLine":[{"text":"\"That deep interest is a strength, let's feed it, it might become something amazing for you.\"","best":true},{"text":"\"Enough of that, talk about normal things.\""}],"relearn":"Honouring an intense interest as a strength to feed builds confidence, unlike dismissing it as 'obsessive'.","persona":"Meena","source":"honour the passion"},
  {"id":"nd-077","cat":"strengths-and-wellbeing","type":"role-play","hook":"After a meltdown has passed, your child seems ashamed. You want to reconnect with warmth.","setup":"Reconnect warmly:","yourLine":[{"text":"\"That was a hard moment and it's over, you're not in trouble, I'm here and I love you.\"","best":true},{"text":"\"See what happens when you don't control yourself?\""}],"relearn":"Reconnecting after a meltdown with reassurance, not reproach, rebuilds safety and self-worth.","persona":"Meena","source":"reconnect after meltdown"},
  {"id":"nd-078","cat":"strengths-and-wellbeing","type":"sort","hook":"Sort: builds a neurodiverse child's confidence, or erodes it?","items":[{"id":"a","text":"Naming what they're great at"},{"id":"b","text":"Only ever pointing out problems"},{"id":"c","text":"Celebrating small wins"},{"id":"d","text":"Comparing them to 'normal' kids"},{"id":"e","text":"Trusting them with a real task"},{"id":"f","text":"Mocking how they speak or move"}],"bins":[{"id":"build","label":"Builds confidence","valence":"pos"},{"id":"erode","label":"Erodes it","valence":"neg"}],"key":{"a":"build","b":"erode","c":"build","d":"erode","e":"build","f":"erode"},"relearn":"Naming strengths and celebrating wins build confidence; problem-only focus and comparisons erode it.","persona":"any","source":"build or erode"},
  {"id":"nd-079","cat":"strengths-and-wellbeing","type":"match","hook":"Match each sign to what your child may need.","pairs":[{"left":"Overwhelmed and melting down","right":"Calm, co-regulation, less stimulation"},{"left":"Anxious before a change of plan","right":"Preparation and reassurance"},{"left":"Lighting up over an interest","right":"Encouragement and space"},{"left":"Ashamed after a hard moment","right":"Reconnection, not reproach"},{"left":"Low and withdrawn for weeks","right":"Taken seriously, maybe support"}],"relearn":"Overwhelm, anxiety, a lit-up interest, post-meltdown shame and lasting low mood each tell you what your child needs.","persona":"Meena","source":"sign to need"},
  {"id":"nd-080","cat":"strengths-and-wellbeing","type":"spot","hook":"Spot the two lines that erode a neurodiverse child's self-worth.","scene":[{"id":"a","text":"Seeing and naming their gifts","trick":false},{"id":"b","text":"Treating them as a list of deficits","trick":true},{"id":"c","text":"Loving them for exactly who they are","trick":false},{"id":"d","text":"'You're nothing but trouble for me'","trick":true},{"id":"e","text":"Telling them you're proud of them","trick":false}],"why":"Treating a child as a list of deficits and calling them 'nothing but trouble' erode self-worth; seeing their gifts, loving and praising them build it.","relearn":"Nurture a neurodiverse child's self-worth by seeing their gifts and loving who they are, not listing deficits.","persona":"Meena","source":"nurture self-worth"},
  {"id":"nd-081","cat":"support-and-you","type":"role-play","hook":"You're exhausted and a friend asks how you really are. You want to be honest, not brush it off.","setup":"Be honest:","yourLine":[{"text":"\"Honestly, it's hard and I'm tired, I love him fiercely and I could use some support too.\"","best":true},{"text":"\"Oh, we're totally fine, no problems at all.\""}],"relearn":"Being honest that it's hard and you need support opens the door to the help that sustains you for your child.","persona":"Divya","source":"be honest"},
  {"id":"nd-082","cat":"support-and-you","type":"sort","hook":"Sort: sustains a parent for the long haul, or burns them out?","items":[{"id":"a","text":"Sharing the load and resting"},{"id":"b","text":"Doing everything alone, always"},{"id":"c","text":"Leaning on a support network"},{"id":"d","text":"Never asking for help"},{"id":"e","text":"Taking short breaks to recharge"},{"id":"f","text":"Ignoring your own needs entirely"}],"bins":[{"id":"sustain","label":"Sustains you","valence":"pos"},{"id":"burn","label":"Burns you out","valence":"neg"}],"key":{"a":"sustain","b":"burn","c":"sustain","d":"burn","e":"sustain","f":"burn"},"relearn":"Sharing the load, a network and short breaks sustain you; doing it all alone, never asking and ignoring your needs burn you out.","persona":"any","source":"sustain or burn"},
  {"id":"nd-083","cat":"support-and-you","type":"match","hook":"Match a parent need to the support for it.","pairs":[{"left":"Feeling alone","right":"A parent support group"},{"left":"Needing strategies","right":"A professional or therapist"},{"left":"Running on empty","right":"Your own wellbeing care (g63)"},{"left":"Unsure about a diagnosis","right":"A qualified assessment"},{"left":"A low night you can't shake","right":"Tele-MANAS, 14416"}],"relearn":"Loneliness, strategies, empty energy, diagnosis doubts and a low night each have a support that fits.","persona":"any","source":"need to support"},
  {"id":"nd-084","cat":"support-and-you","type":"role-play","hook":"Your child's grandparent wants to help but doesn't understand the diagnosis. You want to guide them in.","setup":"Guide them in warmly:","yourLine":[{"text":"\"Here's a simple way to understand him, and here's exactly how you can help, he adores you.\"","best":true},{"text":"\"Just don't get involved if you don't understand it.\""}],"relearn":"Warmly explaining and giving a concrete way to help turns a willing grandparent into real support, not a closed door.","persona":"Priya","source":"guide grandparent"},
  {"id":"nd-900","cat":"accommodate","type":"strike-rewrite","hook":"\"A bright tube-light, blaring TV and crowd are fine; he should just get used to it.\"","myth":{"un":"A bright tube-light, blaring TV and crowd are fine; he should just get used to it.","re":"Dimming lights, lowering noise and easing the crowd lets an overloaded child cope; you adjust the setting, not the child.","why":"You flex the room, not the wiring."},"relearn":"Lower the lights, sound and crowd for an overloaded child; adjust the setting, not the child.","persona":"Meena","source":"dial down the room"},
  {"id":"nd-901","cat":"accommodate","type":"strike-rewrite","hook":"\"Letting him wear headphones in the market is babying him; he must toughen up.\"","myth":{"un":"Letting him wear headphones in the market is babying him; he must toughen up.","re":"Noise-cancelling headphones aren't babying; they cut painful sensory overload so he can actually be there with you.","why":"They turn down pain, not effort."},"relearn":"Headphones in a loud market aren't babying; they cut sensory overload so your child can cope and stay.","persona":"Meena","source":"headphones not babying"},
  {"id":"nd-902","cat":"accommodate","type":"strike-rewrite","hook":"\"Only fussy children need special food; he must finish whatever is served.\"","myth":{"un":"Only fussy children need special food; he must finish whatever is served.","re":"Some textures and smells genuinely overwhelm a child's senses; respecting food needs isn't fussiness, it's accommodation.","why":"A real sensory need isn't a tantrum."},"relearn":"Respecting your child's food textures isn't pampering fussiness; it honours a real sensory need.","persona":"Divya","source":"food needs not fussy"},
  {"id":"nd-903","cat":"accommodate","type":"strike-rewrite","hook":"\"He should learn to do homework in one long sitting like everyone else.\"","myth":{"un":"He should learn to do homework in one long sitting like everyone else.","re":"Breaking work into short chunks with movement breaks matches how his attention is wired and gets more done, not less.","why":"Chunks fit the wiring, not laziness."},"relearn":"Chunk homework into short steps with movement breaks; it fits how attention is wired and gets more done.","persona":"Meena","source":"chunk the work"},
  {"id":"nd-904","cat":"accommodate","type":"strike-rewrite","hook":"\"A calm-down corner at home just rewards bad behaviour.\"","myth":{"un":"A calm-down corner at home just rewards bad behaviour.","re":"A calm-down space gives an overwhelmed child somewhere safe to settle; it isn't a reward, it's a place to regulate.","why":"Settling isn't the same as a treat."},"relearn":"A calm-down corner isn't rewarding bad behaviour; it gives an overwhelmed child a safe place to regulate.","persona":"Meena","source":"calm corner not reward"},
  {"id":"nd-905","cat":"accommodate","type":"strike-rewrite","hook":"\"If I let him stim and fidget, he'll never learn to sit properly.\"","myth":{"un":"If I let him stim and fidget, he'll never learn to sit properly.","re":"Stimming and fidgeting often help a child self-regulate and focus; allowing them supports him rather than holding him back.","why":"The movement is helping, not hindering."},"relearn":"Letting your child stim and fidget often helps them regulate and focus; it supports them, not spoils them.","persona":"Vikram","source":"stim helps focus"},
  {"id":"nd-906","cat":"accommodate","type":"strike-rewrite","hook":"\"Forcing him to look me in the eye when I talk teaches respect.\"","myth":{"un":"Forcing him to look me in the eye when I talk teaches respect.","re":"For many autistic children eye contact is overwhelming; he can listen well without it, and forcing it only adds stress.","why":"Listening doesn't need a forced gaze."},"relearn":"Don't force eye contact; many autistic children listen better without it, and forcing it only adds stress.","persona":"Meena","source":"eye contact not forced"},
  {"id":"nd-907","cat":"accommodate","type":"strike-rewrite","hook":"\"Surprises build flexibility, so I shouldn't warn him before plans change.\"","myth":{"un":"Surprises build flexibility, so I shouldn't warn him before plans change.","re":"A warning and a simple visual before a change let a routine-reliant child adjust; surprise just floods him with overwhelm.","why":"A heads-up eases change, it doesn't weaken him."},"relearn":"Warn a routine-reliant child before changes with a heads-up and a visual; surprise floods them, not strengthens them.","persona":"Divya","source":"warn before change"},
  {"id":"nd-908","cat":"accommodate","type":"strike-rewrite","hook":"\"Other kids manage school uniforms and tags, so his complaints are drama.\"","myth":{"un":"Other kids manage school uniforms and tags, so his complaints are drama.","re":"Scratchy tags and seams can feel genuinely painful to a sensory-sensitive child; softer clothes or removed tags is real relief.","why":"His skin truly feels it differently."},"relearn":"Scratchy tags can genuinely hurt a sensory-sensitive child; softer clothes or removed tags is real relief, not drama.","persona":"any","source":"clothing sensitivity"},
  {"id":"nd-909","cat":"accommodate","type":"strike-rewrite","hook":"\"Giving him a visual timetable means he'll never cope without one.\"","myth":{"un":"Giving him a visual timetable means he'll never cope without one.","re":"A visual schedule lowers the daily anxiety of not-knowing, and that security is what coping skills grow from over time.","why":"Security is the launchpad for coping."},"relearn":"A visual timetable lowers daily anxiety; that security is exactly what real coping skills grow from.","persona":"Meena","source":"visual timetable security"},
  {"id":"nd-910","cat":"accommodate","type":"strike-rewrite","hook":"\"A quiet exit from the wedding is rude; he must sit through the whole function.\"","myth":{"un":"A quiet exit from the wedding is rude; he must sit through the whole function.","re":"Planning a quiet exit lets an overstimulated child leave before a meltdown; it prevents overload, it isn't bad manners.","why":"Leaving early beats a forced breakdown."},"relearn":"A planned quiet exit from a loud function prevents overload for an overstimulated child; it isn't rudeness.","persona":"any","source":"quiet exit plan"},
  {"id":"nd-911","cat":"accommodate","type":"sort","hook":"Sort: a supportive accommodation, or forcing the child to mask who they are?","items":[{"id":"a","text":"Noise-cancelling headphones in a loud hall"},{"id":"b","text":"Punishing him for flapping his hands"},{"id":"c","text":"A visual schedule for the day"},{"id":"d","text":"Demanding he hold eye contact"},{"id":"e","text":"A movement break between tasks"},{"id":"f","text":"Forcing him to sit perfectly still"}],"bins":[{"id":"support","label":"Supportive accommodation","valence":"pos"},{"id":"mask","label":"Forcing masking","valence":"neg"}],"key":{"a":"support","b":"mask","c":"support","d":"mask","e":"support","f":"mask"},"relearn":"Headphones, visual schedules and movement breaks support; punishing stimming or forcing eye contact and stillness force masking.","persona":"Meena","source":"support vs mask six"},
  {"id":"nd-912","cat":"accommodate","type":"sort","hook":"Sort: respects how the child is wired, or forces them to mask it?","items":[{"id":"a","text":"Letting her fidget with a spinner to focus"},{"id":"b","text":"Forcing 'normal' stillness in class"},{"id":"c","text":"Quiet breaks when she's overstimulated"},{"id":"d","text":"Punishing her for rocking to self-soothe"},{"id":"e","text":"Respecting her need for the same lunch"},{"id":"f","text":"Mocking her hand-flapping till she stops"}],"bins":[{"id":"respect","label":"Respects the wiring","valence":"pos"},{"id":"mask","label":"Forces masking","valence":"neg"}],"key":{"a":"respect","b":"mask","c":"respect","d":"mask","e":"respect","f":"mask"},"relearn":"Fidget tools, quiet breaks and respected routines honour the wiring; forcing stillness or punishing self-soothing force masking.","persona":"Meena","source":"respect or mask six"},
  {"id":"nd-913","cat":"accommodate","type":"sort","hook":"Sort: a sensory accommodation that helps, or piling on more sensory load?","items":[{"id":"a","text":"Dimming a harsh tube-light"},{"id":"b","text":"Turning the TV up over his protest"},{"id":"c","text":"Soft tags-removed clothes"},{"id":"d","text":"A crowded, noisy surprise outing"},{"id":"e","text":"A quiet low-stimulation corner"},{"id":"f","text":"Strong perfume in a small room"}],"bins":[{"id":"eases","label":"Eases the senses","valence":"pos"},{"id":"overloads","label":"Overloads the senses","valence":"neg"}],"key":{"a":"eases","b":"overloads","c":"eases","d":"overloads","e":"eases","f":"overloads"},"relearn":"Dimming lights, soft clothes and a quiet corner ease the senses; loud TV, surprise crowds and strong smells pile on overload.","persona":"any","source":"ease vs overload senses"},
  {"id":"nd-914","cat":"accommodate","type":"match","hook":"Match each need to a practical home accommodation that helps.","pairs":[{"left":"Sensory overload","right":"A calm, low-stimulation corner"},{"left":"Trouble with transitions","right":"A warning and a visual routine"},{"left":"Attention differences","right":"Short steps and movement breaks"},{"left":"Food sensitivities","right":"Respect safe foods, no forcing"},{"left":"Loud outings","right":"Noise-cancelling headphones"}],"relearn":"Sensory overload, transitions, attention, food needs and loud outings each have a simple home accommodation that helps.","persona":"any","source":"need to accommodation five"},
  {"id":"nd-915","cat":"accommodate","type":"match","hook":"Match each daily setting to the accommodation that helps it go better.","pairs":[{"left":"Mealtimes","right":"Respect food sensitivities, no force"},{"left":"Bedtime","right":"A predictable, calming routine"},{"left":"Homework","right":"Chunked tasks and breaks"},{"left":"Morning rush","right":"A visual step-by-step checklist"},{"left":"Bath time","right":"Warn first, control water and light"}],"relearn":"Meals, bedtime, homework, mornings and bath time each go better with an accommodation that fits the child's wiring.","persona":"any","source":"setting to support five"},
  {"id":"nd-916","cat":"accommodate","type":"match","hook":"Match each tricky moment out and about to the accommodation that helps.","pairs":[{"left":"Overwhelming party","right":"A quiet exit plan and headphones"},{"left":"New place","right":"Preview or visit it in advance"},{"left":"Big feelings","right":"A calm-down space, not a scolding"},{"left":"Long queue","right":"A fidget toy and a known wait-time"},{"left":"Crowded bus","right":"A window seat and a calm playlist"}],"relearn":"Parties, new places, big feelings, queues and crowded buses each go better with a simple accommodation than with force.","persona":"any","source":"moment to accommodation five"},
  {"id":"nd-917","cat":"accommodate","type":"match","hook":"Match each sense that overloads your child to a way to ease it.","pairs":[{"left":"Bright glare","right":"Dim lights or a cap with a brim"},{"left":"Sudden loud noise","right":"Headphones or a warning first"},{"left":"Scratchy fabric","right":"Soft clothes with tags removed"},{"left":"Strong smells","right":"Air a room or move spots"},{"left":"Busy visuals","right":"A plain, uncluttered corner"}],"relearn":"Glare, loud noise, scratchy fabric, strong smells and busy visuals each have a simple way to ease the overload.","persona":"any","source":"sense to relief"},
  {"id":"nd-918","cat":"accommodate","type":"branch","hook":"A loud, crowded birthday party your child finds overwhelming.","options":[{"text":"Go prepared: headphones, a quiet-room plan and an early exit","consequence":"You set him up to enjoy it and leave before overload hits.","outcome":"prepared","best":true},{"text":"Make him stay the whole time to 'get used to it'","consequence":"Forcing him to endure it floods an overwhelmed child; supports would have helped."}],"debrief":"Join overwhelming events with supports and an exit plan, not forced endurance.","relearn":"Bring supports and an exit plan to loud events; don't force a child to endure overload.","persona":"Meena","source":"party prepared"},
  {"id":"nd-919","cat":"accommodate","type":"branch","hook":"Your child does homework better with breaks, but relatives call it 'making excuses'.","options":[{"text":"Keep the chunked steps and breaks that work for him","consequence":"You stick with what fits his wiring and he finishes more.","outcome":"chunked","best":true},{"text":"Drop the breaks to look strict for relatives","consequence":"Dropping what fits his attention to please relatives makes the work harder, not better."}],"debrief":"Keep the chunked steps and breaks that fit your child, whatever onlookers say.","relearn":"Keep the breaks and chunked steps that fit your child's attention, whatever relatives say.","persona":"Meena","source":"keep what works"},
  {"id":"nd-920","cat":"accommodate","type":"branch","hook":"Bedtime is a nightly battle; your child seems to need the same routine each night.","options":[{"text":"Build a predictable visual bedtime routine and keep it steady","consequence":"The sameness lowers his anxiety and bedtime gets easier.","outcome":"routine","best":true},{"text":"Change the routine nightly to 'teach flexibility'","consequence":"Changing it every night floods a child who relies on knowing what's next."}],"debrief":"A steady, predictable bedtime routine lowers anxiety better than nightly change.","relearn":"A predictable bedtime routine lowers anxiety; nightly change just leaves your child unsettled.","persona":"Divya","source":"steady bedtime"},
  {"id":"nd-921","cat":"accommodate","type":"branch","hook":"At the mall your child melts down from the lights, noise and crowd.","options":[{"text":"Move him to a quiet spot and let him settle, supports out","consequence":"You meet his overwhelm with calm and he recovers.","outcome":"settle","best":true},{"text":"Scold him to stop and drag him on to shop","consequence":"Scolding an overwhelmed child only deepens the overload; a quiet spot would have settled him."}],"debrief":"Meet a sensory meltdown by reducing the load and helping him settle, not by scolding.","relearn":"Meet a sensory meltdown by moving to calm and easing the load; scolding only deepens overwhelm.","persona":"Meena","source":"mall meltdown"},
  {"id":"nd-922","cat":"accommodate","type":"branch","hook":"You set up one fixed sensory kit, but lately it isn't helping much.","options":[{"text":"Watch and ask him, then adjust the supports to what helps now","consequence":"You keep the kit tuned to your real, changing child.","outcome":"tailored","best":true},{"text":"Insist the old kit must work, as an article said","consequence":"A generic kit ignores his cues today; watching and adjusting would fit him."}],"debrief":"Keep tuning accommodations to your real, changing child by watching and asking.","relearn":"Tune accommodations to your real child by watching and asking; needs change, so a fixed kit drifts off.","persona":"Divya","source":"retune the kit"},
  {"id":"nd-923","cat":"accommodate","type":"branch","hook":"A new school term starts and the layout, teacher and timetable have all changed.","options":[{"text":"Preview the new room, teacher and routine with him beforehand","consequence":"He walks in already knowing what to expect and feels safer.","outcome":"preview","best":true},{"text":"Let him face it all cold so he 'adapts on the spot'","consequence":"Facing every change cold at once overwhelms a routine-reliant child; a preview would ease it."}],"debrief":"Ease a big transition by previewing the new place and routine in advance.","relearn":"Preview a new term's room, teacher and routine in advance to ease the transition.","persona":"Meena","source":"preview new term"},
  {"id":"nd-924","cat":"accommodate","type":"reflect","hook":"Lensy: noise-cancelling headphones at the party aren't him 'avoiding' the family. They're how he stays in the room with you. Sit right?","prompt":"What do you think?","options":["Sits right","Lets him stay","Not avoidance"],"affirm":"A tool that lowers sensory overload keeps a child present and connected, instead of forcing a choice between coping and being there.","relearn":"An accommodation like headphones isn't withdrawal. It's what lets a child stay in the room and join in.","persona":"Meena","source":"headphones stay in room"},
  {"id":"nd-925","cat":"accommodate","type":"reflect","hook":"Lensy: accommodations are like glasses, they give fair access, not an unfair edge. Does that frame help you?","prompt":"What do you think?","options":["Like glasses","Fair access","Levels the ground"],"affirm":"Accommodations level the ground so your child gets the same fair chance as others; fair access isn't an unfair advantage.","relearn":"Accommodations are like glasses: they give fair access and level the ground, not an unfair edge.","persona":"Vikram","source":"glasses frame"},
  {"id":"nd-926","cat":"accommodate","type":"reflect","hook":"Lensy: you know your child best, so watching and asking them often beats any generic checklist. Ring true?","prompt":"What do you think?","options":["Rings true","Watch and ask","My real child"],"affirm":"Tuning support to your real child by watching their cues and asking them works better than any one-size checklist.","relearn":"Watching and asking your own child tailors support better than a generic checklist ever could.","persona":"Divya","source":"watch and ask reflect"},
  {"id":"nd-927","cat":"accommodate","type":"reflect","hook":"Lensy: a meltdown in an overwhelming place is overwhelm, not bad behaviour to punish. Does that sit right?","prompt":"What do you think?","options":["Sits right","It's overwhelm","Not misbehaviour"],"affirm":"A meltdown in an overloading setting is a nervous system flooded, not defiance; preventing overload helps far more than punishing it.","relearn":"A meltdown in an overwhelming place is overwhelm, not misbehaviour to punish.","persona":"Meena","source":"overwhelm not behaviour"},
  {"id":"nd-928","cat":"accommodate","type":"reflect","hook":"Lensy: adjusting the room, the plan and your expectations is gentler than asking a child to mask all day. Agree?","prompt":"What do you think?","options":["Agree","Flex the setting","Not the child"],"affirm":"It's kinder and it works better to flex the environment and your expectations than to demand a child mask who they are.","relearn":"Flex the room, the plan and your expectations rather than asking your child to mask all day.","persona":"Meena","source":"flex not mask reflect"},
  {"id":"nd-929","cat":"accommodate","type":"reflect","hook":"Lensy: respecting your child's food, clothing and noise needs honours a real sensory truth, not fussiness. Sit right?","prompt":"What do you think?","options":["Sits right","A real need","Not fussiness"],"affirm":"Sensory needs around food, fabric and sound are genuine; respecting them is accommodation, not giving in to fussiness.","relearn":"Respecting food, clothing and noise needs honours a real sensory truth, not fussiness.","persona":"any","source":"sensory needs reflect"},
  {"id":"nd-930","cat":"accommodate","type":"reflect","hook":"Lensy: the support you give now is the launchpad real coping grows from, not a crutch. Does that land?","prompt":"What do you think?","options":["It lands","A launchpad","Not a crutch"],"affirm":"Accommodation builds the security and skills from which real coping grows; forced distress teaches fear, not coping.","relearn":"Support is the launchpad real coping grows from, not a crutch.","persona":"Vikram","source":"launchpad reflect"},
  {"id":"nd-931","cat":"accommodate","type":"spot","hook":"Spot the two moves that force your child to mask, not accommodate them.","scene":[{"id":"a","text":"Offering headphones in a loud hall","trick":false},{"id":"b","text":"Punishing him for hand-flapping to self-soothe","trick":true},{"id":"c","text":"Giving a clear visual schedule","trick":false},{"id":"d","text":"Forcing him to hold eye contact","trick":true},{"id":"e","text":"A quiet break when overstimulated","trick":false}],"why":"Punishing stimming and forcing eye contact make a child mask; the other three adjust the setting to support him.","relearn":"Punishing stimming and forcing eye contact force masking; headphones, schedules and quiet breaks accommodate.","persona":"Meena","source":"spot the masking"},
  {"id":"nd-932","cat":"accommodate","type":"spot","hook":"Spot the two responses that overload your child instead of easing the moment.","scene":[{"id":"a","text":"Dimming the harsh lights when he winces","trick":false},{"id":"b","text":"Turning the loud TV up over his protest","trick":true},{"id":"c","text":"Warning him before the plan changes","trick":false},{"id":"d","text":"Springing a surprise crowd on him","trick":true},{"id":"e","text":"Offering a quiet corner to settle","trick":false}],"why":"Blasting the TV and a surprise crowd pile on overload; dimming lights, a warning and a quiet corner ease it.","relearn":"Loud TV and surprise crowds overload a child; dimming lights, warnings and a quiet corner ease the moment.","persona":"any","source":"spot the overload"},
  {"id":"nd-933","cat":"accommodate","type":"spot","hook":"Spot the two 'tough-love' moves that harm an overwhelmed child, not support them.","scene":[{"id":"a","text":"Letting him leave a function early when flooded","trick":false},{"id":"b","text":"Scolding him to stop a sensory meltdown","trick":true},{"id":"c","text":"Respecting his safe foods at dinner","trick":false},{"id":"d","text":"Making him sit perfectly still","trick":true},{"id":"e","text":"Breaking homework into short chunks","trick":false}],"why":"Scolding a meltdown and forcing stillness punish overwhelm; a quiet exit, safe foods and chunks support him.","relearn":"Scolding meltdowns and forcing stillness harm a child; quiet exits, safe foods and chunks support them.","persona":"Meena","source":"spot the tough-love harm"},
  {"id":"nd-934","cat":"accommodate","type":"role-play","hook":"A relative says you 'pamper' your son with headphones and special food. You want to explain calmly.","setup":"Explain calmly:","yourLine":[{"text":"\"These aren't pampering, they're like his glasses; they give fair access so he can be his best.\"","best":true},{"text":"\"Maybe you're right, I should just make him manage like everyone else.\""}],"relearn":"Framing accommodations as fair access, like glasses, defends them calmly against the 'pampering' charge.","persona":"Vikram","source":"not pampering"},
  {"id":"nd-935","cat":"accommodate","type":"role-play","hook":"At a family lunch a cousin laughs at your daughter's fidget spinner. You want to step in gently.","setup":"Step in gently:","yourLine":[{"text":"\"That's her focus tool, like my reading glasses; it helps her settle, so let's leave it with her.\"","best":true},{"text":"\"Sorry, she shouldn't have it here, I'll take it away.\""}],"relearn":"Naming a fidget tool as a focus aid, calmly, protects your child's support from being mocked away.","persona":"any","source":"defend fidget tool"},
  {"id":"nd-936","cat":"accommodate","type":"role-play","hook":"Grandma insists your son must look her in the eye to greet her 'properly'. You want to ease it.","setup":"Ease it warmly:","yourLine":[{"text":"\"He's listening even without eye contact, Amma; for him a wave is a warm hello, and that's enough.\"","best":true},{"text":"\"Look at your grandmother right now, or no greeting is fine.\""}],"relearn":"Gently explaining that listening doesn't need eye contact protects your child from a stressful forced gaze.","persona":"Meena","source":"eye contact with elders"},
  {"id":"nd-937","cat":"accommodate","type":"role-play","hook":"At a noisy wedding your child is near overload. You want to suggest a quiet exit to your partner.","setup":"Suggest calmly:","yourLine":[{"text":"\"He's getting overloaded; let's slip out to the quiet courtyard for a bit before it tips over.\"","best":true},{"text":"\"He has to sit through the whole thing, it would look rude to leave.\""}],"relearn":"Calmly proposing a quiet exit prevents overload at a loud event instead of forcing a child to the breaking point.","persona":"any","source":"propose quiet exit"},
  {"id":"nd-938","cat":"accommodate","type":"role-play","hook":"Your child is melting down at a shop; a stranger snaps that he needs 'a good scolding'. You stay calm.","setup":"Respond steadily:","yourLine":[{"text":"\"He's overwhelmed, not naughty; he needs calm, not a scolding, so we'll just give him a moment.\"","best":true},{"text":"\"You're right, sorry, I'll sort his behaviour out at once.\""}],"relearn":"Naming a meltdown as overwhelm, not naughtiness, holds your ground against onlookers and protects your child.","persona":"Meena","source":"overwhelm not naughty stranger"},
  {"id":"nd-990","cat":"advocate","type":"strike-rewrite","persona":"Meena","source":"partnership not interference","hook":"\"The teacher knows best; questioning her makes me an interfering parent.\"","myth":{"un":"The teacher knows best; questioning her makes me an interfering parent.","re":"You know your child best; teaming up with the teacher and sharing what works is partnership, not interference.","why":"You're both on the same side."},"relearn":"You know your child best; teaming up and sharing what works is partnership, not interference."},
  {"id":"nd-991","cat":"advocate","type":"strike-rewrite","persona":"Meena","source":"record opens doors","hook":"\"A diagnosis on the school record will only get my child labelled and held back.\"","myth":{"un":"A diagnosis on the record will only get my child labelled and held back.","re":"On record, a diagnosis unlocks the accommodations the law entitles your child to; it opens doors, not closes them.","why":"It's a key to support, not a brand."},"relearn":"On record, a diagnosis unlocks accommodations; it opens doors, it doesn't brand your child."},
  {"id":"nd-992","cat":"advocate","type":"strike-rewrite","persona":"Vikram","source":"concessions fair access","hook":"\"If I ask for exam concessions, people will say my child gets an unfair edge.\"","myth":{"un":"If I ask for exam concessions, people will say my child gets an unfair edge.","re":"Concessions like extra time or a scribe are fair access, like glasses; they let your child show what they know.","why":"Fair access isn't an advantage."},"relearn":"Exam concessions are fair access, like glasses; they let your child show what they truly know."},
  {"id":"nd-993","cat":"advocate","type":"strike-rewrite","persona":"Meena","source":"inclusion is a right","hook":"\"Special schools are the only option; a regular school can never include my child.\"","myth":{"un":"Special schools are the only option; a regular school can never include my child.","re":"The law backs inclusive education; many regular schools can include your child with the right support, if you ask.","why":"Inclusion is a right, not a favour."},"relearn":"The law backs inclusive education; many regular schools can include your child with support."},
  {"id":"nd-994","cat":"advocate","type":"strike-rewrite","persona":"Divya","source":"don't wait","hook":"\"I should wait until my child is older before raising this with the school.\"","myth":{"un":"I should wait until my child is older before raising this with the school.","re":"Earlier support helps more; raising it now, calmly, gets help in place sooner than losing years to waiting.","why":"Early support beats lost years."},"relearn":"Earlier support helps more; raising needs now gets help in place sooner than waiting."},
  {"id":"nd-995","cat":"advocate","type":"strike-rewrite","persona":"Vikram","source":"support not strictness","hook":"\"Elders say therapy is a waste of money; we should just be stricter at home.\"","myth":{"un":"Elders say therapy is a waste of money; we should just be stricter at home.","re":"You can't discipline neurodivergence away; the right professional support builds skills that strictness never will.","why":"Support teaches; strictness only frightens."},"relearn":"You can't discipline neurodivergence away; professional support builds skills strictness can't."},
  {"id":"nd-996","cat":"advocate","type":"strike-rewrite","persona":"Meena","source":"writing protects plan","hook":"\"A written request will make the teacher think I don't trust her.\"","myth":{"un":"A written request will make the teacher think I don't trust her.","re":"A calm written request isn't distrust; it gives the teacher a clear record to act on and protects your child's plan.","why":"In writing, support isn't forgotten."},"relearn":"A calm written request isn't distrust; it gives a clear record and protects your child's plan."},
  {"id":"nd-997","cat":"advocate","type":"strike-rewrite","persona":"Divya","source":"bright still needs support","hook":"\"My child is bright, so asking for learning support is just making excuses.\"","myth":{"un":"My child is bright, so asking for learning support is just making excuses.","re":"A bright child can still have dyslexia or ADHD; support isn't an excuse, it lets that brightness show in school.","why":"Support and ability aren't opposites."},"relearn":"A bright child can still have dyslexia or ADHD; support lets their brightness show, it's no excuse."},
  {"id":"nd-998","cat":"advocate","type":"strike-rewrite","persona":"Meena","source":"one no isn't final","hook":"\"If the principal says no once, that's final and there's nothing more I can do.\"","myth":{"un":"If the principal says no once, that's final and there's nothing I can do.","re":"One 'no' isn't the end; you can put it in writing, ask whom to approach next, or seek another school, calmly.","why":"A first 'no' is rarely the last word."},"relearn":"One 'no' isn't the end; put it in writing, ask whom to approach next, or seek another route."},
  {"id":"nd-999","cat":"advocate","type":"strike-rewrite","persona":"Divya","source":"calm not confrontational","hook":"\"Advocating means fighting everyone; I'm not confrontational, so I can't do it.\"","myth":{"un":"Advocating means fighting everyone; I'm not confrontational, so I can't do it.","re":"Advocacy is calm, clear partnership, not a fight; you needn't be loud, just steady and informed about your child's needs.","why":"Quiet and firm beats loud and angry."},"relearn":"Advocacy is calm, clear partnership, not a fight; you needn't be loud, just steady and informed."},
  {"id":"nd-1000","cat":"advocate","type":"strike-rewrite","persona":"Meena","source":"one-pager is a gift","hook":"\"It's pushy to give the teacher a one-page note on what helps my child.\"","myth":{"un":"It's pushy to give the teacher a one-page note on what helps my child.","re":"A short one-pager on your child's strengths and what helps is a gift to a busy teacher, not pushiness.","why":"You're saving the teacher guesswork."},"relearn":"A short note on your child's strengths and what helps is a gift to a busy teacher, not pushy."},
  {"id":"nd-1001","cat":"advocate","type":"sort","persona":"any","source":"build or burn bridge","hook":"Sort: builds partnership with the teacher, or burns the bridge?","items":[{"id":"a","text":"\"Here's what calms him, can we try it?\""},{"id":"b","text":"\"Your class is the problem, fix it.\""},{"id":"c","text":"Sharing a short note on his strengths"},{"id":"d","text":"Blaming her in front of others"},{"id":"e","text":"Asking what she's noticing too"},{"id":"f","text":"Threatening to complain on day one"}],"bins":[{"id":"build","label":"Builds partnership","valence":"pos"},{"id":"break","label":"Burns the bridge","valence":"neg"}],"key":{"a":"build","b":"break","c":"build","d":"break","e":"build","f":"break"},"relearn":"Offering what helps, sharing strengths and asking what she notices build partnership; blame and threats burn the bridge."},
  {"id":"nd-1002","cat":"advocate","type":"sort","persona":"any","source":"open or shut door","hook":"Sort: opens the door to support, or shuts it?","items":[{"id":"a","text":"Seeking a professional assessment"},{"id":"b","text":"Hiding the report from school"},{"id":"c","text":"Putting needs in writing"},{"id":"d","text":"Telling no one, to avoid gossip"},{"id":"e","text":"Following up after a 'we'll see'"},{"id":"f","text":"Dropping it after the first delay"}],"bins":[{"id":"open","label":"Opens the door","valence":"pos"},{"id":"shut","label":"Shuts the door","valence":"neg"}],"key":{"a":"open","b":"shut","c":"open","d":"shut","e":"open","f":"shut"},"relearn":"Assessment, written requests and following up open the door; hiding, silence and dropping it shut it."},
  {"id":"nd-1003","cat":"advocate","type":"sort","persona":"any","source":"right or myth","hook":"Sort: a real disability-rights protection, or a myth about it?","items":[{"id":"a","text":"Reasonable accommodation in school"},{"id":"b","text":"\"The law doesn't cover dyslexia\""},{"id":"c","text":"Inclusive-education backing"},{"id":"d","text":"\"Only special schools must take him\""},{"id":"e","text":"Exam concessions on assessment"},{"id":"f","text":"\"He has no legal standing at all\""}],"bins":[{"id":"right","label":"A real right","valence":"pos"},{"id":"myth","label":"A myth","valence":"neg"}],"key":{"a":"right","b":"myth","c":"right","d":"myth","e":"right","f":"myth"},"relearn":"Accommodation, inclusive education and exam concessions are real rights; 'no cover' or 'no standing' are myths."},
  {"id":"nd-1004","cat":"advocate","type":"sort","persona":"any","source":"school vs family","hook":"Sort: which is school advocacy, and which is family advocacy?","items":[{"id":"a","text":"Requesting a learning-support plan"},{"id":"b","text":"Asking for exam concessions"},{"id":"c","text":"Explaining the profile to grandparents"},{"id":"d","text":"Setting respectful limits with a relative"},{"id":"e","text":"A note to the class teacher"},{"id":"f","text":"Coaching an aunt on what calms him"}],"bins":[{"id":"school","label":"School advocacy","valence":"neutral"},{"id":"family","label":"Family advocacy","valence":"neutral"}],"key":{"a":"school","b":"school","c":"family","d":"family","e":"school","f":"family"},"relearn":"Support plans, concessions and teacher notes are school advocacy; explaining the profile and coaching relatives are family advocacy."},
  {"id":"nd-1005","cat":"advocate","type":"sort","persona":"any","source":"strong or thin over time","hook":"Sort: keeps advocacy strong over time, or wears it thin?","items":[{"id":"a","text":"Keeping a folder of reports and notes"},{"id":"b","text":"Re-explaining from scratch each year"},{"id":"c","text":"A short summary for each new teacher"},{"id":"d","text":"Relying only on memory in meetings"},{"id":"e","text":"Noting what worked last term"},{"id":"f","text":"Letting the plan lapse over holidays"}],"bins":[{"id":"strong","label":"Keeps it strong","valence":"pos"},{"id":"thin","label":"Wears it thin","valence":"neg"}],"key":{"a":"strong","b":"thin","c":"strong","d":"thin","e":"strong","f":"thin"},"relearn":"A folder, a summary per teacher and notes on what worked keep advocacy strong; starting from scratch wears it thin."},
  {"id":"nd-1006","cat":"advocate","type":"sort","persona":"any","source":"hold or give away","hook":"Sort: holds your ground calmly, or gives your child's needs away?","items":[{"id":"a","text":"\"What support can the school offer him?\""},{"id":"b","text":"\"Sorry to bother you, never mind.\""},{"id":"c","text":"\"Can we write down what we agreed?\""},{"id":"d","text":"\"Maybe I'm overreacting, ignore me.\""},{"id":"e","text":"\"Whom should I speak to next?\""},{"id":"f","text":"\"If you say he's fine, he's fine.\""}],"bins":[{"id":"hold","label":"Holds the ground","valence":"pos"},{"id":"give","label":"Gives it away","valence":"neg"}],"key":{"a":"hold","b":"give","c":"hold","d":"give","e":"hold","f":"give"},"relearn":"Asking what support exists, writing it down and asking whom to see next hold the ground; over-apologising gives it away."},
  {"id":"nd-1007","cat":"advocate","type":"sort","persona":"any","source":"forward or dead end","hook":"Sort: a wise next step when a service is slow, or a dead end?","items":[{"id":"a","text":"Politely following up in writing"},{"id":"b","text":"Assuming nothing's available, stopping"},{"id":"c","text":"Asking a parent group for another route"},{"id":"d","text":"Deciding the system just won't help"},{"id":"e","text":"Requesting a timeline for next steps"},{"id":"f","text":"Quietly giving up to dodge the hassle"}],"bins":[{"id":"forward","label":"Keeps it moving","valence":"pos"},{"id":"dead","label":"A dead end","valence":"neg"}],"key":{"a":"forward","b":"dead","c":"forward","d":"dead","e":"forward","f":"dead"},"relearn":"Following up, asking a parent group and requesting a timeline keep it moving; assuming nothing exists is a dead end."},
  {"id":"nd-1008","cat":"advocate","type":"sort","persona":"any","source":"team or alone","hook":"Sort: builds a team of champions, or leaves you carrying it alone?","items":[{"id":"a","text":"Briefing a willing uncle on what helps"},{"id":"b","text":"Doing every school meeting solo"},{"id":"c","text":"Bringing your partner into the plan"},{"id":"d","text":"Hiding the diagnosis from family"},{"id":"e","text":"Joining a parent support group"},{"id":"f","text":"Refusing all offers of help"}],"bins":[{"id":"team","label":"Builds the team","valence":"pos"},{"id":"alone","label":"Leaves you alone","valence":"neg"}],"key":{"a":"team","b":"alone","c":"team","d":"alone","e":"team","f":"alone"},"relearn":"Briefing relatives, bringing your partner in and joining a parent group build the team; going solo leaves you alone."},
  {"id":"nd-1009","cat":"advocate","type":"branch","persona":"Meena","source":"slow to a plan","hook":"The teacher seats your son at the back, calling him 'just slow and distracted'.","options":[{"text":"Share his profile and ask for a front seat and chunked work","consequence":"You turn 'slow' into a plan she can follow.","outcome":"plan","best":true},{"text":"Accept that he's slow and hope he copes","consequence":"Sharing his profile gets support; accepting 'slow' leaves him struggling unseen."}],"debrief":"Turn a vague 'slow' label into specific accommodations you and the teacher can both act on.","relearn":"When a teacher calls your child 'slow', share his profile and request concrete accommodations."},
  {"id":"nd-1010","cat":"advocate","type":"branch","persona":"Meena","source":"shield at the wedding","hook":"At a wedding, an uncle says your daughter's stimming is 'bad manners to beat out'.","options":[{"text":"Say calmly it's how she self-soothes and steer her somewhere quiet","consequence":"You shield her and show she isn't misbehaving.","outcome":"shield","best":true},{"text":"Scold her publicly to satisfy the uncle","consequence":"A calm word protects her; scolding her to please him teaches her she's shameful."}],"debrief":"Shield your child from undeserved blame by calmly correcting it, not passing it on.","relearn":"When a relative shames stimming, calmly explain it's self-soothing and protect your child."},
  {"id":"nd-1011","cat":"advocate","type":"branch","persona":"Divya","source":"report unlocks concession","hook":"The school will only allow exam extra time if you produce a formal assessment report.","options":[{"text":"Book a qualified professional assessment to get the report","consequence":"You secure the evidence the school needs.","outcome":"assess","best":true},{"text":"Argue extra time should come on your word alone","consequence":"A report secures it; your word alone leaves the school unable to grant it."}],"debrief":"A professional assessment is the evidence that unlocks fair exam concessions; pursue it.","relearn":"Seek a qualified assessment to get the report the school needs for fair exam concessions."},
  {"id":"nd-1012","cat":"advocate","type":"branch","persona":"Meena","source":"carry the plan over","hook":"Your son's support plan was agreed last year, but the new teacher hasn't seen it.","options":[{"text":"Share the plan and a short summary, and ask to review it together","consequence":"You carry the support across the handover.","outcome":"carry","best":true},{"text":"Assume the school passed it on and say nothing","consequence":"Sharing it keeps support continuous; assuming a handover often means it lapses."}],"debrief":"Carry your child's plan across each teacher handover yourself; don't assume it travelled.","relearn":"At a handover, share the plan and a summary yourself so accommodations carry over."},
  {"id":"nd-1013","cat":"advocate","type":"branch","persona":"Vikram","source":"refuse the cure seller","hook":"A 'miracle therapist' guarantees to 'cure' your child's autism in three months for a big fee.","options":[{"text":"Decline and seek evidence-based support from a professional","consequence":"You protect your child and your money.","outcome":"protect","best":true},{"text":"Pay up; maybe this is the cure you prayed for","consequence":"Real support helps; a guaranteed 'cure' is quackery that drains hope and savings."}],"debrief":"There is no 'cure' for neurodivergence; trust qualified, evidence-based support.","relearn":"Decline 'cure' sellers; neurodivergence isn't a disease to cure, so seek evidence-based support."},
  {"id":"nd-1014","cat":"advocate","type":"branch","persona":"Meena","source":"reframe meltdown plan","hook":"The school 'sends home' your daughter after a meltdown, calling it 'violent misconduct'.","options":[{"text":"Reframe it as overwhelm and request a sensory plan to prevent it","consequence":"You move them from punishing to preventing.","outcome":"prevent","best":true},{"text":"Accept the punishment as deserved","consequence":"Asking for a plan addresses the cause; accepting it leaves the trigger in place."}],"debrief":"Reframe a meltdown as overwhelm and ask for prevention, not punishment.","relearn":"When a meltdown is called misconduct, reframe it as overwhelm and request a sensory plan."},
  {"id":"nd-1015","cat":"advocate","type":"branch","persona":"Vikram","source":"hold to inclusion duty","hook":"A school says it 'can't accommodate' your son and tells you to look elsewhere.","options":[{"text":"Ask in writing about its inclusion duty and whom to approach","consequence":"You hold them to the law, keeping the door open.","outcome":"hold","best":true},{"text":"Quietly accept that no school will take him","consequence":"The duty keeps options open; accepting it assumes a 'no' too soon."}],"debrief":"Hold a school to its inclusion duty calmly and in writing; one 'no' isn't final.","relearn":"If a school 'can't accommodate', ask in writing about its inclusion duty and the next step."},
  {"id":"nd-1016","cat":"advocate","type":"branch","persona":"Divya","source":"don't advocate alone","hook":"You feel too drained and ashamed to attend yet another meeting about your child's needs.","options":[{"text":"Bring your partner or a parent-group friend so you don't go alone","consequence":"Shared advocacy sustains you and the support.","outcome":"shared","best":true},{"text":"Skip the meeting and let the support stall","consequence":"Bringing support keeps advocacy alive; skipping meetings lets the plan slip."}],"debrief":"You don't have to advocate alone; bring someone so advocacy survives your tiredness.","relearn":"When you're drained, bring your partner or a parent-friend so advocacy doesn't rest on you alone."},
  {"id":"nd-1017","cat":"advocate","type":"branch","persona":"Divya","source":"right method not drills","hook":"A tutor wants to drill your son for hours to 'fix' his slow reading before exams.","options":[{"text":"Explain dyslexia needs the right method and concessions, not just drilling","consequence":"You steer help toward what works for him.","outcome":"method","best":true},{"text":"Agree to long drills so someone's at least trying","consequence":"The right method helps; endless drilling exhausts him, not his dyslexia."}],"debrief":"Advocate for the right method and concessions, not just more hours; effort isn't the gap.","relearn":"For dyslexia, advocate for the right method and exam concessions, not endless drilling."},
  {"id":"nd-1018","cat":"advocate","type":"branch","persona":"Meena","source":"openness over secrecy","hook":"Grandparents insist the diagnosis stays a secret 'for the child's marriage prospects'.","options":[{"text":"Say gently that openness, on your terms, lets support and understanding in","consequence":"You choose your child's wellbeing over secrecy.","outcome":"open","best":true},{"text":"Agree to hide it completely to keep peace","consequence":"Openness on your terms lets help in; secrecy isolates your child and feeds stigma."}],"debrief":"Openness on your own terms lets support in; secrecy feeds the stigma it fears.","relearn":"Openness about a diagnosis, on your own terms, lets support in; secrecy isolates the family."},
  {"id":"nd-1019","cat":"advocate","type":"branch","persona":"Meena","source":"verbal yes in writing","hook":"The school agreed to accommodations verbally, but nothing changes by the next week.","options":[{"text":"Send a polite written summary of what was agreed and a review date","consequence":"You turn a vague yes into a tracked commitment.","outcome":"track","best":true},{"text":"Assume good intentions and wait for months","consequence":"A summary makes it trackable; waiting quietly often means nothing happens."}],"debrief":"Follow a verbal yes with a calm written summary and a review date so agreements happen.","relearn":"After a verbal yes, send a written summary and a review date so accommodations actually happen."},
  {"id":"nd-1020","cat":"advocate","type":"match","persona":"Meena","source":"blocker to reply","hook":"Match each blocker you might hear to a calm advocacy reply.","pairs":[{"left":"\"He's just lazy and won't try.\"","right":"\"His brain works differently; here's what helps him.\""},{"left":"\"We can't accommodate him.\"","right":"\"What's our duty to include him here?\""},{"left":"\"Extra time is unfair to others.\"","right":"\"It's fair access, like glasses.\""},{"left":"\"Let's just wait and see.\"","right":"\"Can we set a date to review?\""},{"left":"\"Keep the diagnosis quiet.\"","right":"\"Openness, on our terms, lets help in.\""}],"relearn":"Each blocker has a calm reply: reframe 'lazy', name the duty to include, name fair access, set a review."},
  {"id":"nd-1021","cat":"advocate","type":"match","persona":"any","source":"arena to first move","hook":"Match each arena to the right first advocacy move there.","pairs":[{"left":"School","right":"Request a written learning-support plan"},{"left":"Exam board","right":"Apply for concessions with an assessment"},{"left":"Grandparents","right":"Explain the profile and set respectful limits"},{"left":"A slow service","right":"Follow up politely and ask the next step"},{"left":"Your co-parent","right":"Agree the plan and share the load"}],"relearn":"School needs a written plan, the exam board concessions, grandparents understanding, a slow service follow-up, a co-parent shared load."},
  {"id":"nd-1022","cat":"advocate","type":"match","persona":"any","source":"right to example","hook":"Match each disability right to a plain example for a parent.","pairs":[{"left":"Reasonable accommodation","right":"Noise headphones and a quiet exam room"},{"left":"Inclusive education","right":"A place in a regular school with support"},{"left":"Non-discrimination","right":"Not refused only for being autistic"},{"left":"Exam adjustments","right":"Extra time or a scribe on assessment"},{"left":"Accessible learning","right":"Materials in a form he can use"}],"relearn":"These rights mean accommodation, a regular-school place, exam adjustments, accessible materials."},
  {"id":"nd-1023","cat":"advocate","type":"match","persona":"any","source":"habit to problem","hook":"Match each advocacy habit to the problem it prevents.","pairs":[{"left":"Keeping a report folder","right":"Re-proving the diagnosis every year"},{"left":"A one-page profile note","right":"Each new teacher starting from zero"},{"left":"Written agreements","right":"A verbal yes going nowhere"},{"left":"A review date","right":"A plan that lapses and is forgotten"},{"left":"A parent-group contact","right":"Hitting a dead end with no other route"}],"relearn":"A folder, a profile note, written agreements, review dates and parent contacts each prevent a way advocacy quietly fails."},
  {"id":"nd-1024","cat":"advocate","type":"match","persona":"any","source":"who gives what","hook":"Match each person on your child's team to what they best give.","pairs":[{"left":"Class teacher","right":"Day-to-day accommodations in the room"},{"left":"Qualified professional","right":"Assessment and tailored strategies"},{"left":"Co-parent","right":"Sharing meetings and the daily load"},{"left":"Parent support group","right":"Practical tips and another route to try"},{"left":"Willing grandparent","right":"A calm, understanding extra champion"}],"relearn":"A teacher gives daily accommodations, a professional assessment, a co-parent shared load, a group tips, a grandparent support."},
  {"id":"nd-1025","cat":"advocate","type":"match","persona":"any","source":"weak to strong move","hook":"Match each weak advocacy move to its stronger version.","pairs":[{"left":"\"Sorry to bother you.\"","right":"\"I'd like to discuss the support he needs.\""},{"left":"Relying on memory","right":"Bringing a folder of reports and notes"},{"left":"Dropping it after a 'no'","right":"Asking, in writing, whom to approach next"},{"left":"Blaming the teacher","right":"Asking what she notices, then offering help"},{"left":"Hiding the diagnosis","right":"Sharing it, on your terms, with helpers"}],"relearn":"Swap apology for a clear ask, memory for a folder, giving up for a next step, blame for partnership, hiding for openness."},
  {"id":"nd-1026","cat":"advocate","type":"match","persona":"any","source":"line to effect","hook":"Match each calm parent line to what it achieves in a meeting.","pairs":[{"left":"\"Can we write down what we agreed?\"","right":"Turns a vague yes into a commitment"},{"left":"\"What's worked for others here?\"","right":"Invites the school's experience"},{"left":"\"Here are his strengths and triggers.\"","right":"Gives the teacher a starting point"},{"left":"\"Whom should I speak to next?\"","right":"Keeps the path open after a 'no'"},{"left":"\"Can we set a date to review?\"","right":"Stops the plan quietly lapsing"}],"relearn":"Calm lines do work: writing tracks it, asking experience builds partnership, review dates hold the plan."},
  {"id":"nd-1027","cat":"advocate","type":"match","persona":"any","source":"quackery to truth","hook":"Match each 'cure' claim to the truth that debunks it.","pairs":[{"left":"\"This diet will cure his autism.\"","right":"Neurodivergence isn't a disease to cure"},{"left":"\"Strict discipline fixes ADHD.\"","right":"You can't punish a wiring difference away"},{"left":"\"He'll grow out of dyslexia.\"","right":"It's lifelong; the right method helps"},{"left":"\"A label will ruin his future.\"","right":"A diagnosis is a key, not a verdict"},{"left":"\"Just try harder, he'll be normal.\"","right":"Support lets him show his best"}],"relearn":"No diet cures autism, discipline can't fix ADHD, dyslexia is lifelong, a label is a key not a verdict."},
  {"id":"nd-1028","cat":"advocate","type":"role-play","persona":"Meena","source":"open as partner","hook":"You're meeting the principal to request a support plan. You want to open as a calm partner.","setup":"Open the meeting:","yourLine":[{"text":"\"Thank you for your time. I'd love to work with you, here are his strengths and what helps him learn.\"","best":true},{"text":"\"I suppose you'll tell me there's nothing the school can do, as usual.\""}],"relearn":"Opening with thanks, strengths and a wish to work together sets advocacy up as partnership, not a battle."},
  {"id":"nd-1029","cat":"advocate","type":"role-play","persona":"Vikram","source":"fair access reply","hook":"A teacher says she can't give your son extra time because 'it wouldn't be fair to the others'.","setup":"Respond calmly:","yourLine":[{"text":"\"Extra time is fair access, like glasses; it lets him show what he knows, it isn't an advantage.\"","best":true},{"text":"\"Fine, forget it, I don't want him to be the odd one out anyway.\""}],"relearn":"Naming concessions as fair access, like glasses, answers the 'unfairness' worry without backing down."},
  {"id":"nd-1030","cat":"advocate","type":"role-play","persona":"Meena","source":"answer the hide-it elder","hook":"Your mother-in-law says the autism diagnosis must be hidden so the family isn't 'shamed'.","setup":"Answer gently but firmly:","yourLine":[{"text":"\"I get the worry, but openness on our terms lets people help him; hiding it would leave him more alone.\"","best":true},{"text":"\"You're right, let's never mention it to anyone again.\""}],"relearn":"Acknowledging the fear while choosing openness keeps support flowing and protects the child from isolating secrecy."},
  {"id":"nd-1031","cat":"advocate","type":"role-play","persona":"Divya","source":"polite follow-up call","hook":"A slow service has ignored your assessment request for weeks. You're following up by phone.","setup":"Make the follow-up call:","yourLine":[{"text":"\"I'm following up on last month's request, could you tell me the next step and a likely timeline?\"","best":true},{"text":"\"I assume nothing's happening, so I'll just stop bothering you all.\""}],"relearn":"A polite, specific follow-up asking the next step and a timeline keeps a slow service moving, not stalling."},
  {"id":"nd-1032","cat":"advocate","type":"role-play","persona":"Meena","source":"reframe naughty","hook":"At the parent-teacher meeting, the teacher calls your son 'naughty and disruptive'.","setup":"Reframe it calmly:","yourLine":[{"text":"\"When he's overwhelmed he can't sit still; a movement break and warnings before changes really help him.\"","best":true},{"text":"\"He's just badly behaved, I know, I'll tell him off properly at home.\""}],"relearn":"Reframing 'naughty' as overwhelm plus concrete supports turns blame into a plan the teacher can use."},
  {"id":"nd-1033","cat":"advocate","type":"role-play","persona":"Priya","source":"brief the willing relative","hook":"Your brother offers to help but says, \"Just tell me what to do with him.\"","setup":"Brief him simply:","yourLine":[{"text":"\"He loves trains and gets overwhelmed by noise; if a tantrum starts, stay calm and take him somewhere quiet.\"","best":true},{"text":"\"Honestly, just leave it to me, you wouldn't understand him anyway.\""}],"relearn":"A simple brief on strengths and what calms your child turns a willing relative into a real champion."},
  {"id":"nd-1034","cat":"advocate","type":"role-play","persona":"Meena","source":"hold the inclusion line","hook":"The school suggests your daughter move to a 'special school' so they needn't adapt.","setup":"Hold the line calmly:","yourLine":[{"text":"\"She's doing well here with friends; could we look at the support that would let her stay?\"","best":true},{"text":"\"If you don't want her, I suppose we'll just take her away quietly.\""}],"relearn":"Naming what's working and asking for inclusive support keeps a regular-school place on the table."},
  {"id":"nd-1035","cat":"advocate","type":"role-play","persona":"Vikram","source":"decline the cure clinic","hook":"A relative pushes a 'guaranteed autism cure' clinic on you. You want to decline without a fight.","setup":"Decline warmly but clearly:","yourLine":[{"text":"\"Thanks for caring, but there's no cure; we're putting our energy into support that really helps him.\"","best":true},{"text":"\"Maybe you're right, what's the harm, I'll book it just to be safe.\""}],"relearn":"Thanking the relative while naming that there's no cure, only evidence-based support, declines quackery without conflict."},
  {"id":"nd-1036","cat":"advocate","type":"reflect","persona":"Meena","source":"a time you spoke up","hook":"Lensy: think of a time you spoke up for your child and it shifted something, even a little.","prompt":"What comes to mind?","options":["A meeting that went better","A teacher who finally understood","Just feeling braver next time"],"affirm":"Every time you speak up, you build the muscle, and you show your child they're worth standing up for.","relearn":"Each act of advocacy, however small, builds your confidence and shows your child they matter."},
  {"id":"nd-1037","cat":"advocate","type":"reflect","persona":"Divya","source":"make the meeting doable","hook":"Lensy: what would make the next school meeting feel a little more doable for you?","prompt":"What would help?","options":["Bringing my notes in a folder","Taking my partner along","Writing my main ask first"],"affirm":"There's no single right way; whatever steadies you, a folder, a person, a written ask, makes you a stronger advocate.","relearn":"Small preparations, notes, a companion or a written ask, make advocacy more doable and effective."},
  {"id":"nd-1038","cat":"advocate","type":"reflect","persona":"any","source":"who could champion too","hook":"Lensy: who could become another champion for your child if you let them in a little?","prompt":"Who comes to mind?","options":["My partner","A grandparent or aunt","A parent who gets it"],"affirm":"You needn't be the only one; every champion you let in doubles the people standing up for your child.","relearn":"Letting trusted people in builds a team of champions, so advocacy isn't yours to carry alone."},
  {"id":"nd-1039","cat":"advocate","type":"reflect","persona":"Meena","source":"name the worry","hook":"Lensy: when you imagine asking the school for support, what worry shows up first?","prompt":"What's the worry?","options":["Being seen as 'that parent'","Not knowing the right words","Hearing 'no' again"],"affirm":"That worry is normal and it doesn't make you wrong; even with it, asking for your child is worth it.","relearn":"Worries about advocating are normal; naming them helps you ask anyway, which is what your child needs."},
  {"id":"nd-1040","cat":"advocate","type":"reflect","persona":"Divya","source":"picture the good year","hook":"Lensy: picture the school year going well for your child. What support is in place?","prompt":"What do you see?","options":["A teacher who knows what helps","A few simple accommodations","Him feeling understood"],"affirm":"Whatever you pictured, that's the goal worth advocating toward, and naming it helps you ask for it.","relearn":"Picturing the support you want for your child clarifies exactly what to advocate for."},
  {"id":"nd-1041","cat":"advocate","type":"reflect","persona":"Divya","source":"refill between rounds","hook":"Lensy: after a hard meeting, how do you usually refill before the next round?","prompt":"What refills you?","options":["A friend who listens","A break for myself","Remembering why I do this"],"affirm":"Advocacy is a long road; refilling however works for you is part of staying able to keep championing your child.","relearn":"Looking after yourself between hard meetings is part of being able to keep advocating for your child."},
  {"id":"nd-1042","cat":"advocate","type":"reflect","persona":"Meena","source":"strength to lead with","hook":"Lensy: what's one strength of your child you'd want every new teacher to know first?","prompt":"What would you tell them?","options":["How focused he is on what he loves","How honest and kind he is","How he notices what others miss"],"affirm":"Leading with a strength changes how a teacher sees your child, and you're the one who can make sure they hear it.","relearn":"Leading your child's story with a strength shapes how teachers see and support them."},
  {"id":"nd-1043","cat":"advocate","type":"spot","persona":"any","source":"spot the giving-up lines","hook":"Spot the two red flags: lines that quietly give up your child's support.","scene":[{"id":"a","text":"\"Could we put the agreed plan in writing?\"","trick":false},{"id":"b","text":"\"Sorry to be a nuisance, forget I asked.\"","trick":true},{"id":"c","text":"\"What's our duty to include him here?\"","trick":false},{"id":"d","text":"\"If you say he's fine, I'll trust that.\"","trick":true},{"id":"e","text":"\"Whom should I speak to next?\"","trick":false}],"why":"Over-apologising and accepting 'he's fine' both surrender support; the other lines hold the ground calmly.","relearn":"Apologising your way out or accepting 'he's fine' give up support; writing it down and asking next steps hold the ground."},
  {"id":"nd-1044","cat":"advocate","type":"spot","persona":"any","source":"spot the quackery","hook":"Spot the two red flags: 'support' offers that are quackery or harm.","scene":[{"id":"a","text":"A qualified professional assessment","trick":false},{"id":"b","text":"A clinic 'guaranteeing a full autism cure'","trick":true},{"id":"c","text":"A visual schedule and movement breaks","trick":false},{"id":"d","text":"\"Strict beatings will fix his ADHD\"","trick":true},{"id":"e","text":"Exam concessions with a report","trick":false}],"why":"A guaranteed 'cure' and 'beatings fix ADHD' are quackery and harm; the rest are real, evidence-based support.","relearn":"Guaranteed 'cures' and punishment are quackery; assessment, visual schedules and exam concessions are real support."},
  {"id":"nd-1045","cat":"advocate","type":"spot","persona":"any","source":"spot the shaming responses","hook":"Spot the two red flags: family responses that shame your child.","scene":[{"id":"a","text":"\"Let's learn what calms him together.\"","trick":false},{"id":"b","text":"\"Beat the stimming out of her, it's rude.\"","trick":true},{"id":"c","text":"\"I'll take him somewhere quiet when it's loud.\"","trick":false},{"id":"d","text":"\"Hide it or no one will marry him.\"","trick":true},{"id":"e","text":"\"Tell me his strengths so I can cheer him.\"","trick":false}],"why":"Punishing stimming and hiding the diagnosis both shame the child; the others offer real understanding.","relearn":"Beating out stimming or hiding the diagnosis shame your child; learning what calms them and naming strengths support them."},
  {"id":"nd-1046","cat":"advocate","type":"spot","persona":"any","source":"spot the handover gaps","hook":"Spot the two red flags: things that make a teacher handover lose support.","scene":[{"id":"a","text":"Sharing the plan with the new teacher","trick":false},{"id":"b","text":"Assuming the school passed it on","trick":true},{"id":"c","text":"Giving a one-page strengths note","trick":false},{"id":"d","text":"Waiting to see if she struggles first","trick":true},{"id":"e","text":"Asking to review the plan together","trick":false}],"why":"Assuming a handover happened and waiting for problems both let the plan lapse; the rest keep support continuous.","relearn":"Assuming the plan was passed on or waiting for struggles loses support; share it and review it together to keep it."},
  {"id":"nd-1047","cat":"advocate","type":"spot","persona":"any","source":"spot the door-closing replies","hook":"Spot the two red flags: replies to a 'no' that end your child's chances.","scene":[{"id":"a","text":"\"Could we revisit this in writing?\"","trick":false},{"id":"b","text":"\"Then there's nothing to be done.\"","trick":true},{"id":"c","text":"\"Whom can I approach next?\"","trick":false},{"id":"d","text":"\"You're right, I'll stop pushing.\"","trick":true},{"id":"e","text":"\"What would change your answer?\"","trick":false}],"why":"\"Nothing to be done\" and \"I'll stop pushing\" treat one 'no' as final; the rest keep the door open.","relearn":"Treating a 'no' as final ends your child's chances; revisiting in writing and asking whom to see next keep the door open."},
  {"id":"nd-1048","cat":"advocate","type":"spot","persona":"any","source":"spot the spoiling framing","hook":"Spot the two red flags: framings of accommodations to push back on.","scene":[{"id":"a","text":"\"It's fair access, like glasses.\"","trick":false},{"id":"b","text":"\"Extra time just spoils him.\"","trick":true},{"id":"c","text":"\"It lets him show what he knows.\"","trick":false},{"id":"d","text":"\"Headphones are pandering, toughen up.\"","trick":true},{"id":"e","text":"\"It levels the ground, it's no edge.\"","trick":false}],"why":"\"Spoils him\" and \"pandering, toughen up\" wrongly cast fair access as indulgence; the rest frame it as leveling the ground.","relearn":"Calling accommodations 'spoiling' or 'pandering' is wrong; they're fair access that levels the ground, like glasses."},
  {"id":"nd-1049","cat":"advocate","type":"spot","persona":"any","source":"spot the burnout patterns","hook":"Spot the two red flags: ways of carrying advocacy that burn you out.","scene":[{"id":"a","text":"Bringing your partner to the meeting","trick":false},{"id":"b","text":"Doing every meeting alone, every time","trick":true},{"id":"c","text":"Leaning on a parent group for tips","trick":false},{"id":"d","text":"Refusing all offers of help on principle","trick":true},{"id":"e","text":"Sharing the load with a co-parent","trick":false}],"why":"Always going solo and refusing help drain you until advocacy stalls; the rest sustain it.","relearn":"Doing it all alone and refusing help burn you out; sharing meetings and leaning on others sustain your advocacy."},
  {"id":"nd-1080","cat":"drop-the-shame","type":"strike-rewrite","hook":"\"Too much mobile and TV gave my child autism.\"","myth":{"un":"Too much mobile and TV gave my child autism.","re":"Screen time doesn't cause autism or ADHD; your child was born wired this way, screens or no screens.","why":"Correlation in tired homes isn't a cause."},"relearn":"Screens didn't cause your child's neurodivergence; it's how they were wired from the start.","persona":"Meena","source":"not screens"},
  {"id":"nd-1081","cat":"drop-the-shame","type":"strike-rewrite","hook":"\"It's my karma, or some past-life sin, coming back through my child.\"","myth":{"un":"It's my karma, or some past-life sin, coming back through my child.","re":"Neurodivergence is not punishment, karma or a curse; it's simply a different way a brain is wired.","why":"A wiring difference carries no blame or sin."},"relearn":"Your child's neurodivergence is no curse or karma; it's just how their brain is wired.","persona":"Meena","source":"not karma"},
  {"id":"nd-1082","cat":"drop-the-shame","type":"strike-rewrite","hook":"\"A working mother who isn't home enough makes children like this.\"","myth":{"un":"A working mother who isn't home enough makes children like this.","re":"No mother's job, absence or 'cold' parenting causes neurodivergence; that old blame has been thoroughly debunked.","why":"Wiring isn't set by a mother's schedule."},"relearn":"Working or being away didn't cause your child's neurodivergence; that mother-blaming idea is a debunked myth.","persona":"Meena","source":"not working mother"},
  {"id":"nd-1083","cat":"drop-the-shame","type":"strike-rewrite","hook":"\"Vaccines must have triggered my child's condition.\"","myth":{"un":"Vaccines must have triggered my child's condition.","re":"Vaccines do not cause autism; that claim came from fraud and has been disproven again and again.","why":"The original study was retracted as fraudulent."},"relearn":"Vaccines didn't cause your child's neurodivergence; that link was a fraud and has been disproven.","persona":"any","source":"not vaccines"},
  {"id":"nd-1084","cat":"drop-the-shame","type":"strike-rewrite","hook":"\"My diet in pregnancy, or eating the wrong things, caused this.\"","myth":{"un":"My diet in pregnancy, or eating the wrong things, caused this.","re":"What you ate in pregnancy didn't cause your child's neurodivergence; you did nothing wrong to bring it about.","why":"Self-blame over food is misplaced guilt."},"relearn":"Your pregnancy diet didn't cause this; there's no food choice you could have made to prevent your child's wiring.","persona":"Divya","source":"not diet"},
  {"id":"nd-1085","cat":"drop-the-shame","type":"strike-rewrite","hook":"\"A special diet or supplement will cure the autism.\"","myth":{"un":"A special diet or supplement will cure the autism.","re":"No diet, supplement or detox cures neurodivergence; people selling 'cures' are selling false hope, not help.","why":"There's no cure to buy, only support that helps."},"relearn":"No diet or supplement cures neurodivergence; beware anyone selling a 'cure'. Support, not a cure, helps your child.","persona":"any","source":"no cure to buy"},
  {"id":"nd-1086","cat":"drop-the-shame","type":"strike-rewrite","hook":"\"If I'd been stricter, my child would behave like the others.\"","myth":{"un":"If I'd been stricter, my child would behave like the others.","re":"Stricter discipline doesn't fix neurodivergence; meltdowns are overwhelm, and punishment only adds fear.","why":"You can't discipline a wiring difference away."},"relearn":"Being stricter wouldn't have changed your child's wiring; meltdowns are overwhelm, not a discipline failure.","persona":"Vikram","source":"not strictness"},
  {"id":"nd-1087","cat":"drop-the-shame","type":"strike-rewrite","hook":"\"My child stims and rocks because we failed to train it out of him.\"","myth":{"un":"My child stims and rocks because we failed to train it out of him.","re":"Stimming is self-soothing, not a failure to train; it calms your child and isn't something to shame out of them.","why":"Self-soothing is a need, not bad behaviour."},"relearn":"Stimming is your child soothing themselves, not your failure; it's not shameful and needn't be trained away.","persona":"Meena","source":"stimming not failure"},
  {"id":"nd-1088","cat":"drop-the-shame","type":"strike-rewrite","hook":"\"A diagnosis is a tragedy that ruins a child's whole future.\"","myth":{"un":"A diagnosis is a tragedy that ruins a child's whole future.","re":"A diagnosis is a key to the right support, not a tragedy or a verdict; your child is the same child the day after.","why":"A name opens doors; it doesn't close them."},"relearn":"A diagnosis is a key to support, not a tragedy; your child is unchanged by the label and their future is open.","persona":"Meena","source":"key not tragedy"},
  {"id":"nd-1090","cat":"drop-the-shame","type":"strike-rewrite","hook":"\"My child is a burden I'm being punished with.\"","myth":{"un":"My child is a burden I'm being punished with.","re":"Your child is a whole, wonderful person, not a punishment or a burden; the heavy part is the stigma, not the child.","why":"The weight is society's judgement, not your child."},"relearn":"Your child isn't a burden or a punishment; they're a whole person, and the weight you feel is stigma, not them.","persona":"Meena","source":"not a burden"},
  {"id":"nd-1091","cat":"drop-the-shame","type":"strike-rewrite","hook":"\"I should have caught this sooner; the late diagnosis is my failure.\"","myth":{"un":"I should have caught this sooner; the late diagnosis is my failure.","re":"A late diagnosis is common and isn't your failure; you acted the moment you understood, and that's what counts.","why":"You can only act on what you've come to know."},"relearn":"A late diagnosis isn't a failure; signs are easy to miss, and acting once you understood is exactly the right thing.","persona":"Divya","source":"late not failure"},
  {"id":"nd-1092","cat":"drop-the-shame","type":"strike-rewrite","hook":"\"My child's meltdown in public showed everyone I can't control him.\"","myth":{"un":"My child's meltdown in public showed everyone I can't control him.","re":"A public meltdown is overwhelm spilling over, not proof of bad parenting; you're supporting a child, not failing to control one.","why":"Strangers' stares aren't evidence of anything."},"relearn":"A public meltdown is overwhelm, not proof you can't parent; you're helping an overloaded child, not failing.","persona":"Meena","source":"public meltdown"},
  {"id":"nd-1094","cat":"drop-the-shame","type":"strike-rewrite","hook":"\"Sharing his diagnosis with the school will mark him for life.\"","myth":{"un":"Sharing his diagnosis with the school will mark him for life.","re":"Sharing on your terms unlocks support and understanding; secrecy is what isolates a child and feeds the stigma.","why":"Hiding protects the shame, not the child."},"relearn":"Telling school on your own terms opens support; hiding the diagnosis isolates your child and feeds stigma.","persona":"Vikram","source":"openness unlocks support"},
  {"id":"nd-1095","cat":"drop-the-shame","type":"sort","hook":"Sort each line: a fact that lifts the shame, or a blame myth that piles it on.","items":[{"id":"a","text":"\"It's no one's fault, least of all yours\""},{"id":"b","text":"\"Screen time gave him autism\""},{"id":"c","text":"\"With support, your child can flourish\""},{"id":"d","text":"\"A good family hides such things\""},{"id":"e","text":"\"A diagnosis is a key to support\""},{"id":"f","text":"\"It's your karma coming back\""}],"bins":[{"id":"lifts","label":"Lifts shame","valence":"pos"},{"id":"piles","label":"Piles on blame","valence":"neg"}],"key":{"a":"lifts","b":"piles","c":"lifts","d":"piles","e":"lifts","f":"piles"},"relearn":"'No one's fault', 'can flourish' and 'a key to support' lift shame; screens, karma and 'hide it' are blame myths.","persona":"any","source":"lifts vs piles"},
  {"id":"nd-1096","cat":"drop-the-shame","type":"sort","hook":"Sort: which of these is true and steadying, and which is a debunked cause-myth?","items":[{"id":"a","text":"Neurodivergence is lifelong, not a phase"},{"id":"b","text":"Vaccines triggered it"},{"id":"c","text":"It's how the brain is wired"},{"id":"d","text":"Bad parenting caused it"},{"id":"e","text":"Support helps a child thrive"},{"id":"f","text":"A special detox can cure it"}],"bins":[{"id":"true","label":"True","valence":"pos"},{"id":"myth","label":"Debunked myth","valence":"neg"}],"key":{"a":"true","b":"myth","c":"true","d":"myth","e":"true","f":"myth"},"relearn":"Lifelong wiring and support that helps are true; vaccines, bad parenting and 'detox cures' are debunked myths.","persona":"any","source":"true vs debunked"},
  {"id":"nd-1097","cat":"drop-the-shame","type":"sort","hook":"A meltdown happens. Sort each thought: shame-talk that traps you, or a kind truth that frees you.","items":[{"id":"a","text":"\"Everyone's judging my parenting\""},{"id":"b","text":"\"He's overwhelmed and needs me calm\""},{"id":"c","text":"\"This proves I've failed\""},{"id":"d","text":"\"Strangers' stares aren't the truth\""},{"id":"e","text":"\"I should be ashamed in public\""},{"id":"f","text":"\"My job is to help him feel safe\""}],"bins":[{"id":"shame","label":"Shame-talk","valence":"neg"},{"id":"kind","label":"Kind truth","valence":"pos"}],"key":{"a":"shame","b":"kind","c":"shame","d":"kind","e":"shame","f":"kind"},"relearn":"'Everyone's judging' and 'I've failed' are shame-talk; 'he's overwhelmed' and 'help him feel safe' are kind truths.","persona":"Meena","source":"shame-talk vs truth"},
  {"id":"nd-1098","cat":"drop-the-shame","type":"sort","hook":"Sort: which words shield your child from blame, and which quietly hand them shame?","items":[{"id":"a","text":"\"It's no one's fault, you're wonderful\""},{"id":"b","text":"\"See, you've embarrassed us again\""},{"id":"c","text":"\"Your brain just works differently\""},{"id":"d","text":"\"Why can't you be normal?\""},{"id":"e","text":"\"I'm proud of how you tried\""},{"id":"f","text":"\"Don't tell anyone about this\""}],"bins":[{"id":"shield","label":"Shields the child","valence":"pos"},{"id":"hands","label":"Hands them shame","valence":"neg"}],"key":{"a":"shield","b":"hands","c":"shield","d":"hands","e":"shield","f":"hands"},"relearn":"'No one's fault' and 'I'm proud you tried' shield your child; 'be normal' and 'don't tell anyone' hand them shame.","persona":"Meena","source":"shield vs hand shame"},
  {"id":"nd-1099","cat":"drop-the-shame","type":"sort","hook":"A relative offers 'cures'. Sort: a quack promise to refuse, or a real support to lean on.","items":[{"id":"a","text":"A miracle detox to 'fix' him"},{"id":"b","text":"A qualified professional assessment"},{"id":"c","text":"A faith-healer's 'cure'"},{"id":"d","text":"A peer parent support group"},{"id":"e","text":"Drops that 'remove' autism"},{"id":"f","text":"Tele-MANAS 14416 for guidance"}],"bins":[{"id":"quack","label":"Quack promise","valence":"neg"},{"id":"real","label":"Real support","valence":"pos"}],"key":{"a":"quack","b":"real","c":"quack","d":"real","e":"quack","f":"real"},"relearn":"Detoxes, faith-cures and 'autism-removing drops' are quackery; a professional, a peer group and Tele-MANAS are real support.","persona":"any","source":"quack vs real"},
  {"id":"nd-1100","cat":"drop-the-shame","type":"sort","hook":"Lensy: sort the grief work. Which moves you forward, and which keeps you stuck in guilt?","items":[{"id":"a","text":"Letting yourself feel the sadness"},{"id":"b","text":"Replaying 'what did I do wrong?'"},{"id":"c","text":"Refocusing on the child here now"},{"id":"d","text":"Punishing yourself with what-ifs"},{"id":"e","text":"Naming that it's no one's fault"},{"id":"f","text":"Carrying guilt silently for years"}],"bins":[{"id":"forward","label":"Moves forward","valence":"pos"},{"id":"stuck","label":"Keeps you stuck","valence":"neg"}],"key":{"a":"forward","b":"stuck","c":"forward","d":"stuck","e":"forward","f":"stuck"},"relearn":"Feeling the grief, refocusing on your child and 'no one's fault' move you forward; what-ifs and silent guilt keep you stuck.","persona":"Divya","source":"grief forward vs stuck"},
  {"id":"nd-1101","cat":"drop-the-shame","type":"reflect","hook":"Lensy: a diagnosis is a key to support, not a verdict on your child. Does that land?","prompt":"What do you feel?","options":["It lands","A key, not a verdict","Same child tomorrow"],"affirm":"A diagnosis is information and a key to the right support, not a tragedy or a verdict; your child is unchanged by it.","relearn":"A diagnosis is a key to support, not a verdict; your child is the same wonderful child the day after.","persona":"Meena","source":"key not verdict"},
  {"id":"nd-1102","cat":"drop-the-shame","type":"reflect","hook":"Lensy: you can grieve the path you imagined and still love the child in front of you. True for you?","prompt":"Sit with that.","options":["True for me","Grief is allowed","Love them as they are"],"affirm":"Allowing the grief and dropping the guilt are both okay; you can mourn your expectations and fully love your real child.","relearn":"You're allowed the grief and free of the guilt; love the child you have, exactly as they are.","persona":"Divya","source":"grief and love"},
  {"id":"nd-1103","cat":"drop-the-shame","type":"reflect","hook":"Lensy: the stares of strangers in a market are not the truth about your child. Agree?","prompt":"What's your take?","options":["Agree","Stares aren't truth","I know my child"],"affirm":"A stranger's judgement during a meltdown is their misunderstanding, not a verdict on you or your wonderful child.","relearn":"Strangers' stares aren't the truth; a meltdown is overwhelm, and you know your child far better than they do.","persona":"Meena","source":"stares not truth"},
  {"id":"nd-1104","cat":"drop-the-shame","type":"reflect","hook":"Lensy: you didn't cause this, and you don't owe anyone an apology for your child. Feel right?","prompt":"How does that sit?","options":["Feels right","No apology owed","Not my fault"],"affirm":"You caused nothing and owe no apology; over-saying sorry for your child quietly accepts a blame that was never yours.","relearn":"You didn't cause it and owe no apology; constant sorrys hand you a blame that was never yours to carry.","persona":"Meena","source":"no apology owed"},
  {"id":"nd-1105","cat":"drop-the-shame","type":"reflect","hook":"Lensy: the energy you spend on shame could go to understanding your child instead. Worth a try?","prompt":"What do you think?","options":["Worth a try","Redirect the energy","Understand, not blame"],"affirm":"Shame and blame help no one; the same energy, turned toward understanding and championing your child, changes everything.","relearn":"Shame helps no one; spend that energy on understanding your child instead, and it goes much further.","persona":"Meena","source":"redirect energy"},
  {"id":"nd-1106","cat":"drop-the-shame","type":"reflect","hook":"Lensy: you don't have to be a perfect parent, just a loving, learning one. Does that ease it?","prompt":"Take a breath.","options":["It eases it","Learning is enough","Loving, not perfect"],"affirm":"You don't have to be perfect or all-knowing; a learning, loving parent is exactly what your child needs.","relearn":"You needn't be perfect; a loving, learning parent is exactly what your child needs, and that's enough.","persona":"Divya","source":"loving not perfect"},
  {"id":"nd-1107","cat":"drop-the-shame","type":"reflect","hook":"Lensy: when a relative says 'fix him', remember there's nothing broken to fix. Hold that?","prompt":"What's your feeling?","options":["I'll hold it","Nothing's broken","Difference, not defect"],"affirm":"There is nothing broken in your child to fix; they're wired differently, not wrongly, and they're whole exactly as they are.","relearn":"There's nothing broken to fix; your child is different, not defective, and whole as they are.","persona":"Meena","source":"nothing to fix"},
  {"id":"nd-1108","cat":"drop-the-shame","type":"reflect","hook":"Lensy: telling one trusted person can lift a weight you've carried alone. Ready to consider it?","prompt":"Sit with it.","options":["I'll consider it","Sharing lifts weight","Not alone"],"affirm":"Openness on your own terms, even with just one trusted person, lets support in and lightens the shame you've carried alone.","relearn":"Sharing on your terms, even with one trusted person, lets support in and lifts the weight of carrying it alone.","persona":"Vikram","source":"sharing lifts weight"},
  {"id":"nd-1109","cat":"drop-the-shame","type":"branch","hook":"At a family function, an uncle loudly calls your son 'mad' in front of everyone.","options":[{"text":"Calmly say his brain works differently, then steer him away","consequence":"You correct the slur and protect your son from absorbing it.","outcome":"correct","best":true},{"text":"Stay silent and hope no one noticed","consequence":"Correcting it shields him; silence lets the cruel label land.","outcome":"silent"}],"debrief":"Correct cruel labels calmly and protect your child; the blame was never theirs to wear.","relearn":"When someone shames your child, correct it calmly and shield them; it's no one's fault.","persona":"Meena","source":"correct the slur"},
  {"id":"nd-1110","cat":"drop-the-shame","type":"branch","hook":"A WhatsApp uncle forwards a 'doctor' selling a costly autism 'cure'.","options":[{"text":"Politely decline and stick with a professional and real support","consequence":"You protect your money and your child from false hope.","outcome":"decline","best":true},{"text":"Pay for it out of guilt and desperation","consequence":"Declining keeps you safe; chasing a 'cure' just sells false hope.","outcome":"pay"}],"debrief":"There's no cure to buy; refuse the sellers and lean on real support and a professional.","relearn":"You can't 'cure' neurodivergence; refuse the sellers and trust real support, not false hope.","persona":"any","source":"refuse cure seller"},
  {"id":"nd-1111","cat":"drop-the-shame","type":"branch","hook":"Your mother-in-law insists the diagnosis is a 'nazar' (evil eye) to hide.","options":[{"text":"Gently say it's not nazar and you won't hide who he is","consequence":"You refuse the shame and keep your son's life in the open.","outcome":"refuse","best":true},{"text":"Agree to hide it to keep family peace","consequence":"Naming the truth protects him; hiding teaches him he is shameful.","outcome":"hide"}],"debrief":"It's not nazar and nothing to hide; refuse secrecy kindly and keep his life in the open.","relearn":"Neurodivergence isn't an evil eye to hide; secrecy feeds shame, openness lets support in.","persona":"Meena","source":"not nazar"},
  {"id":"nd-1112","cat":"drop-the-shame","type":"branch","hook":"You catch yourself snapping at your son mid-meltdown, then feel guilt.","options":[{"text":"Breathe, reconnect, and forgive yourself as a learning parent","consequence":"You repair with your son and let go of the guilt spiral.","outcome":"repair","best":true},{"text":"Spiral into 'I'm a terrible mother' for days","consequence":"Repairing helps you both; the guilt spiral drains your energy.","outcome":"spiral"}],"debrief":"Repair after a hard moment and drop the guilt; a loving, learning parent is what your child needs.","relearn":"Snapping once doesn't make you a bad parent; reconnect, forgive yourself, keep learning.","persona":"Divya","source":"repair and forgive"},
  {"id":"nd-1113","cat":"drop-the-shame","type":"branch","hook":"Neighbours whisper that 'screen time' made your daughter this way, in her earshot.","options":[{"text":"Tell them plainly screens don't cause it, and reassure her","consequence":"You correct the myth and protect her from believing it.","outcome":"correct","best":true},{"text":"Take her phone away in shame to seem a 'good' parent","consequence":"Correcting the myth helps; performing guilt teaches her she's the problem.","outcome":"perform"}],"debrief":"Screens don't cause neurodivergence; correct the myth and shield your child from it.","relearn":"Screens didn't cause it; correct that blame so your child never wears a fault not theirs.","persona":"Meena","source":"screens dont cause it"},
  {"id":"nd-1114","cat":"drop-the-shame","type":"branch","hook":"A teacher asks 'what did you do at home to make him like this?' at a meeting.","options":[{"text":"Calmly say it's no one's fault and refocus on the support he needs","consequence":"You move the room from blame to a plan for your son.","outcome":"refocus","best":true},{"text":"Apologise repeatedly and promise to 'try harder' at home","consequence":"Refocusing helps; over-apologising accepts a blame never yours.","outcome":"apologise"}],"debrief":"You didn't cause it; deflect the blame and steer toward the accommodations he needs.","relearn":"When blamed for your child's wiring, say it's no one's fault and refocus on support.","persona":"Meena","source":"blame to plan"},
  {"id":"nd-1115","cat":"drop-the-shame","type":"branch","hook":"Your partner says 'let's just not tell anyone, it'll be easier'.","options":[{"text":"Talk it through and agree to share on your terms with safe people","consequence":"You let support in without feeding the secrecy that isolates you.","outcome":"share","best":true},{"text":"Agree to total secrecy to avoid conflict","consequence":"Sharing with safe people lets help in; secrecy isolates and signals shame.","outcome":"secrecy"}],"debrief":"Openness on your terms, with people who can support you, beats hiding it in secrecy.","relearn":"Choose openness with safe people; secrecy isolates, and there's nothing shameful to hide.","persona":"Vikram","source":"share on your terms"},
  {"id":"nd-1116","cat":"drop-the-shame","type":"branch","hook":"At a wedding, your son melts down from the noise and lights, and aunties tut.","options":[{"text":"Take him to a quiet room, comfort him, and ignore the tutting","consequence":"You meet his overwhelm and protect him from the shame in the air.","outcome":"comfort","best":true},{"text":"Hiss at him to 'stop embarrassing the family'","consequence":"Comforting calms the storm; shaming adds fear to an overwhelmed child.","outcome":"shame"}],"debrief":"A meltdown is overwhelm, not misbehaviour; meet it with calm, not shame for onlookers.","relearn":"A meltdown is overwhelm, not embarrassment to punish; comfort your child, let the tutting go.","persona":"Meena","source":"comfort over scene"},
  {"id":"nd-1117","cat":"drop-the-shame","type":"branch","hook":"You're scrolling at 1am, drowning in 'what if I'd noticed sooner?' guilt.","options":[{"text":"Close the phone, name that a late diagnosis isn't failure, and rest","consequence":"You break the spiral and save your energy for your child.","outcome":"rest","best":true},{"text":"Keep reading 'early signs I missed' posts till dawn","consequence":"Naming it isn't failure frees you; the spiral just deepens guilt.","outcome":"spiral"}],"debrief":"Late diagnoses are common, not your failure; rest, and put tomorrow's energy into support.","relearn":"A late diagnosis isn't failure; drop the 2am what-ifs and save your energy for your child.","persona":"Divya","source":"break the spiral"},
  {"id":"nd-1118","cat":"drop-the-shame","type":"spot","hook":"Spot the two shaming lines an aunt drops at tea (the ones that pin blame).","scene":[{"id":"a","text":"\"You must have spoiled him rotten\"","trick":true},{"id":"b","text":"\"He has such a sharp memory\"","trick":false},{"id":"c","text":"\"Hide it or no one will marry your daughter\"","trick":true},{"id":"d","text":"\"Tell me how I can help out\"","trick":false},{"id":"e","text":"\"He drew that whole train from memory\"","trick":false}],"why":"'You spoiled him' and 'hide it or no one will marry her' pin blame and shame; the rest are kind or neutral.","relearn":"Blame myths like 'you spoiled him' and 'hide it' are the shaming lines to catch and let go.","persona":"any","source":"catch the shaming lines"},
  {"id":"nd-1119","cat":"drop-the-shame","type":"spot","hook":"Spot the two false 'cause or cure' claims in this forwarded message.","scene":[{"id":"a","text":"\"Vaccines secretly cause autism\"","trick":true},{"id":"b","text":"\"Support helps children thrive\"","trick":false},{"id":"c","text":"\"₹50,000 detox removes it in weeks\"","trick":true},{"id":"d","text":"\"A qualified professional can assess your child\"","trick":false},{"id":"e","text":"\"Neurodivergence is lifelong\"","trick":false}],"why":"'Vaccines cause autism' and a 'detox that removes it' are the false cause-and-cure claims; the rest are true.","relearn":"Catch debunked claims like 'vaccines cause autism' and 'a detox cures it'; there's no cause to blame or cure to buy.","persona":"any","source":"catch cause-cure claims"},
  {"id":"nd-1120","cat":"drop-the-shame","type":"spot","hook":"Spot the two thoughts in this 1am spiral that are shame, not truth.","scene":[{"id":"a","text":"\"I broke my child somehow\"","trick":true},{"id":"b","text":"\"He's overwhelmed, not naughty\"","trick":false},{"id":"c","text":"\"A better mother would have prevented this\"","trick":true},{"id":"d","text":"\"It's no one's fault\"","trick":false},{"id":"e","text":"\"Support can help him flourish\"","trick":false}],"why":"'I broke my child' and 'a better mother would have prevented this' are shame talking, not truth; the rest are true.","relearn":"Catch shame-thoughts like 'I broke my child' and 'a better mother would have prevented it'; they're false.","persona":"Meena","source":"catch the shame-thoughts"},
  {"id":"nd-1121","cat":"drop-the-shame","type":"spot","hook":"At a clinic waiting room, spot the two myths other parents repeat.","scene":[{"id":"a","text":"\"Strict discipline fixes this behaviour\"","trick":true},{"id":"b","text":"\"Meltdowns are overwhelm, not defiance\"","trick":false},{"id":"c","text":"\"Good families keep it a secret\"","trick":true},{"id":"d","text":"\"Stimming is just him self-soothing\"","trick":false},{"id":"e","text":"\"A diagnosis opens the door to support\"","trick":false}],"why":"'Strict discipline fixes it' and 'good families keep it secret' are myths; the rest are accurate.","relearn":"Catch myths like 'discipline fixes it' and 'hide it'; you can't punish wiring away and secrecy only isolates.","persona":"any","source":"catch waiting-room myths"},
  {"id":"nd-1122","cat":"drop-the-shame","type":"spot","hook":"Spot the two cruel labels in this relative's voice note (the ones that shame your child).","scene":[{"id":"a","text":"\"He's just a stubborn, badly-raised boy\"","trick":true},{"id":"b","text":"\"He notices details nobody else does\"","trick":false},{"id":"c","text":"\"This is a curse on your house\"","trick":true},{"id":"d","text":"\"Bring him over, we'd love to see him\"","trick":false},{"id":"e","text":"\"He learns differently, and that's okay\"","trick":false}],"why":"'Badly-raised, stubborn boy' and 'a curse on your house' are cruel, false labels; the rest are warm or true.","relearn":"Catch cruel labels like 'badly-raised' and 'a curse'; they're untrue blame your child should never wear.","persona":"Meena","source":"catch cruel labels"},
  {"id":"nd-1123","cat":"drop-the-shame","type":"role-play","hook":"Your sister says 'don't post about his diagnosis, people will talk'. You want to answer kindly but firmly.","setup":"Answer kindly but firmly:","yourLine":[{"text":"\"I won't hide who he is to please gossips; sharing on my terms is how support reaches us.\"","best":true},{"text":"\"You're right, maybe it's better people don't know.\""}],"relearn":"Refusing to hide your child, on your own terms, keeps support flowing and tells him there's nothing to be ashamed of.","persona":"Meena","source":"wont hide him"},
  {"id":"nd-1124","cat":"drop-the-shame","type":"role-play","hook":"At school pickup another parent says 'you must feel so unlucky'. You want to gently reframe it.","setup":"Gently reframe it:","yourLine":[{"text":"\"Not unlucky, he's wonderful; the diagnosis just helped us understand and support him better.\"","best":true},{"text":"\"Yes, we've had such bad luck, it's been a tragedy.\""}],"relearn":"Reframing pity as understanding tells everyone, and yourself, that your child is not a tragedy but a whole person.","persona":"Meena","source":"not unlucky"},
  {"id":"nd-1125","cat":"drop-the-shame","type":"role-play","hook":"Your own mother says 'you brought this on by working too much'. You want to set it down without a fight.","setup":"Set it down gently:","yourLine":[{"text":"\"My job didn't cause this, Ma; no one did. Blaming me won't help him, but support will.\"","best":true},{"text":"\"Maybe you're right, I should have stayed home.\""}],"relearn":"Naming that no one's choices caused it stops a false blame from taking root in you or being passed to your child.","persona":"Meena","source":"job didnt cause it"},
  {"id":"nd-1126","cat":"drop-the-shame","type":"role-play","hook":"A salesman swears his programme will 'make your son normal'. You want to decline clearly.","setup":"Decline clearly:","yourLine":[{"text":"\"There's no cure to buy, and he doesn't need to be 'normal'; we'll stick with real support, thank you.\"","best":true},{"text":"\"Okay, maybe we should try it, just in case it works.\""}],"relearn":"Refusing a 'cure' protects your family from false hope; your child needs support and acceptance, not fixing.","persona":"Vikram","source":"no cure to buy"},
  {"id":"nd-1127","cat":"drop-the-shame","type":"role-play","hook":"After a public meltdown a stranger mutters 'control your child'. You want to answer with calm dignity.","setup":"Answer with calm dignity:","yourLine":[{"text":"\"He's overwhelmed, not misbehaving, and I'm helping him; thanks for your patience.\"","best":true},{"text":"\"Sorry, sorry, I know, he's just impossible.\""}],"relearn":"Calmly naming overwhelm, instead of over-apologising, refuses the shame and models for your child that he's okay.","persona":"Meena","source":"overwhelmed not misbehaving"},
  {"id":"nd-1128","cat":"drop-the-shame","type":"role-play","hook":"A friend confides she's hiding her son's diagnosis out of shame. You want to reassure her.","setup":"Reassure her:","yourLine":[{"text":"\"It's no one's fault, and you've nothing to hide; sharing on your terms lets the support in.\"","best":true},{"text":"\"Yes, best to keep it quiet, people are so judgemental.\""}],"relearn":"Telling another parent it's no one's fault and openness helps passes on the relief instead of the shame.","persona":"Priya","source":"reassure a friend"},
  {"id":"nd-1129","cat":"drop-the-shame","type":"role-play","hook":"Your son overhears 'what's wrong with him?' and looks up at you, worried. You want to answer for him.","setup":"Answer warmly, for him:","yourLine":[{"text":"\"Nothing's wrong; his brain just works differently, and we love exactly how he is.\"","best":true},{"text":"\"Nothing, nothing, ignore them.\""}],"relearn":"Answering 'nothing's wrong, his brain works differently' shields your child and tells him he's whole and loved.","persona":"Meena","source":"nothing wrong with him"},
  {"id":"nd-1130","cat":"drop-the-shame","type":"match","hook":"Match each blame myth to the calm, true reply that lifts the shame.","pairs":[{"left":"\"Screens caused it\"","right":"He was wired this way from birth"},{"left":"\"You spoiled him\"","right":"Meltdowns are overwhelm, not spoiling"},{"left":"\"It's a curse\"","right":"It's wiring, not karma or a curse"},{"left":"\"Just buy a cure\"","right":"There's no cure to buy, only support"},{"left":"\"Hide the diagnosis\"","right":"Openness on my terms lets help in"}],"relearn":"Every blame myth, screens, spoiling, curses, cures, hiding, has a calm true reply that lifts the shame.","persona":"any","source":"myth to reply"},
  {"id":"nd-1131","cat":"drop-the-shame","type":"match","hook":"Match each false belief to the fact that debunks it.","pairs":[{"left":"Vaccines trigger autism","right":"Disproven; that study was fraud"},{"left":"They'll grow out of it","right":"Neurodivergence is lifelong"},{"left":"Bad parenting causes it","right":"It's how the brain is wired"},{"left":"A detox can cure it","right":"No diet or detox cures it"},{"left":"It's nobody's nazar","right":"It's not an evil eye or a sin"}],"relearn":"Vaccines, 'growing out of it', bad parenting, detoxes and nazar are myths; each has a plain fact that debunks it.","persona":"any","source":"belief to fact"},
  {"id":"nd-1132","cat":"drop-the-shame","type":"match","hook":"Match each shame-trap to the kinder move that frees the family.","pairs":[{"left":"Hiding the child away","right":"Sharing openly, on your terms"},{"left":"Endless self-blame","right":"Refocusing on support"},{"left":"Chasing a miracle cure","right":"Leaning on real, proven support"},{"left":"Over-apologising for him","right":"Calmly naming it's no one's fault"},{"left":"Carrying it all in silence","right":"Telling one trusted person"}],"relearn":"Each shame-trap, hiding, self-blame, chasing cures, apologising, silence, has a kinder move that frees the family.","persona":"any","source":"trap to free move"},
  {"id":"nd-1133","cat":"drop-the-shame","type":"match","hook":"Match each cutting comment to the calm boundary that ends the blame.","pairs":[{"left":"\"Control your child\"","right":"\"He's overwhelmed; I'm helping him\""},{"left":"\"You're so unlucky\"","right":"\"Not unlucky, he's wonderful\""},{"left":"\"What did you do wrong?\"","right":"\"No one did anything; let's help him\""},{"left":"\"Just discipline him harder\"","right":"\"You can't punish wiring away\""},{"left":"\"Keep it a family secret\"","right":"\"Secrecy only feeds the stigma\""}],"relearn":"Cutting comments, 'control him', 'unlucky', 'what did you do', 'discipline him', 'keep it secret', each meet a calm boundary.","persona":"any","source":"comment to boundary"},
  {"id":"nd-1134","cat":"drop-the-shame","type":"match","hook":"Match each parent's feeling to the steadying truth that meets it.","pairs":[{"left":"Grief for the path you imagined","right":"You can grieve and still love him"},{"left":"Guilt that you caused it","right":"You caused nothing; no one's fault"},{"left":"Fear of others' judgement","right":"Their misunderstanding isn't your shame"},{"left":"Exhaustion from coping alone","right":"You're allowed to ask for support"},{"left":"Shame after a public meltdown","right":"Overwhelm isn't yours to be ashamed of"}],"relearn":"Grief, guilt, fear, exhaustion and shame each meet a steadying truth; the feeling is real, the blame is not.","persona":"any","source":"feeling truth"},
  {"id":"nd-1135","cat":"drop-the-shame","type":"strike-rewrite","hook":"\"If I just pray hard enough, the autism will go away.\"","myth":{"un":"If I just pray hard enough, the autism will go away.","re":"Faith can comfort you, but no amount of prayer removes neurodivergence; your child isn't broken and needs support, not a cure.","why":"There's nothing to undo, only a child to support."},"relearn":"Prayer may comfort you, but it won't 'remove' your child's wiring; they need understanding and support, not curing.","persona":"any","source":"prayer not cure"},
  {"id":"nd-1136","cat":"drop-the-shame","type":"strike-rewrite","hook":"\"My child won't get married or work, so why even tell people?\"","myth":{"un":"My child won't get married or work, so why even tell people?","re":"Neurodiverse people build full lives, relationships and careers; writing off your child's future only limits the support they get now.","why":"A diagnosis predicts support needs, not a ceiling."},"relearn":"A diagnosis isn't a ceiling on your child's future; with support, neurodiverse people build full, rich lives.","persona":"Meena","source":"not a ceiling"},
  {"id":"nd-1170","cat":"strengths-and-wellbeing","type":"strike-rewrite","hook":"\"Praising my child will just make them lazy and big-headed.\"","myth":{"un":"Praising my child will just make them lazy and big-headed.","re":"Praising real effort and strengths builds a neurodiverse child's confidence and motivation, not laziness.","why":"Felt confidence fuels effort, not complacency."},"relearn":"Praising genuine effort and strengths grows a neurodiverse child's confidence and drive; it doesn't spoil them.","persona":"Meena","source":"praise builds confidence"},
  {"id":"nd-1171","cat":"strengths-and-wellbeing","type":"strike-rewrite","hook":"\"My child should toughen up and learn to handle a meltdown alone.\"","myth":{"un":"My child should toughen up and learn to handle a meltdown alone.","re":"A child in a meltdown is overwhelmed, not weak; calm co-regulation now is how they slowly learn to self-soothe.","why":"Coping grows from borrowed calm, not isolation."},"relearn":"A child can't 'toughen up' out of a meltdown alone; calm co-regulation is how self-soothing skills are built.","persona":"Meena","source":"co-regulation builds coping"},
  {"id":"nd-1172","cat":"strengths-and-wellbeing","type":"strike-rewrite","hook":"\"If I let my child draw all day, that 'obsession' will hold them back in life.\"","myth":{"un":"If I let my child draw all day, that 'obsession' will hold them back in life.","re":"An intense interest is a strength to feed; deep passions often grow into real skills, focus and even a future path.","why":"Today's obsession can be tomorrow's expertise."},"relearn":"An intense interest is a strength to feed, not an 'obsession' to shut down; it can become something amazing.","persona":"Meena","source":"feed the passion"},
  {"id":"nd-1173","cat":"strengths-and-wellbeing","type":"strike-rewrite","hook":"\"My child seems anxious all the time. That's just part of autism, nothing to do.\"","myth":{"un":"My child seems anxious all the time. That's just part of autism, nothing to do.","re":"Anxiety often rides alongside autism but is a real, treatable need on its own, worth taking seriously, not shrugging off.","why":"A co-occurring need can be eased, not endured."},"relearn":"Don't dismiss steady anxiety as 'just autism'; it's often a treatable co-occurring need worth support.","persona":"Divya","source":"anxiety is treatable"},
  {"id":"nd-1174","cat":"strengths-and-wellbeing","type":"strike-rewrite","hook":"\"After a meltdown I should explain how much trouble they caused, so it won't happen again.\"","myth":{"un":"After a meltdown I should explain how much trouble they caused, so it won't happen again.","re":"After a meltdown a child needs reconnection and reassurance, not a lecture; reproach adds shame and fear, not control.","why":"Safety, not shame, rebuilds a flooded child."},"relearn":"Reconnect after a meltdown with reassurance, not reproach; a lecture adds shame, it doesn't prevent the next wave.","persona":"Meena","source":"reconnect not reproach"},
  {"id":"nd-1175","cat":"strengths-and-wellbeing","type":"strike-rewrite","hook":"\"My child is a bundle of problems I have to manage every single day.\"","myth":{"un":"My child is a bundle of problems I have to manage every single day.","re":"Your child is a whole, wonderful person, far more than a list of challenges; their gifts and joy are just as real.","why":"A child is a person to know, not a problem to fix."},"relearn":"Your neurodiverse child is a whole, wonderful person, not a bundle of problems; their strengths are as real as their struggles.","persona":"Meena","source":"whole person not problem"},
  {"id":"nd-1176","cat":"strengths-and-wellbeing","type":"strike-rewrite","hook":"\"Celebrating small wins is silly. They're things every other child just does.\"","myth":{"un":"Celebrating small wins is silly. They're things every other child just does.","re":"For your child a 'small' win can be hard-won; celebrating it, not comparing it to others, builds real self-worth.","why":"Progress is measured against their own path."},"relearn":"Celebrate your child's small wins against their own path; comparing them to other kids chips at self-worth.","persona":"any","source":"celebrate small wins"},
  {"id":"nd-1177","cat":"strengths-and-wellbeing","type":"sort","hook":"Sort: a calm response to a meltdown, or one that escalates it?","items":[{"id":"a","text":"Lowering your voice and your body"},{"id":"b","text":"Shouting back to 'snap them out of it'"},{"id":"c","text":"Reducing noise and bright light"},{"id":"d","text":"Threatening to take their tablet away"},{"id":"e","text":"Offering a familiar comfort item"},{"id":"f","text":"Grabbing and forcing them to be still"}],"bins":[{"id":"calm","label":"Calms it","valence":"pos"},{"id":"escalate","label":"Escalates it","valence":"neg"}],"key":{"a":"calm","b":"escalate","c":"calm","d":"escalate","e":"calm","f":"escalate"},"relearn":"A meltdown calms when you lower your voice, dim the input and offer comfort; shouting, threats and force only escalate it.","persona":"Meena","source":"calm vs escalate meltdown"},
  {"id":"nd-1178","cat":"strengths-and-wellbeing","type":"sort","hook":"Sort: a strength worth feeding, or a behaviour to handle with care?","items":[{"id":"a","text":"Deep focus on a favourite topic"},{"id":"b","text":"Melting down in a loud bazaar"},{"id":"c","text":"Spotting patterns others miss"},{"id":"d","text":"Refusing a sudden change of plan"},{"id":"e","text":"Honest, fair-minded comments"},{"id":"f","text":"Shutting down when overwhelmed"}],"bins":[{"id":"strength","label":"Strength to feed","valence":"pos"},{"id":"care","label":"Needs care, not blame","valence":"uhoh"}],"key":{"a":"strength","b":"care","c":"strength","d":"care","e":"strength","f":"care"},"relearn":"Deep focus, pattern-spotting and honesty are strengths to feed; meltdowns, rigidity and shutdowns are overwhelm to meet with care, not blame.","persona":"any","source":"strength vs needs care"},
  {"id":"nd-1179","cat":"strengths-and-wellbeing","type":"sort","hook":"Sort: this builds self-worth, or this corrects-only and wears it down?","items":[{"id":"a","text":"'I love how your mind works'"},{"id":"b","text":"'Why can't you be like your cousin'"},{"id":"c","text":"'You worked so hard on that'"},{"id":"d","text":"'Everyone's staring, behave'"},{"id":"e","text":"'Tell me more about your project'"},{"id":"f","text":"'You always ruin family outings'"}],"bins":[{"id":"worth","label":"Builds self-worth","valence":"pos"},{"id":"wears","label":"Wears it down","valence":"neg"}],"key":{"a":"worth","b":"wears","c":"worth","d":"wears","e":"worth","f":"wears"},"relearn":"Warmth, effort-praise and curiosity build self-worth; comparison, public shaming and 'you always' wear it down.","persona":"Meena","source":"worth vs wears down"},
  {"id":"nd-1180","cat":"strengths-and-wellbeing","type":"branch","hook":"At a family wedding your son starts melting down from the noise and crowd.","options":[{"text":"Take him to a quiet room and stay calm until it passes","consequence":"He settles, and learns the world can feel safer.","outcome":"co-regulate","best":true},{"text":"Hiss at him to stop embarrassing you","consequence":"Quiet and calm pass the wave; shaming him in the noise deepens the overwhelm."}],"debrief":"A meltdown in a crowd is overwhelm; ease the overload and co-regulate, don't shame.","relearn":"Meet a meltdown by easing the overload and staying calm; shaming only escalates it.","persona":"Meena","source":"wedding meltdown"},
  {"id":"nd-1181","cat":"strengths-and-wellbeing","type":"branch","hook":"Your daughter has seemed flat and withdrawn for weeks since starting a new school.","options":[{"text":"Take the low mood seriously and seek support if it lingers","consequence":"You catch a real, treatable need early.","outcome":"wellbeing","best":true},{"text":"Decide it's just her autism, nothing to do","consequence":"Taken seriously, it's a treatable need; 'just autism' leaves her struggling alone."}],"debrief":"Persistent low mood is worth taking seriously, not dismissing as 'just the diagnosis'.","relearn":"Don't dismiss lasting low mood as 'just autism'; take it seriously and seek support.","persona":"Divya","source":"withdrawn for weeks"},
  {"id":"nd-1182","cat":"strengths-and-wellbeing","type":"branch","hook":"Your son spends hours arranging his toy cars by colour; a relative calls it 'weird'.","options":[{"text":"Sit with him, ask about his system, treat it as a strength","consequence":"He feels seen, and his deep focus is honoured.","outcome":"feed-strength","best":true},{"text":"Sweep the cars away, tell him to play 'normally'","consequence":"Joining his world feeds the strength; shutting it down says his play is wrong."}],"debrief":"An intense, ordered interest is deep focus to honour, not a 'weird' habit to stop.","relearn":"Honour an intense interest as a strength to feed; don't shut it down.","persona":"Vikram","source":"sorting cars strength"},
  {"id":"nd-1183","cat":"strengths-and-wellbeing","type":"branch","hook":"After a hard meltdown, your child curls up looking ashamed and won't meet your eye.","options":[{"text":"Sit close and reassure him: it's over, he's not in trouble","consequence":"He feels safe again, and trusts you next time.","outcome":"reconnect","best":true},{"text":"List what he did wrong so he 'learns'","consequence":"Reassurance rebuilds safety; a list of wrongs shames an overwhelmed child."}],"debrief":"After a meltdown, reconnect with reassurance, not reproach, to rebuild safety.","relearn":"Reconnect after a meltdown with warmth; reproach only deepens a child's shame.","persona":"Meena","source":"reconnect after meltdown"},
  {"id":"nd-1184","cat":"strengths-and-wellbeing","type":"match","hook":"Match each neurodiverse strength to where it can shine.","pairs":[{"left":"Deep focus (autism)","right":"Mastering one subject in real depth"},{"left":"High energy (ADHD)","right":"Sport, dance and hands-on play"},{"left":"Pattern recognition","right":"Puzzles, coding and music"},{"left":"Big-picture thinking (dyslexia)","right":"Storytelling and inventing ideas"},{"left":"Strong sense of fairness","right":"Standing up for a friend"}],"relearn":"Deep focus, high energy, pattern recognition, big-picture thinking and fairness each have real places to shine.","persona":"any","source":"strength to where it shines"},
  {"id":"nd-1185","cat":"strengths-and-wellbeing","type":"match","hook":"Match each warm parent line to what it protects in your child.","pairs":[{"left":"'I love how your brain works'","right":"Their self-worth"},{"left":"'It's over, you're not in trouble'","right":"Safety after a meltdown"},{"left":"'Tell me everything about it'","right":"A treasured interest"},{"left":"'You tried so hard at that'","right":"Their effort and courage"},{"left":"'I'm here, take your time'","right":"Calm during overwhelm"}],"relearn":"Warm, specific words protect a child's self-worth, safety, interests, effort and calm far more than correction does.","persona":"Meena","source":"line to what it protects"},
  {"id":"nd-1186","cat":"strengths-and-wellbeing","type":"reflect","hook":"Lensy: a child who hears 'I love the way your mind works' carries that voice for life. Worth saying often?","prompt":"What do you think?","options":["Worth it","I'll say it more","They deserve to hear it"],"affirm":"A neurodiverse child who often hears their mind is loved, not just corrected, grows up liking who they are.","relearn":"Telling your child you love how their mind works builds a self-worth that lasts long after the moment.","persona":"Meena","source":"love your mind"},
  {"id":"nd-1187","cat":"strengths-and-wellbeing","type":"reflect","hook":"Lensy: under every meltdown is a child who is overwhelmed, not bad. Does holding that change how you meet it?","prompt":"Sit with that.","options":["It changes a lot","Overwhelmed, not bad","I can stay calmer"],"affirm":"Seeing a meltdown as overwhelm, not badness, lets you meet it with calm co-regulation instead of anger.","relearn":"Holding 'overwhelmed, not bad' under a meltdown helps you respond with calm, not punishment.","persona":"Meena","source":"overwhelmed not bad"},
  {"id":"nd-1188","cat":"strengths-and-wellbeing","type":"reflect","hook":"Lensy: your child's intense passion lights them up like nothing else. What might it grow into?","prompt":"Picture it.","options":["A real skill","A future path","Just pure joy"],"affirm":"An intense interest is a strength to feed; given space, today's passion can grow into skill, confidence or a path.","relearn":"Your child's intense passion is a strength to feed; with space it can grow into skill, confidence and joy.","persona":"any","source":"passion grows"},
  {"id":"nd-1189","cat":"strengths-and-wellbeing","type":"reflect","hook":"Lensy: a child celebrated for who they are, not just corrected, grows up at home in their own skin. Worth aiming for?","prompt":"What's your take?","options":["Worth aiming for","At home in themselves","That's the goal"],"affirm":"A child who feels celebrated, not constantly corrected, grows up with self-worth and at home in their own skin.","relearn":"Aim to celebrate your child for who they are, not just correct them; it grows a lifelong sense of self-worth.","persona":"Meena","source":"celebrated not corrected"},
  {"id":"nd-1190","cat":"strengths-and-wellbeing","type":"spot","hook":"Spot the two lines that punish overwhelm instead of soothing it.","scene":[{"id":"a","text":"'Let's go somewhere quieter together'","trick":false},{"id":"b","text":"'Stop crying or no dinner for you'","trick":true},{"id":"c","text":"'I'll hold your hand till it passes'","trick":false},{"id":"d","text":"'You're doing this on purpose to spite me'","trick":true},{"id":"e","text":"'Take a slow breath with me'","trick":false}],"why":"Threatening 'no dinner' and accusing 'on purpose to spite me' punish overwhelm; offering quiet, a hand and a breath soothe it.","relearn":"Soothe overwhelm with calm and closeness; threats and 'you're doing it on purpose' punish a child who is flooded, not defiant.","persona":"Meena","source":"soothe not punish overwhelm"},
  {"id":"nd-1191","cat":"strengths-and-wellbeing","type":"spot","hook":"Spot the two lines that shame a child's strengths instead of feeding them.","scene":[{"id":"a","text":"'I love hearing about your rockets'","trick":false},{"id":"b","text":"'Stop obsessing, it's embarrassing'","trick":true},{"id":"c","text":"'Your honesty is a real gift'","trick":false},{"id":"d","text":"'Nobody cares about your weird facts'","trick":true},{"id":"e","text":"'Show me what you built today'","trick":false}],"why":"Calling a passion an embarrassing 'obsession' and 'weird facts nobody cares about' shame a strength; the other lines feed it with interest.","relearn":"Feed a child's passion with genuine interest; calling it an embarrassing 'obsession' shames a real strength.","persona":"any","source":"feed not shame strengths"},
  {"id":"nd-1192","cat":"strengths-and-wellbeing","type":"spot","hook":"Spot the two lines that compare and diminish your child.","scene":[{"id":"a","text":"'You're exactly who you're meant to be'","trick":false},{"id":"b","text":"'Why can't you be normal like them'","trick":true},{"id":"c","text":"'I'm proud of how you tried today'","trick":false},{"id":"d","text":"'Your sister never gives me this trouble'","trick":true},{"id":"e","text":"'There's no one quite like you'","trick":false}],"why":"'Why can't you be normal' and the sibling comparison diminish your child; the rest value who they are.","relearn":"Value your child for who they are; comparing them to a 'normal' kid or a sibling chips at self-worth.","persona":"Meena","source":"value not compare"},
  {"id":"nd-1193","cat":"strengths-and-wellbeing","type":"role-play","hook":"Grandma scolds your son for stimming, calling it a 'bad habit'. You want to protect him gently.","setup":"Protect his self-soothing:","yourLine":[{"text":"\"That hand-flapping helps him calm down, Ma. It's not a bad habit, it's how he copes.\"","best":true},{"text":"\"Stop that at once, you're upsetting your grandmother.\""}],"relearn":"Defending a child's stimming as self-soothing, not a 'bad habit' to stop, protects both his calm and his self-worth.","persona":"Vikram","source":"protect stimming"},
  {"id":"nd-1194","cat":"strengths-and-wellbeing","type":"role-play","hook":"Your child just managed a hard transition that usually triggers tears. You want to celebrate the win.","setup":"Name the win:","yourLine":[{"text":"\"You moved from the park to the car all on your own today. I saw how hard that was. Well done.\"","best":true},{"text":"\"Finally, no drama for once.\""}],"relearn":"Naming a hard-won transition as a real win, with specific warmth, builds confidence far more than relief framed as 'finally'.","persona":"Meena","source":"name the transition win"},
  {"id":"nd-1195","cat":"strengths-and-wellbeing","type":"role-play","hook":"Mid-meltdown, your daughter is sobbing on the floor. You crouch down to co-regulate.","setup":"Speak calm into the storm:","yourLine":[{"text":"\"I'm right here. You're safe. We'll just breathe together until it passes.\"","best":true},{"text":"\"Get up right now, people are looking at us.\""}],"relearn":"Calm, safe, present words co-regulate a meltdown; demanding she get up because 'people are looking' adds shame to overwhelm.","persona":"Meena","source":"calm into the storm"},
  {"id":"nd-1196","cat":"strengths-and-wellbeing","type":"role-play","hook":"Your son says 'I'm so stupid, everyone in class is better than me.' You want to reframe with truth.","setup":"Reframe his worth:","yourLine":[{"text":"\"You're not stupid. Your brain works differently, and it's brilliant at things theirs aren't.\"","best":true},{"text":"\"Don't say that, just try harder than them.\""}],"relearn":"Reframing 'I'm stupid' as a differently-wired, capable brain rebuilds self-worth; 'try harder' leaves the shame in place.","persona":"Meena","source":"reframe i'm stupid"},
  {"id":"nd-1198","cat":"strengths-and-wellbeing","type":"strike-rewrite","hook":"\"If I keep co-regulating his meltdowns, he'll never learn to cope on his own.\"","myth":{"un":"If I keep co-regulating his meltdowns, he'll never learn to cope on his own.","re":"Co-regulation is the launchpad for self-regulation; a child borrows your calm now and slowly grows their own.","why":"Independence is built on early support, not denial of it."},"relearn":"Co-regulation isn't a crutch; it's the launchpad from which a child's own coping skills grow over time.","persona":"Meena","source":"co-regulation is a launchpad"},
  {"id":"nd-1199","cat":"strengths-and-wellbeing","type":"sort","hook":"Sort: this honours your child's interest, or this dismisses it?","items":[{"id":"a","text":"Asking them to teach you about it"},{"id":"b","text":"'Not that boring topic again'"},{"id":"c","text":"Finding a book on their passion"},{"id":"d","text":"Rolling your eyes when they start"},{"id":"e","text":"Joining their game on their terms"},{"id":"f","text":"'Real kids don't care about that'"}],"bins":[{"id":"honour","label":"Honours the interest","valence":"pos"},{"id":"dismiss","label":"Dismisses it","valence":"neg"}],"key":{"a":"honour","b":"dismiss","c":"honour","d":"dismiss","e":"honour","f":"dismiss"},"relearn":"Asking, reading and joining in honour a child's passion; eye-rolls and 'boring again' dismiss a real strength.","persona":"any","source":"honour vs dismiss interest"},
  {"id":"nd-1200","cat":"strengths-and-wellbeing","type":"sort","hook":"Sort: a sign of co-occurring anxiety to take seriously, or an ordinary good day?","items":[{"id":"a","text":"Refusing to leave the house for days"},{"id":"b","text":"Happily showing you a new drawing"},{"id":"c","text":"Stomach aches every school morning"},{"id":"d","text":"Playing easily with a cousin"},{"id":"e","text":"Waking with nightmares most nights"},{"id":"f","text":"Laughing along at a silly video"}],"bins":[{"id":"watch","label":"Take seriously","valence":"uhoh"},{"id":"fine","label":"An ordinary good day","valence":"pos"}],"key":{"a":"watch","b":"fine","c":"watch","d":"fine","e":"watch","f":"fine"},"relearn":"House refusal, daily stomach aches and nightmares are anxiety signs to take seriously; play, drawing and laughter are just a good day.","persona":"Divya","source":"anxiety sign vs good day"},
  {"id":"nd-1201","cat":"strengths-and-wellbeing","type":"branch","hook":"Your child proudly shows you a 'messy' painting they spent an hour on.","options":[{"text":"Light up and ask them to tell you all about it","consequence":"They glow, and learn their creativity is treasured.","outcome":"celebrate","best":true},{"text":"Point out where it's wrong so they 'improve'","consequence":"Warm interest feeds their joy; leading with corrections says their best isn't enough."}],"debrief":"Meet a child's proud creation with delight first; corrections-first chips at the joy.","relearn":"Celebrate creative effort first; leading with what's 'wrong' says their best isn't enough.","persona":"any","source":"proud painting"},
  {"id":"nd-1202","cat":"strengths-and-wellbeing","type":"branch","hook":"Your son is overstimulated at a birthday party and starts covering his ears and rocking.","options":[{"text":"Step outside with him for a calm break, no fuss","consequence":"He resets and can rejoin when ready.","outcome":"break","best":true},{"text":"Tell him to stop rocking and act normal","consequence":"A quiet break lets him reset; shaming his self-soothing stresses a flooded child."}],"debrief":"Rocking and ear-covering are self-soothing, not misbehaving; offer a calm break.","relearn":"Let an overstimulated child take a calm break; rocking is self-soothing, not bad behaviour.","persona":"Vikram","source":"party overstimulation"},
  {"id":"nd-1203","cat":"strengths-and-wellbeing","type":"match","hook":"Match each moment to the wellbeing response it calls for.","pairs":[{"left":"A win they're proud of","right":"Celebrate it out loud"},{"left":"The storm of a meltdown","right":"Calm, safety, co-regulation"},{"left":"Shame after melting down","right":"Reassurance, not reproach"},{"left":"Weeks of low, flat mood","right":"Take it seriously, seek support"},{"left":"A passion lighting them up","right":"Feed it with time and interest"}],"relearn":"A win, a meltdown, post-meltdown shame, a long low mood and a passion each call for a different, caring response.","persona":"Meena","source":"moment to response"},
  {"id":"nd-1204","cat":"strengths-and-wellbeing","type":"match","hook":"Match each child's self-doubt to a truthful, kind reframe.","pairs":[{"left":"'I'm so stupid'","right":"'Your brain just works differently'"},{"left":"'Everyone hates me'","right":"'You feel alone right now, I'm here'"},{"left":"'I always mess up'","right":"'You tried something hard today'"},{"left":"'I'm a burden to you'","right":"'You're a joy I chose and love'"},{"left":"'I'll never fit in'","right":"'The right people will love you as you are'"}],"relearn":"Each harsh self-belief a child voices can be met with a truthful, warm reframe that rebuilds their self-worth.","persona":"Meena","source":"self-doubt to reframe"},
  {"id":"nd-1205","cat":"strengths-and-wellbeing","type":"reflect","hook":"Lensy: looking back, which of your child's 'difficult' traits is secretly a strength in disguise?","prompt":"Sit with that.","options":["Their deep focus","Their honesty","Their boundless energy"],"affirm":"Many traits called 'difficult' are strengths in disguise; naming them as strengths changes how your child sees themselves.","relearn":"A trait that looks 'difficult' is often a strength in disguise; naming it as one reshapes your child's self-image.","persona":"any","source":"strength in disguise"},
  {"id":"nd-1206","cat":"strengths-and-wellbeing","type":"reflect","hook":"Lensy: when your child is most overwhelmed, what does the calmest version of you sound like?","prompt":"Picture it.","options":["Soft and slow","'I'm right here'","Quiet and steady"],"affirm":"The calmest version of you is the anchor a flooded child borrows; your steadiness is what co-regulation is made of.","relearn":"Your calm, steady voice is the anchor an overwhelmed child borrows to find their way back to calm.","persona":"Meena","source":"calmest version of you"},
  {"id":"nd-1207","cat":"strengths-and-wellbeing","type":"spot","hook":"Spot the two lines that punish self-soothing instead of allowing it.","scene":[{"id":"a","text":"'Squeeze your fidget toy if it helps'","trick":false},{"id":"b","text":"'Stop flapping, people will laugh'","trick":true},{"id":"c","text":"'Rock as long as you need to'","trick":false},{"id":"d","text":"'Sit still and stop the noises'","trick":true},{"id":"e","text":"'Your headphones are right here'","trick":false}],"why":"'Stop flapping' and 'sit still, stop the noises' punish self-soothing; the rest allow the stims and tools that calm your child.","relearn":"Allow stimming, rocking and sensory tools that self-soothe your child; punishing them adds stress, not control.","persona":"any","source":"allow self-soothing"},
  {"id":"nd-1208","cat":"strengths-and-wellbeing","type":"role-play","hook":"Your daughter says other kids called her 'weird' at school today. You want to build her up.","setup":"Build her up with truth:","yourLine":[{"text":"\"Different isn't weird. Your mind sees things theirs can't, and that's something special.\"","best":true},{"text":"\"Just try to act more like the other girls.\""}],"relearn":"Reframing 'weird' as a special way of seeing builds a child's self-worth; 'act like the others' teaches her to mask.","persona":"Meena","source":"called weird at school"},
  {"id":"nd-1209","cat":"strengths-and-wellbeing","type":"role-play","hook":"Your son finally finished a puzzle that frustrated him for days. You want to mark the win.","setup":"Mark the hard-won win:","yourLine":[{"text":"\"You stuck with that even when it was so hard. Look what your patience did.\"","best":true},{"text":"\"About time, you should've finished that ages ago.\""}],"relearn":"Naming persistence and effort behind a hard-won win builds confidence; 'about time' sours it with shame.","persona":"any","source":"finished the puzzle"},
  {"id":"nd-1260","cat":"support-and-you","type":"strike-rewrite","hook":"\"A good mother manages her child alone and never needs anyone's help.\"","myth":{"un":"A good mother manages her child alone and never needs anyone's help.","re":"Leaning on a support network sustains you; doing it all alone is how devoted parents burn out.","why":"A sustained parent can sustain their child."},"relearn":"A good parent isn't one who copes alone; sharing the load and leaning on support keeps you going.","persona":"Meena","source":"not alone"},
  {"id":"nd-1261","cat":"support-and-you","type":"strike-rewrite","hook":"\"My own rest is selfish; every minute must go to my neurodiverse child.\"","myth":{"un":"My own rest is selfish; every minute must go to my neurodiverse child.","re":"Your rest isn't selfish; a rested parent has the patience and energy their child needs day after day.","why":"You can't pour from an empty cup."},"relearn":"Resting isn't selfish; your own wellbeing is part of your child's support, not a betrayal of it.","persona":"Divya","source":"rest not selfish"},
  {"id":"nd-1262","cat":"support-and-you","type":"strike-rewrite","hook":"\"There's a quick cure online if I just pay enough. It'll fix my child.\"","myth":{"un":"There's a quick cure online if I just pay enough. It'll fix my child.","re":"There's no miracle cure to buy; understanding, accommodation and qualified support are what truly help.","why":"Anyone selling a cure is selling false hope."},"relearn":"Chasing a paid 'cure' wastes hope and money; real support comes from understanding and qualified help.","persona":"any","source":"no miracle cure"},
  {"id":"nd-1263","cat":"support-and-you","type":"strike-rewrite","hook":"\"I have to be the expert and know every answer about my child's needs.\"","myth":{"un":"I have to be the expert and know every answer about my child's needs.","re":"You don't have to know it all; a learning, loving, supported parent is exactly what your child needs.","why":"Loving and learning beats knowing everything."},"relearn":"You don't have to be all-knowing; a learning, loving, supported parent is enough for your child.","persona":"any","source":"learning is enough"},
  {"id":"nd-1264","cat":"support-and-you","type":"strike-rewrite","hook":"\"Asking a relative to help means admitting I can't cope as a parent.\"","myth":{"un":"Asking a relative to help means admitting I can't cope as a parent.","re":"Bringing a willing relative in doubles your child's champions; asking for help is strength, not weakness.","why":"More hands mean more love around your child."},"relearn":"Asking a relative to help isn't failure; it shares the load and gives your child another champion.","persona":"Vikram","source":"ask for help"},
  {"id":"nd-1265","cat":"support-and-you","type":"strike-rewrite","hook":"\"Joining a parent support group is just sitting around complaining.\"","myth":{"un":"Joining a parent support group is just sitting around complaining.","re":"A parent support group offers real understanding and practical tips from people who truly get it.","why":"Shared experience hands you tools and relief."},"relearn":"A parent support group isn't just complaining; it gives understanding and practical tips that help.","persona":"any","source":"support group helps"},
  {"id":"nd-1266","cat":"support-and-you","type":"strike-rewrite","hook":"\"If I admit I'm struggling, people will think I don't love my child.\"","myth":{"un":"If I admit I'm struggling, people will think I don't love my child.","re":"Being honest that it's hard isn't a lack of love; it opens the door to the support that sustains you both.","why":"You can love fiercely and still be tired."},"relearn":"Admitting it's hard doesn't mean you love your child less; honesty lets the support you need in.","persona":"Divya","source":"honesty not failure"},
  {"id":"nd-1267","cat":"support-and-you","type":"strike-rewrite","hook":"\"A diagnosis app or quiz can tell me exactly what my child has.\"","myth":{"un":"A diagnosis app or quiz can tell me exactly what my child has.","re":"An app or quiz can't diagnose; only a qualified professional can assess and guide your child's care.","why":"A tool points you to a professional, never replaces one."},"relearn":"An app can't diagnose your child; a qualified professional assesses and guides specific care.","persona":"any","source":"not a quiz"},
  {"id":"nd-1268","cat":"support-and-you","type":"match","hook":"Match each parent worry to the right kind of support.","pairs":[{"left":"Feeling utterly alone","right":"Other parents who truly get it"},{"left":"Unsure of the diagnosis","right":"A qualified professional's assessment"},{"left":"Out of patience and energy","right":"Your own wellbeing care (g63)"},{"left":"No idea what strategy fits","right":"A therapist's tailored plan"},{"left":"A relative who wants to help","right":"A simple way to understand and act"}],"relearn":"Loneliness, uncertainty, exhaustion, strategy and a willing relative each have a support that fits.","persona":"any","source":"worry to support"},
  {"id":"nd-1269","cat":"support-and-you","type":"match","hook":"Match each helper to what they best offer a parent.","pairs":[{"left":"A peer parent","right":"Lived understanding and practical tips"},{"left":"A child therapist","right":"Assessment and tailored strategies"},{"left":"Looking After You (g63)","right":"Care for your own energy"},{"left":"A grandparent","right":"Extra hands and steady love"},{"left":"Tele-MANAS","right":"Free mental-health support, 14416"}],"relearn":"Peers, therapists, g63, family and Tele-MANAS each give a parent a different, real kind of support.","persona":"any","source":"helper to offer"},
  {"id":"nd-1270","cat":"support-and-you","type":"match","hook":"Match each tired moment to a small step that refills you.","pairs":[{"left":"Running on no sleep","right":"Trade a night shift with your partner"},{"left":"Haven't seen a friend in weeks","right":"A short call while the kettle boils"},{"left":"Carrying it all in your head","right":"Write one worry down and share it"},{"left":"No moment to yourself","right":"Ten quiet minutes that are just yours"},{"left":"Stuck on a hard day","right":"Message a parent who understands"}],"relearn":"Even on a hard day, small steps like a swap, a call, a note or ten minutes quietly refill a parent.","persona":"Divya","source":"tired to step"},
  {"id":"nd-1271","cat":"support-and-you","type":"match","hook":"Match each question a parent has to who can best answer it.","pairs":[{"left":"\"Does my child need assessing?\"","right":"A qualified professional"},{"left":"\"How did you handle bedtime?\"","right":"Another neurodiverse child's parent"},{"left":"\"What helps him learn at school?\"","right":"His teacher and a learning-support plan"},{"left":"\"Why am I so drained?\"","right":"Looking After You (g63)"},{"left":"\"Can I just talk to someone now?\"","right":"Tele-MANAS, 14416"}],"relearn":"Each parent question has a right place to ask: assessment, daily tips, school support, your own energy, someone now.","persona":"any","source":"question to who"},
  {"id":"nd-1272","cat":"support-and-you","type":"match","hook":"Match each way to bring family in to what it gives your child.","pairs":[{"left":"Explain his profile simply","right":"Relatives who understand, not judge"},{"left":"Give one concrete task","right":"A grandparent who helps, not hovers"},{"left":"Share what calms him","right":"Aunts and uncles who soothe, not scold"},{"left":"Invite them to a good day","right":"Bonds built on his strengths"},{"left":"Set a respectful limit","right":"Family who back you up"}],"relearn":"Explaining, giving a task, sharing what calms, inviting them in and setting limits turn family into champions.","persona":"Vikram","source":"family in"},
  {"id":"nd-1273","cat":"support-and-you","type":"match","hook":"Match each thing a parent might chase to whether it truly helps.","pairs":[{"left":"A 'special diet that cures it'","right":"False hope, no real help"},{"left":"A qualified assessment","right":"A real door to support"},{"left":"Coping in total silence","right":"Isolation that wears you down"},{"left":"A peer parent group","right":"Understanding and shared tips"},{"left":"Honest 'I need help'","right":"Support that sustains you"}],"relearn":"Cures and silence wear a parent down; assessment, peers and honest asks truly help.","persona":"any","source":"chase or help"},
  {"id":"nd-1274","cat":"support-and-you","type":"match","hook":"Match each parent feeling to a gentle reminder.","pairs":[{"left":"\"I should manage alone\"","right":"Support is wise, not weak"},{"left":"\"I must be perfect\"","right":"Learning and loving is enough"},{"left":"\"My rest is selfish\"","right":"A rested parent shows up better"},{"left":"\"No one understands\"","right":"Peer parents truly do"},{"left":"\"It's all on me\"","right":"Champions can be invited in"}],"relearn":"Each heavy feeling has a truer reminder: support is wise, learning is enough, rest helps, you're not alone.","persona":"any","source":"feeling to reminder"},
  {"id":"nd-1275","cat":"support-and-you","type":"match","hook":"Match each support route to the relief it brings.","pairs":[{"left":"A WhatsApp group of ND parents","right":"Quick tips at 2am from people who get it"},{"left":"A standing weekly handover","right":"One evening that's reliably yours"},{"left":"A therapist on retainer","right":"Strategies tailored to your child"},{"left":"A trusted relative on call","right":"Backup when you're stretched thin"},{"left":"Your own check-in via g63","right":"Catching burnout before it lands"}],"relearn":"A parent group, a handover, a therapist, a relative and a self check-in each bring their own real relief.","persona":"any","source":"route to relief"},
  {"id":"nd-1276","cat":"support-and-you","type":"branch","hook":"You haven't slept in weeks and snapped at your child today.","options":[{"text":"Arrange a real break and ask someone to take a shift","consequence":"You refill enough to be the calm parent he needs.","outcome":"refill","best":true},{"text":"Vow to try harder and push through alone","consequence":"A break refills you; pushing on with no sleep only frays your patience further."}],"debrief":"When worn down, arrange a real break. A rested parent sustains their child.","relearn":"Don't just push harder on empty; arrange a break and share a shift so you can keep showing up.","persona":"Divya","source":"arrange a break"},
  {"id":"nd-1277","cat":"support-and-you","type":"branch","hook":"A neighbour swears a special diet 'cured' a child's autism.","options":[{"text":"Thank her, but check any change with your professional first","consequence":"You protect your child and keep trusted guidance.","outcome":"check-pro","best":true},{"text":"Pour your savings into the 'cure' right away","consequence":"Checking with a professional keeps your child safe; a 'cure' drains hope and money for nothing."}],"debrief":"Run any 'cure' claim past a professional; no diet cures neurodivergence.","relearn":"There's no miracle cure; check any big claim with a professional rather than chasing it on hope.","persona":"any","source":"check the cure"},
  {"id":"nd-1278","cat":"support-and-you","type":"branch","hook":"You feel completely alone. No one seems to understand your child.","options":[{"text":"Find a parent group of others raising neurodiverse kids","consequence":"You discover you're far from alone and gain real support.","outcome":"find-peers","best":true},{"text":"Decide no one could understand and stay silent","consequence":"A peer group shows you're not alone; staying silent leaves you isolated with the whole weight."}],"debrief":"Seek other parents of neurodiverse kids; their tips remind you you're not alone.","relearn":"You're not alone; find a parent group whose understanding and tips lighten the load.","persona":"Divya","source":"find peers"},
  {"id":"nd-1279","cat":"support-and-you","type":"branch","hook":"Your partner says 'just handle it, you're better with him' and steps back.","options":[{"text":"Invite them in to learn and share the load as a team","consequence":"Your child gets two engaged champions and you stop carrying it all.","outcome":"team-up","best":true},{"text":"Sigh and silently take on everything yourself","consequence":"Sharing the load doubles your child's champions; carrying it all alone slowly burns you out."}],"debrief":"Don't carry it all alone; bring your co-parent in to share the load as a team.","relearn":"Invite your co-parent to learn and share the load; two champions beat one exhausted parent.","persona":"Vikram","source":"share with partner"},
  {"id":"nd-1280","cat":"support-and-you","type":"branch","hook":"You suspect your own low mood has tipped into something heavier.","options":[{"text":"Reach out: Tele-MANAS 14416 or Looking After You (g63)","consequence":"You tend your wellbeing so you can keep tending your child's.","outcome":"reach-out","best":true},{"text":"Tell yourself you've no right to struggle and bury it","consequence":"Reaching out tends your wellbeing; burying it lets the weight grow and dims you for your child."}],"debrief":"Your low mood matters; reach out via Tele-MANAS 14416 or g63.","relearn":"Your wellbeing matters too; reach out via Tele-MANAS 14416 or g63 rather than burying it.","persona":"Divya","source":"reach for yourself"},
  {"id":"nd-1281","cat":"support-and-you","type":"branch","hook":"A grandparent offers to help but admits they 'don't get the diagnosis'.","options":[{"text":"Give them a simple explanation and one concrete way to help","consequence":"A willing grandparent becomes steady support for you both.","outcome":"guide-in","best":true},{"text":"Wave them off; explaining feels like too much","consequence":"A little guidance turns them into support; waving them off loses a willing helper your child adores."}],"debrief":"Guide a willing grandparent in with a simple explanation and a task.","relearn":"Bring a willing relative in with a simple explanation and one concrete task; don't waste the offer.","persona":"any","source":"guide grandparent in"},
  {"id":"nd-1282","cat":"support-and-you","type":"branch","hook":"You feel guilty taking two hours for yourself while a friend watches your child.","options":[{"text":"Take the break and let it refill you, guilt-free","consequence":"You come back steadier and more present for your child.","outcome":"take-break","best":true},{"text":"Cancel and stay 'just in case', running on empty","consequence":"A guilt-free break refills you; cancelling to hover keeps you depleted and no more useful."}],"debrief":"Take the offered break without guilt; your own refill is part of your child's support.","relearn":"A break isn't neglect; let it refill you so you return steadier and more present.","persona":"Divya","source":"guilt-free break"},
  {"id":"nd-1283","cat":"support-and-you","type":"sort","hook":"Sort: a wise step for a parent, or one to rethink?","items":[{"id":"a","text":"Joining a parent support group"},{"id":"b","text":"Chasing a paid 'miracle cure'"},{"id":"c","text":"Seeing a qualified professional"},{"id":"d","text":"Coping in silence and isolation"},{"id":"e","text":"Being honest you need help"},{"id":"f","text":"Running on empty alone"}],"bins":[{"id":"wise","label":"Wise step","valence":"pos"},{"id":"rethink","label":"Rethink it","valence":"neg"}],"key":{"a":"wise","b":"rethink","c":"wise","d":"rethink","e":"wise","f":"rethink"},"relearn":"Groups, professionals and honest asks are wise; cures, silence and running on empty need a rethink.","persona":"any","source":"wise vs rethink"},
  {"id":"nd-1284","cat":"support-and-you","type":"sort","hook":"Sort: sustains a parent for the long haul, or burns them out?","items":[{"id":"a","text":"Sharing the load with someone"},{"id":"b","text":"Never once asking for help"},{"id":"c","text":"Resting when you can"},{"id":"d","text":"Carrying every task alone"},{"id":"e","text":"Leaning on a support network"},{"id":"f","text":"Skipping all your own needs"}],"bins":[{"id":"sustain","label":"Sustains you","valence":"pos"},{"id":"burn","label":"Burns you out","valence":"neg"}],"key":{"a":"sustain","b":"burn","c":"sustain","d":"burn","e":"sustain","f":"burn"},"relearn":"Sharing, resting and a network sustain you; never asking, doing it all and skipping your needs burn you out.","persona":"any","source":"sustain vs burn"},
  {"id":"nd-1285","cat":"support-and-you","type":"sort","hook":"Sort: who can a parent turn to for real support, or not the right place?","items":[{"id":"a","text":"A qualified professional for assessment"},{"id":"b","text":"A stranger selling a 'cure'"},{"id":"c","text":"Other parents of neurodiverse kids"},{"id":"d","text":"An anonymous forum's medical 'advice'"},{"id":"e","text":"Tele-MANAS for mental-health support"},{"id":"f","text":"A salesman pushing a gadget fix"}],"bins":[{"id":"real","label":"Real support","valence":"pos"},{"id":"not","label":"Not the place","valence":"neg"}],"key":{"a":"real","b":"not","c":"real","d":"not","e":"real","f":"not"},"relearn":"Professionals, peer parents and Tele-MANAS are real support; cure-sellers and gadget pitches are not.","persona":"any","source":"real support or not"},
  {"id":"nd-1286","cat":"support-and-you","type":"sort","hook":"Sort: a sign you need to refill, or a sign you're coping well?","items":[{"id":"a","text":"Snapping at everyone lately"},{"id":"b","text":"Letting a relative take a shift"},{"id":"c","text":"Dreading every morning"},{"id":"d","text":"Resting without guilt"},{"id":"e","text":"Crying alone and hiding it"},{"id":"f","text":"Asking for help early"}],"bins":[{"id":"refill","label":"Time to refill","valence":"uhoh"},{"id":"coping","label":"Coping well","valence":"pos"}],"key":{"a":"refill","b":"coping","c":"refill","d":"coping","e":"refill","f":"coping"},"relearn":"Snapping, dread and hidden tears say refill; sharing shifts, guilt-free rest and asking early show coping.","persona":"Divya","source":"refill or coping"},
  {"id":"nd-1287","cat":"support-and-you","type":"sort","hook":"Sort: brings family in as champions, or pushes them away?","items":[{"id":"a","text":"Explaining his profile simply"},{"id":"b","text":"Snapping 'you wouldn't understand'"},{"id":"c","text":"Giving a relative a concrete task"},{"id":"d","text":"Hiding everything from family"},{"id":"e","text":"Sharing what calms your child"},{"id":"f","text":"Refusing every offer of help"}],"bins":[{"id":"in","label":"Brings them in","valence":"pos"},{"id":"away","label":"Pushes them away","valence":"neg"}],"key":{"a":"in","b":"away","c":"in","d":"away","e":"in","f":"away"},"relearn":"Explaining, giving a task and sharing what calms bring family in; snapping, hiding and refusing push them away.","persona":"Vikram","source":"family in or away"},
  {"id":"nd-1288","cat":"support-and-you","type":"sort","hook":"Sort: a kind thing to tell yourself, or an unfair pressure?","items":[{"id":"a","text":"\"Learning and loving is enough\""},{"id":"b","text":"\"I must have every answer\""},{"id":"c","text":"\"Asking for help is okay\""},{"id":"d","text":"\"I should never be tired\""},{"id":"e","text":"\"My rest helps my child too\""},{"id":"f","text":"\"A good parent copes alone\""}],"bins":[{"id":"kind","label":"Kind to yourself","valence":"pos"},{"id":"unfair","label":"Unfair pressure","valence":"neg"}],"key":{"a":"kind","b":"unfair","c":"kind","d":"unfair","e":"kind","f":"unfair"},"relearn":"Learning is enough, asking is okay and your rest helps; needing every answer or coping alone is unfair pressure.","persona":"any","source":"kind or pressure"},
  {"id":"nd-1289","cat":"support-and-you","type":"sort","hook":"Sort: a healthy way to handle a hard day, or one that wears you thinner?","items":[{"id":"a","text":"Texting a parent who gets it"},{"id":"b","text":"Doom-scrolling 'cures' till 2am"},{"id":"c","text":"Naming one thing that went okay"},{"id":"d","text":"Bottling it all up inside"},{"id":"e","text":"Taking ten quiet minutes"},{"id":"f","text":"Skipping meals to keep going"}],"bins":[{"id":"healthy","label":"Healthy","valence":"pos"},{"id":"thinner","label":"Wears you thin","valence":"neg"}],"key":{"a":"healthy","b":"thinner","c":"healthy","d":"thinner","e":"healthy","f":"thinner"},"relearn":"Texting a peer, naming a win and quiet minutes help; scrolling cures, bottling up and skipping meals wear you thin.","persona":"Divya","source":"healthy or thin"},
  {"id":"nd-1290","cat":"support-and-you","type":"sort","hook":"Sort: what this tool can do for you, or what only a professional can?","items":[{"id":"a","text":"Offer understanding and support"},{"id":"b","text":"Diagnose your specific child"},{"id":"c","text":"Point you to where help lives"},{"id":"d","text":"Prescribe your child's care plan"},{"id":"e","text":"Lift shame with honest reframes"},{"id":"f","text":"Formally assess your child"}],"bins":[{"id":"tool","label":"This tool can","valence":"pos"},{"id":"pro","label":"Only a professional","valence":"neutral"}],"key":{"a":"tool","b":"pro","c":"tool","d":"pro","e":"tool","f":"pro"},"relearn":"This tool offers understanding, signposting and reframes; diagnosis, a care plan and assessment need a professional.","persona":"any","source":"tool vs professional"},
  {"id":"nd-1291","cat":"support-and-you","type":"reflect","hook":"Lensy: looking after yourself isn't taking from your child. It's part of how you support them. Sit right?","prompt":"What's your take?","options":["Sits right","My wellbeing counts","Part of support"],"affirm":"Caring for yourself isn't stealing from your child; your wellbeing is part of the support you give them.","relearn":"Looking after yourself is part of supporting your child, not a betrayal of them.","persona":"Divya","source":"self-care is support"},
  {"id":"nd-1292","cat":"support-and-you","type":"reflect","hook":"Lensy: you don't have to be the perfect parent. A learning, loving, supported one is enough. Land okay?","prompt":"What do you think?","options":["Lands okay","Enough as I am","Learning is fine"],"affirm":"You don't have to be perfect or all-knowing; a learning, loving, supported parent is exactly what your child needs.","relearn":"You don't have to be perfect; a learning, loving, supported parent is enough.","persona":"any","source":"enough as you are"},
  {"id":"nd-1293","cat":"support-and-you","type":"reflect","hook":"Lensy: a parent who is sustained can sustain their child. You matter to this too. Resonate?","prompt":"What's your take?","options":["Resonates","I matter too","Sustained to sustain"],"affirm":"A sustained parent sustains their child; tending to your own energy is part of caring for them.","relearn":"A sustained parent sustains their child; you matter to your child's support too.","persona":"Meena","source":"you matter too"},
  {"id":"nd-1294","cat":"support-and-you","type":"reflect","hook":"Lensy: asking for help isn't a confession of failure. It's a sign you're parenting wisely. Agree?","prompt":"What do you think?","options":["Agree","Asking is wise","Not failure"],"affirm":"Asking for help is wise parenting, not a confession of failure; strong parents lean on support.","relearn":"Asking for help is wisdom, not failure; it's part of parenting well.","persona":"Vikram","source":"asking is wise"},
  {"id":"nd-1295","cat":"support-and-you","type":"reflect","hook":"Lensy: somewhere, other parents are walking this exact road. You are not alone in it. Sit right?","prompt":"What's your take?","options":["Sits right","Not alone","Others get it"],"affirm":"Other parents are walking this same road; their understanding reminds you that you are not alone.","relearn":"You're not alone; other parents walk this road and truly understand it.","persona":"Divya","source":"not alone in it"},
  {"id":"nd-1296","cat":"support-and-you","type":"reflect","hook":"Lensy: it's okay to grieve the hard days and still adore your child fiercely. Both can be true. Land okay?","prompt":"What do you think?","options":["Lands okay","Both true","Hard and loving"],"affirm":"You can find the days hard and love your child fiercely at once; honest feelings don't shrink your love.","relearn":"It's okay to find days hard and adore your child at once; both feelings can be true.","persona":"any","source":"both can be true"},
  {"id":"nd-1297","cat":"support-and-you","type":"reflect","hook":"Lensy: every champion you let in, like a partner, relative or friend, is one more person loving your child. Worth it?","prompt":"What's your take?","options":["Worth it","More champions","Let them in"],"affirm":"Each person you bring in to understand and help is one more champion loving and supporting your child.","relearn":"Every champion you let in is one more person loving and supporting your child.","persona":"Vikram","source":"more champions"},
  {"id":"nd-1298","cat":"support-and-you","type":"reflect","hook":"Lensy: you've learned to understand, accommodate, advocate and drop the shame. Now hold yourself gently too. Ready?","prompt":"What do you think?","options":["Ready","Gentle with me","I'm doing my best"],"affirm":"You've learned to understand, accommodate, advocate and drop the shame; holding yourself gently too is the last piece.","relearn":"Understand, accommodate, advocate, drop the shame, and be gentle with yourself too.","persona":"any","source":"gentle with yourself"},
  {"id":"nd-1299","cat":"support-and-you","type":"role-play","hook":"A fellow parent of a neurodiverse child says they feel completely alone. You want to support them.","setup":"Support them warmly:","yourLine":[{"text":"\"You're not alone. Let's swap what helps and lean on each other through this.\"","best":true},{"text":"\"Yeah, honestly, I don't know how any of us survive it.\""}],"relearn":"Telling an isolated parent they're not alone and offering to swap tips builds the network that sustains you both.","persona":"Priya","source":"you're not alone"},
  {"id":"nd-1300","cat":"support-and-you","type":"role-play","hook":"Your partner says 'you handle him, you're just better at it'. You want to bring them in as a teammate.","setup":"Bring them in:","yourLine":[{"text":"\"He needs us both. Let's learn this together so neither of us carries it alone.\"","best":true},{"text":"\"Fine, I'll just do all of it myself, like always.\""}],"relearn":"Inviting your co-parent to learn together shares the load and gives your child two engaged champions.","persona":"Vikram","source":"bring partner in"},
  {"id":"nd-1301","cat":"support-and-you","type":"role-play","hook":"A friend asks how you really are, and you're tempted to brush it off. You want to be honest.","setup":"Be honest:","yourLine":[{"text":"\"Honestly it's hard and I'm tired. I love him fiercely and I could use some support.\"","best":true},{"text":"\"Oh, we're absolutely fine, nothing to worry about.\""}],"relearn":"Being honest that it's hard and you need support opens the door to the help that keeps you going.","persona":"Divya","source":"be honest with a friend"},
  {"id":"nd-1302","cat":"support-and-you","type":"role-play","hook":"A grandparent wants to help but says they 'don't understand the diagnosis'. You want to guide them in.","setup":"Guide them in:","yourLine":[{"text":"\"Here's a simple way to understand him, and one thing that really helps: he adores you.\"","best":true},{"text":"\"Just leave it, it's too complicated to explain.\""}],"relearn":"A simple explanation and one concrete task turn a willing grandparent into real, steady support.","persona":"any","source":"guide grandparent rp"},
  {"id":"nd-1303","cat":"support-and-you","type":"role-play","hook":"A relative pushes an expensive 'cure' they read about. You want to decline without a fight.","setup":"Decline gently:","yourLine":[{"text":"\"There's no cure to buy. What helps him is understanding and proper support, and we're on it.\"","best":true},{"text":"\"Maybe you're right, perhaps we should just try it.\""}],"relearn":"Gently naming that there's no cure to buy protects your money, your hope and your child from quackery.","persona":"any","source":"decline the cure"},
  {"id":"nd-1304","cat":"support-and-you","type":"role-play","hook":"Your sister offers to babysit so you can rest, and guilt rises. You want to accept the help.","setup":"Accept the help:","yourLine":[{"text":"\"Thank you, yes. A real rest will help me be steadier for him, and he loves you.\"","best":true},{"text":"\"No no, I couldn't, I should be the one doing everything.\""}],"relearn":"Accepting offered help and rest refills you so you return steadier; it isn't neglect, it's support.","persona":"Divya","source":"accept the help"},
  {"id":"nd-1305","cat":"support-and-you","type":"role-play","hook":"At a new parent support group, someone asks why you came. You want to be open, not defensive.","setup":"Be open:","yourLine":[{"text":"\"I'm raising an autistic son and I'd love to learn from people who really get it.\"","best":true},{"text":"\"Oh, I'm just here to watch, I don't really have problems.\""}],"relearn":"Being open in a support group lets in the understanding and practical tips it exists to share.","persona":"any","source":"open at group"},
  {"id":"nd-1306","cat":"support-and-you","type":"role-play","hook":"You're at breaking point and your spouse asks what you need. You want to ask clearly.","setup":"Ask clearly:","yourLine":[{"text":"\"I need a proper break this weekend. Can you take the mornings so I can recharge?\"","best":true},{"text":"\"Nothing, I'm fine, don't worry about me at all.\""}],"relearn":"Asking clearly for what you need lets your partner share the load before you reach a crash.","persona":"Vikram","source":"ask clearly"},
  {"id":"nd-1307","cat":"support-and-you","type":"role-play","hook":"A new parent in your circle is panicking after a fresh diagnosis. You want to reassure them.","setup":"Reassure them:","yourLine":[{"text":"\"It's a key to support, not a tragedy, and you don't have to do any of it alone.\"","best":true},{"text":"\"Yeah, brace yourself, it only gets harder from here.\""}],"relearn":"Telling a frightened new parent it's a key, not a tragedy, and they're not alone steadies them.","persona":"Priya","source":"reassure new parent"},
  {"id":"nd-1308","cat":"support-and-you","type":"role-play","hook":"You feel low and a counsellor at Tele-MANAS asks what's going on. You want to be real, not minimise.","setup":"Be real:","yourLine":[{"text":"\"I'm exhausted and low, and I think I need some support for myself, not just my child.\"","best":true},{"text":"\"It's nothing, really, I just have a lot on, never mind.\""}],"relearn":"Being real about your own struggle lets a counsellor actually help; minimising it shuts the door.","persona":"Divya","source":"real with counsellor"},
  {"id":"nd-1309","cat":"support-and-you","type":"role-play","hook":"Your co-parent feels useless and is pulling back. You want to give them a clear role.","setup":"Give them a role:","yourLine":[{"text":"\"You're brilliant at his bedtime routine. Could that be your thing? It really helps him.\"","best":true},{"text":"\"It's okay, you're no good at this stuff, I'll handle it.\""}],"relearn":"Giving a hesitant co-parent a clear, valued role draws them in instead of letting them drift away.","persona":"Vikram","source":"give a role"},
  {"id":"nd-1310","cat":"support-and-you","type":"role-play","hook":"A relative says you 'spoil' yourself by getting support. You want to hold your ground kindly.","setup":"Hold your ground:","yourLine":[{"text":"\"Getting support keeps me steady for him. A rested parent is a better parent.\"","best":true},{"text":"\"You're right, I should just push through without any help.\""}],"relearn":"Naming that support keeps you steady defends your wellbeing against the 'spoiling yourself' jibe.","persona":"any","source":"hold your ground"},
  {"id":"nd-1311","cat":"support-and-you","type":"role-play","hook":"Another parent confides they're chasing every 'cure' and burning out. You want to gently steer them.","setup":"Steer them gently:","yourLine":[{"text":"\"There's no cure to chase. What helped us was support and rest. You deserve that too.\"","best":true},{"text":"\"Keep at it, one of those cures is bound to work eventually.\""}],"relearn":"Gently steering a burning-out parent toward support and rest, not cures, protects them and their child.","persona":"any","source":"steer from cures"},
  {"id":"nd-1312","cat":"support-and-you","type":"role-play","hook":"Your child's aunt asks how she can actually help. You want to give her something concrete.","setup":"Give her something concrete:","yourLine":[{"text":"\"Could you take him to the park Saturdays? He loves it, and it gives me an hour to breathe.\"","best":true},{"text":"\"Oh, there's nothing really, we're managing fine, thanks.\""}],"relearn":"Giving a willing relative a concrete, doable task turns goodwill into real support for you both.","persona":"Vikram","source":"concrete ask"},
  {"id":"nd-1313","cat":"support-and-you","type":"role-play","hook":"You catch yourself apologising for taking an evening off. You want to reframe it for yourself.","setup":"Reframe it out loud:","yourLine":[{"text":"\"This evening off isn't a luxury. It's how I keep showing up for him all week.\"","best":true},{"text":"\"I really shouldn't be doing this, I'm being selfish.\""}],"relearn":"Reframing a break as fuel, not a luxury, frees a parent to refill without guilt.","persona":"Divya","source":"reframe the break"},
  {"id":"nd-1314","cat":"support-and-you","type":"spot","hook":"Spot the 2 red flags: the moves that burn a parent out.","scene":[{"id":"a","text":"Leaning on a support network","trick":false},{"id":"b","text":"Carrying every single task alone","trick":true},{"id":"c","text":"Resting when you can","trick":false},{"id":"d","text":"Never once asking for help","trick":true},{"id":"e","text":"Sharing the load with family","trick":false}],"why":"Carrying it all alone and never asking for help are the red flags: they burn a devoted parent out.","relearn":"Doing everything alone and never asking for help burn you out; sharing, resting and a network sustain you.","persona":"any","source":"burnout flags"},
  {"id":"nd-1315","cat":"support-and-you","type":"spot","hook":"Spot the 2 red flags: the 'support' that isn't real support.","scene":[{"id":"a","text":"A qualified professional's assessment","trick":false},{"id":"b","text":"A stranger selling a 'miracle cure'","trick":true},{"id":"c","text":"Other parents who truly get it","trick":false},{"id":"d","text":"A forum diagnosing your child for you","trick":true},{"id":"e","text":"Tele-MANAS mental-health support","trick":false}],"why":"The cure-seller and the forum 'diagnosis' are the red flags: neither is real, qualified support.","relearn":"Professionals, peer parents and Tele-MANAS are real support; cure-sellers and forum 'diagnoses' aren't.","persona":"any","source":"fake support flags"},
  {"id":"nd-1316","cat":"support-and-you","type":"spot","hook":"Spot the 2 red flags: the unfair pressures a parent puts on themselves.","scene":[{"id":"a","text":"\"Learning and loving is enough\"","trick":false},{"id":"b","text":"\"I must know every answer\"","trick":true},{"id":"c","text":"\"Asking for help is okay\"","trick":false},{"id":"d","text":"\"A good parent never tires\"","trick":true},{"id":"e","text":"\"My rest helps my child too\"","trick":false}],"why":"\"I must know every answer\" and \"a good parent never tires\" are the red flags: impossible, unfair demands.","relearn":"Needing every answer or never tiring is unfair pressure; learning, asking and resting are enough.","persona":"any","source":"pressure flags"},
  {"id":"nd-1317","cat":"support-and-you","type":"spot","hook":"Spot the 2 red flags: the signs a parent is running on empty.","scene":[{"id":"a","text":"Resting without guilt","trick":false},{"id":"b","text":"Snapping at everyone lately","trick":true},{"id":"c","text":"Asking for help early","trick":false},{"id":"d","text":"Dreading every single morning","trick":true},{"id":"e","text":"Letting a relative take a shift","trick":false}],"why":"Snapping at everyone and dreading every morning are the red flags: your tank is empty and needs refilling.","relearn":"Snapping and dread say you're running empty; rest, asking early and sharing shifts refill you.","persona":"Divya","source":"empty-tank flags"},
  {"id":"nd-1318","cat":"support-and-you","type":"spot","hook":"Spot the 2 red flags: the moves that push willing family away.","scene":[{"id":"a","text":"Explaining his profile simply","trick":false},{"id":"b","text":"Snapping 'you'll never understand'","trick":true},{"id":"c","text":"Giving a relative a concrete task","trick":false},{"id":"d","text":"Hiding everything from them","trick":true},{"id":"e","text":"Sharing what calms your child","trick":false}],"why":"Snapping 'you'll never understand' and hiding everything are the red flags: they push willing family away.","relearn":"Snapping and hiding push family away; explaining, giving a task and sharing what calms bring them in.","persona":"Vikram","source":"push-away flags"},
  {"id":"nd-1319","cat":"support-and-you","type":"spot","hook":"Spot the 2 red flags: the things this tool can NOT do for your child.","scene":[{"id":"a","text":"Offer understanding and support","trick":false},{"id":"b","text":"Formally diagnose your child","trick":true},{"id":"c","text":"Point you toward real help","trick":false},{"id":"d","text":"Replace your child's professional","trick":true},{"id":"e","text":"Lift shame with honest reframes","trick":false}],"why":"Diagnosing and replacing a professional are the red flags: only a qualified professional does those.","relearn":"This tool supports and signposts; it can't diagnose or replace the professional who assesses your child.","persona":"any","source":"tool-limit flags"},
  {"id":"nd-1320","cat":"support-and-you","type":"spot","hook":"Spot the 2 red flags: the ways a parent isolates instead of reaching out.","scene":[{"id":"a","text":"Texting a parent who understands","trick":false},{"id":"b","text":"Bottling every worry up inside","trick":true},{"id":"c","text":"Joining a support group","trick":false},{"id":"d","text":"Insisting 'no one can help me'","trick":true},{"id":"e","text":"Calling Tele-MANAS on a hard night","trick":false}],"why":"Bottling it up and insisting no one can help are the red flags: isolation that quietly wears a parent down.","relearn":"Bottling up and 'no one can help' isolate you; texting peers, a group and Tele-MANAS reach out.","persona":"any","source":"isolation flags"},
  {"id":"nd-1350","cat":"understand-your-child","type":"strike-rewrite","hook":"\"If I just push harder, my child will become a normal kid.\"","myth":{"un":"If I just push harder, my child will become a normal kid.","re":"There is no single 'normal' brain to push toward; your job is to understand your child's wiring, not erase it.","why":"Brains naturally vary; the goal is understanding, not erasing."},"relearn":"You can't push a child into being 'normal'; understand their wiring, the goal isn't to erase who they are.","persona":"Meena","source":"no normal to push toward"},
  {"id":"nd-1351","cat":"understand-your-child","type":"strike-rewrite","hook":"\"My nephew is just very shy, every quiet child is the same.\"","myth":{"un":"My nephew is just very shy; every quiet child is the same.","re":"Every child's profile is their own; 'quiet' can mean many things, so understand this child, not a stereotype.","why":"No single profile fits every child."},"relearn":"Every child's profile is their own; understand the actual child in front of you, not a one-size label.","persona":"Priya","source":"every profile is individual"},
  {"id":"nd-1352","cat":"understand-your-child","type":"strike-rewrite","hook":"\"A diagnosis will define and limit my daughter for life.\"","myth":{"un":"A diagnosis will define and limit my daughter for life.","re":"A diagnosis is information that unlocks support; it's a key, not a verdict, and your child is unchanged by it.","why":"The child is the same; only your understanding grows."},"relearn":"A diagnosis is a key to support, not a verdict that limits your child; she is unchanged by the label.","persona":"Divya","source":"key not verdict"},
  {"id":"nd-1353","cat":"understand-your-child","type":"strike-rewrite","hook":"\"My son's autism means he can't feel love or connect with us.\"","myth":{"un":"My son's autism means he can't feel love or connect with us.","re":"Autistic children feel and connect deeply; they may just show it in their own way, which is yours to learn.","why":"Different expression isn't absent feeling."},"relearn":"Autistic children feel and connect deeply; they show it their own way, which is yours to learn to read.","persona":"Meena","source":"connection shown differently"},
  {"id":"nd-1354","cat":"understand-your-child","type":"strike-rewrite","hook":"\"His intense focus on trains is an obsession we must break.\"","myth":{"un":"His intense focus on trains is an obsession we must break.","re":"A deep interest is a real strength to feed, not break; it can grow confidence, skills and even a future path.","why":"A passion fed becomes a strength, not a problem."},"relearn":"An intense interest is a strength to feed, not an obsession to break; it can grow into something amazing.","persona":"Meena","source":"interest is a strength"},
  {"id":"nd-1355","cat":"understand-your-child","type":"strike-rewrite","hook":"\"Dyslexia just means my child is slow and not very bright.\"","myth":{"un":"Dyslexia just means my child is slow and not very bright.","re":"Dyslexia is a different way of processing print, not low intelligence; it often pairs with big-picture thinking.","why":"Reading difficulty isn't a measure of intelligence."},"relearn":"Dyslexia is a different way of reading, not low intelligence; it often comes with strong big-picture thinking.","persona":"Divya","source":"dyslexia not low intelligence"},
  {"id":"nd-1356","cat":"understand-your-child","type":"strike-rewrite","hook":"\"My ADHD kid is just lazy and unmotivated, that's all it is.\"","myth":{"un":"My ADHD kid is just lazy and unmotivated, that's all it is.","re":"ADHD is a difference in attention and regulation, not laziness; the energy and quick thinking are real strengths.","why":"A wiring difference isn't a character flaw."},"relearn":"ADHD is a difference in attention, not laziness; the energy and quick thinking that come with it are real strengths.","persona":"Vikram","source":"adhd not lazy"},
  {"id":"nd-1357","cat":"understand-your-child","type":"strike-rewrite","hook":"\"Comparing him to his cousin shows me how far behind he is.\"","myth":{"un":"Comparing him to his cousin shows me how far behind he is.","re":"Measure your child against their own profile and pace, not a cousin's milestones; comparison misses who they are.","why":"Your child's pace is the only fair yardstick."},"relearn":"Meet your child's own profile and pace, not a cousin's milestones; comparison only hides who your child really is.","persona":"Meena","source":"their own pace not comparison"},
  {"id":"nd-1358","cat":"understand-your-child","type":"strike-rewrite","hook":"\"Once he grows up, he'll grow out of all of this.\"","myth":{"un":"Once he grows up, he'll grow out of all of this.","re":"Neurodivergence is lifelong; children don't grow out of it, but understanding and support help them thrive.","why":"It's how the brain is wired, not a phase."},"relearn":"Neurodivergence is lifelong; a child doesn't grow out of it, but understanding and support help them truly thrive.","persona":"Meena","source":"lifelong not a phase"},
  {"id":"nd-1359","cat":"understand-your-child","type":"strike-rewrite","hook":"\"He doesn't make eye contact, so he must not be listening.\"","myth":{"un":"He doesn't make eye contact, so he must not be listening.","re":"Many neurodiverse children listen better without forced eye contact; looking away can be how they focus.","why":"Eye contact and listening aren't the same thing."},"relearn":"Many neurodiverse children listen best without eye contact; looking away can be how they focus, not how they ignore.","persona":"Meena","source":"eye contact isn't listening"},
  {"id":"nd-1360","cat":"understand-your-child","type":"strike-rewrite","hook":"\"There's nothing special about her, she's just difficult.\"","myth":{"un":"There's nothing special about her, she's just difficult.","re":"Seeing her strengths, not only the struggles, changes how she comes to see herself; she's far more than 'difficult'.","why":"What you notice in her shapes her self-image."},"relearn":"Seeing your child's strengths, not just the struggles, shapes how she sees herself; she is so much more than 'difficult'.","persona":"Divya","source":"see strengths shapes self"},
  {"id":"nd-1361","cat":"understand-your-child","type":"reflect","hook":"Lensy: your child is a whole, wonderful person, far more than any diagnosis. Sit right with you?","prompt":"What's your take?","options":["Sits right","More than a label","A whole person"],"affirm":"Your child is a whole, wonderful person, far more than a diagnosis; seeing all of them is what matters most.","relearn":"Your child is a whole person, far more than a diagnosis; loving all of who they are matters most.","persona":"Meena","source":"more than a label"},
  {"id":"nd-1362","cat":"understand-your-child","type":"reflect","hook":"Lensy: the first step of support is learning how your child actually experiences the world. Resonate?","prompt":"What do you think?","options":["Resonates","Learn how they feel it","First step"],"affirm":"Asking how your child experiences the world, rather than judging them by a template, is the first real step of support.","relearn":"The first step of support is learning how your child experiences the world, not measuring them against a template.","persona":"Meena","source":"experience first"},
  {"id":"nd-1363","cat":"understand-your-child","type":"reflect","hook":"Lensy: brains varying is just part of being human, like different heights or voices. Feel true?","prompt":"What's your view?","options":["Feels true","Part of being human","Natural variation"],"affirm":"Brains varying is natural human variation, like different heights or voices; your child's way of thinking is valid.","relearn":"Brains varying is natural human variation; your child's way of thinking is valid, not a flaw to fix.","persona":"any","source":"variation is human"},
  {"id":"nd-1364","cat":"understand-your-child","type":"reflect","hook":"Lensy: when you stop asking 'why won't he behave' and start asking 'what's he telling me', things shift. Agree?","prompt":"What do you feel?","options":["Agree","Behaviour is a message","Worth a try"],"affirm":"Swapping 'why won't he behave' for 'what is he telling me' turns frustration into understanding of your real child.","relearn":"Asking 'what is my child telling me' instead of 'why won't he behave' turns frustration into real understanding.","persona":"Divya","source":"behaviour is communication"},
  {"id":"nd-1365","cat":"understand-your-child","type":"reflect","hook":"Lensy: it's okay to grieve the picture you imagined, then turn fully toward the child you have. Land for you?","prompt":"What's your take?","options":["Lands","Grief is allowed","Turn toward them"],"affirm":"Allowing yourself to grieve the imagined child, then turning toward the real one, lets you meet who they truly are.","relearn":"It's okay to grieve the child you pictured, then turn fully toward the wonderful child you actually have.","persona":"Divya","source":"allow the grief then turn"},
  {"id":"nd-1366","cat":"understand-your-child","type":"reflect","hook":"Lensy: your child's honesty and deep focus are gifts the world often forgets to value. Worth holding onto?","prompt":"What's your view?","options":["Worth it","Honesty is a gift","Focus is a gift"],"affirm":"Honesty, deep focus and noticing what others miss are real gifts; naming them aloud helps your child treasure them too.","relearn":"Your child's honesty and deep focus are real gifts; naming them aloud helps your child value them as well.","persona":"Meena","source":"name the gifts"},
  {"id":"nd-1367","cat":"understand-your-child","type":"reflect","hook":"Lensy: understanding your child isn't a test to pass perfectly, it's a relationship you keep learning. Sit right?","prompt":"What do you think?","options":["Sits right","Keep learning","Not a test"],"affirm":"Understanding your child is an ongoing, imperfect relationship, not a test to ace; a learning parent is exactly enough.","relearn":"Understanding your child is a relationship you keep learning, not a test to pass; a learning parent is exactly enough.","persona":"Vikram","source":"a relationship not a test"},
  {"id":"nd-1368","cat":"understand-your-child","type":"reflect","hook":"Lensy: who your child is today is worth celebrating, not just who they might become. True for you?","prompt":"What's your take?","options":["True","Celebrate today","Not just later"],"affirm":"Your child is worth celebrating exactly as they are today, not only for who they might grow into later.","relearn":"Celebrate who your child is today, not only who they might become; they are worth delighting in right now.","persona":"Meena","source":"celebrate who they are now"},
  {"id":"nd-1369","cat":"understand-your-child","type":"sort","hook":"Sort: a real strength a neurodiverse child may bring, or a deficit-only label?","items":[{"id":"a","text":"Notices tiny details others miss"},{"id":"b","text":"'Just can't sit still'"},{"id":"c","text":"Honest, says what's true"},{"id":"d","text":"'Always in his own world'"},{"id":"e","text":"Remembers facts vividly"},{"id":"f","text":"'Never pays attention'"}],"bins":[{"id":"strength","label":"A real strength","valence":"pos"},{"id":"deficit","label":"Deficit-only label","valence":"neg"}],"key":{"a":"strength","b":"deficit","c":"strength","d":"deficit","e":"strength","f":"deficit"},"relearn":"Noticing details, honesty and vivid memory are real strengths; 'can't sit still, own world, never pays attention' see only deficits.","persona":"any","source":"strength vs deficit label"},
  {"id":"nd-1370","cat":"understand-your-child","type":"sort","hook":"Sort: a true statement about neurodivergence, or a myth?","items":[{"id":"a","text":"It's lifelong wiring"},{"id":"b","text":"Bad parenting causes it"},{"id":"c","text":"Each child's profile differs"},{"id":"d","text":"You grow out of it"},{"id":"e","text":"Strengths come with it"},{"id":"f","text":"It means low intelligence"}],"bins":[{"id":"true","label":"True","valence":"pos"},{"id":"myth","label":"Myth","valence":"neg"}],"key":{"a":"true","b":"myth","c":"true","d":"myth","e":"true","f":"myth"},"relearn":"Lifelong wiring, individual profiles and real strengths are true; 'bad parenting, grow out of it, low intelligence' are myths.","persona":"any","source":"true vs myth"},
  {"id":"nd-1371","cat":"understand-your-child","type":"sort","hook":"Sort: which everyday strength tends to go with which profile? (every child is still individual)","items":[{"id":"a","text":"Deep focus on a topic"},{"id":"b","text":"Burst of energy and ideas"},{"id":"c","text":"Honest, literal answers"},{"id":"d","text":"Quick, creative problem-solving"},{"id":"e","text":"Spotting visual patterns"},{"id":"f","text":"Big-picture, spatial thinking"}],"bins":[{"id":"autism","label":"Often autism","valence":"neutral"},{"id":"adhd","label":"Often ADHD","valence":"neutral"},{"id":"dyslexia","label":"Often dyslexia","valence":"neutral"}],"key":{"a":"autism","b":"adhd","c":"autism","d":"adhd","e":"autism","f":"dyslexia"},"relearn":"Deep focus, honesty and pattern-spotting often go with autism; energy and quick ideas with ADHD; big-picture thinking with dyslexia.","persona":"any","source":"strength by profile"},
  {"id":"nd-1372","cat":"understand-your-child","type":"sort","hook":"Sort: a way of understanding your child, or judging them?","items":[{"id":"a","text":"'How does he experience this?'"},{"id":"b","text":"'Why won't he be normal?'"},{"id":"c","text":"'What does she need here?'"},{"id":"d","text":"'She's doing this to annoy me'"},{"id":"e","text":"'What is he good at?'"},{"id":"f","text":"'He's just being difficult'"}],"bins":[{"id":"understand","label":"Understanding","valence":"pos"},{"id":"judge","label":"Judging","valence":"neg"}],"key":{"a":"understand","b":"judge","c":"understand","d":"judge","e":"understand","f":"judge"},"relearn":"Asking how a child experiences things and what they need understands them; 'why won't he be normal, doing it to annoy me' judges.","persona":"Meena","source":"understand vs judge"},
  {"id":"nd-1373","cat":"understand-your-child","type":"sort","hook":"Sort: what a diagnosis actually is, or what it is not?","items":[{"id":"a","text":"Information to guide support"},{"id":"b","text":"A tragedy to mourn forever"},{"id":"c","text":"A key that opens help"},{"id":"d","text":"A verdict on your child"},{"id":"e","text":"A shared word with school"},{"id":"f","text":"Proof something is broken"}],"bins":[{"id":"is","label":"What it is","valence":"pos"},{"id":"isnot","label":"What it is not","valence":"neg"}],"key":{"a":"is","b":"isnot","c":"is","d":"isnot","e":"is","f":"isnot"},"relearn":"A diagnosis is information, a key and a shared word for support; it is not a tragedy, a verdict, or proof your child is broken.","persona":"Divya","source":"diagnosis is vs isnt"},
  {"id":"nd-1374","cat":"understand-your-child","type":"sort","hook":"Sort: a behaviour that's overwhelm to understand, or genuine defiance to discipline?","items":[{"id":"a","text":"Meltdown in a loud mall"},{"id":"b","text":"Hands over ears at a party"},{"id":"c","text":"Refusing a sudden plan change"},{"id":"d","text":"Stimming when excited"},{"id":"e","text":"Hitting a sibling for a toy"},{"id":"f","text":"Lying to dodge a chore"}],"bins":[{"id":"overwhelm","label":"Overwhelm","valence":"uhoh"},{"id":"choice","label":"A choice to guide","valence":"neutral"}],"key":{"a":"overwhelm","b":"overwhelm","c":"overwhelm","d":"overwhelm","e":"choice","f":"choice"},"relearn":"Meltdowns, covering ears, resisting sudden changes and stimming are overwhelm; hitting for a toy or lying are ordinary choices to guide.","persona":"Meena","source":"overwhelm vs choice"},
  {"id":"nd-1375","cat":"understand-your-child","type":"sort","hook":"Sort: a strengths-first thought, or a deficit-first one?","items":[{"id":"a","text":"'She learns best by doing'"},{"id":"b","text":"'He can't do anything right'"},{"id":"c","text":"'His memory amazes me'"},{"id":"d","text":"'She's so far behind'"},{"id":"e","text":"'He cares so deeply'"},{"id":"f","text":"'Why is he always a problem?'"}],"bins":[{"id":"strengths","label":"Strengths-first","valence":"pos"},{"id":"deficit","label":"Deficit-first","valence":"neg"}],"key":{"a":"strengths","b":"deficit","c":"strengths","d":"deficit","e":"strengths","f":"deficit"},"relearn":"Noticing how she learns, his memory and how deeply he cares is strengths-first; 'can't do anything, so behind, a problem' is deficit-first.","persona":"any","source":"strengths-first vs deficit-first"},
  {"id":"nd-1376","cat":"understand-your-child","type":"sort","hook":"Sort: a kind, accurate thing to say to your child, or a harmful one?","items":[{"id":"a","text":"'Your brain works its own way'"},{"id":"b","text":"'There's something wrong with you'"},{"id":"c","text":"'I love how your mind works'"},{"id":"d","text":"'Why can't you be normal?'"},{"id":"e","text":"'We'll figure this out together'"},{"id":"f","text":"'You're too much to handle'"}],"bins":[{"id":"kind","label":"Kind and true","valence":"pos"},{"id":"harmful","label":"Harmful","valence":"neg"}],"key":{"a":"kind","b":"harmful","c":"kind","d":"harmful","e":"kind","f":"harmful"},"relearn":"'Your brain works its own way, I love your mind, we'll figure it out' protect a child; 'something's wrong, be normal, too much' wound them.","persona":"Meena","source":"kind vs harmful words"},
  {"id":"nd-1377","cat":"understand-your-child","type":"match","hook":"Match each profile to a common strength (every child is still their own person).","pairs":[{"left":"Autism","right":"Deep focus and honesty"},{"left":"ADHD","right":"Energy and creative thinking"},{"left":"Dyslexia","right":"Big-picture, spatial thinking"},{"left":"Dyspraxia","right":"Determined, creative problem-solving"},{"left":"Dyscalculia","right":"Strong verbal and story skills"}],"relearn":"Each profile commonly brings real strengths: autism deep focus, ADHD energy, dyslexia big-picture thinking, though every child is unique.","persona":"any","source":"profile to strength"},
  {"id":"nd-1378","cat":"understand-your-child","type":"match","hook":"Match each behaviour to what it may really be communicating.","pairs":[{"left":"Covering ears","right":"This noise hurts me"},{"left":"Lining up toys","right":"Order helps me feel calm"},{"left":"Repeating a phrase","right":"I'm soothing or processing"},{"left":"Refusing new food","right":"This texture feels wrong"},{"left":"Running off in a crowd","right":"I'm overwhelmed and need space"}],"relearn":"Behaviour is communication: covering ears means noise hurts, lining up brings calm, repeating soothes, refusing food is texture, running is overwhelm.","persona":"Meena","source":"behaviour to meaning"},
  {"id":"nd-1379","cat":"understand-your-child","type":"match","hook":"Match each myth to the truth that replaces it.","pairs":[{"left":"Caused by bad parenting","right":"It's simply how the brain is wired"},{"left":"They'll grow out of it","right":"It's lifelong; support helps them thrive"},{"left":"It means low intelligence","right":"It's a difference, not a measure of smarts"},{"left":"A diagnosis is a verdict","right":"It's a key that opens support"},{"left":"Just naughtiness","right":"Often overwhelm, not defiance"}],"relearn":"Myths fall to truth: not parenting but wiring, lifelong not outgrown, difference not low intelligence, a key not a verdict, overwhelm not naughtiness.","persona":"any","source":"myth to truth"},
  {"id":"nd-1380","cat":"understand-your-child","type":"match","hook":"Match each parent question to the understanding it opens.","pairs":[{"left":"What is he good at?","right":"Builds on strengths"},{"left":"How does she experience this?","right":"Sees through her senses"},{"left":"What does this behaviour say?","right":"Reads it as communication"},{"left":"What's his own pace?","right":"Drops the comparison trap"},{"left":"What does she need now?","right":"Moves from blame to support"}],"relearn":"Better questions open understanding: strengths, her senses, behaviour as a message, his own pace, and what she needs over blame.","persona":"Divya","source":"question to understanding"},
  {"id":"nd-1381","cat":"understand-your-child","type":"match","hook":"Match each child's everyday moment to the gift hiding inside it.","pairs":[{"left":"Asks 'why' a hundred times","right":"A curious, hungry mind"},{"left":"Won't bend the rules of a game","right":"A strong sense of fairness"},{"left":"Talks endlessly about dinosaurs","right":"Deep, expert-level passion"},{"left":"Notices a tiny change in the room","right":"Sharp, detailed attention"},{"left":"Says exactly what she thinks","right":"Refreshing honesty"}],"relearn":"Everyday moments hide gifts: endless 'why' is curiosity, rigid rules are fairness, a passion runs deep, noticing is attention, bluntness is honesty.","persona":"Meena","source":"moment to gift"},
  {"id":"nd-1382","cat":"understand-your-child","type":"match","hook":"Match each neurodiverse trait to a fair, everyday way to picture it.","pairs":[{"left":"Sensory overload","right":"Like a too-loud, too-bright room"},{"left":"Trouble with sudden change","right":"Like losing the map mid-journey"},{"left":"Hyperfocus","right":"Like the world going quiet around one thing"},{"left":"Needing routine","right":"Like a handrail on the stairs"},{"left":"Stimming","right":"Like tapping a foot to settle"}],"relearn":"Fair pictures build empathy: overload is a too-loud room, change is a lost map, hyperfocus is quiet focus, routine is a handrail, stimming is settling.","persona":"any","source":"trait to picture"},
  {"id":"nd-1383","cat":"understand-your-child","type":"match","hook":"Match each profile to a daily moment where its strength can shine.","pairs":[{"left":"Pattern-spotter","right":"Sorting and organising a collection"},{"left":"High-energy thinker","right":"An active, hands-on task"},{"left":"Big-picture mind","right":"Planning the whole trip at once"},{"left":"Deep specialist","right":"Becoming the family expert on a topic"},{"left":"Honest observer","right":"Giving a true, useful opinion"}],"relearn":"Strengths shine in daily life: a pattern-spotter organises, an energetic mind builds, a big-picture mind plans, a specialist teaches, an honest child advises.","persona":"any","source":"profile to shining moment"},
  {"id":"nd-1384","cat":"understand-your-child","type":"branch","hook":"A diagnosis arrived today. How do you hold it?","options":[{"text":"Read it as a guide to understand and support him","consequence":"The word becomes a map to your actual child.","outcome":"a-map","best":true},{"text":"Treat it as the worst news of your life","consequence":"Fear floods in, though he is unchanged."},{"text":"Ignore it and carry on as before","consequence":"The chance to understand him slips past."}],"debrief":"Hold a diagnosis as information that helps you support your child, not a tragedy or a verdict.","relearn":"A diagnosis is a guide to support, not the worst news or a thing to ignore; your child is unchanged.","persona":"Meena","source":"hold the diagnosis"},
  {"id":"nd-1385","cat":"understand-your-child","type":"branch","hook":"Your daughter melts down every time you visit the noisy market.","options":[{"text":"Read it as overwhelm and adjust the trip","consequence":"Seen through her senses, the meltdowns ease.","outcome":"her-senses","best":true},{"text":"Decide she's naughty and scold her","consequence":"It shames a child who was already drowning."},{"text":"Avoid taking her anywhere again","consequence":"Avoidance shrinks her world instead of helping."}],"debrief":"A meltdown in a loud place is overwhelm to understand, not naughtiness to punish.","relearn":"Market meltdowns are sensory overwhelm to understand and adjust for, not naughtiness to scold away.","persona":"Meena","source":"meltdown as overwhelm"},
  {"id":"nd-1386","cat":"understand-your-child","type":"branch","hook":"Relatives keep calling your son 'slow'. You want to understand him.","options":[{"text":"Watch how he learns and find what clicks","consequence":"He learns by doing; 'slow' was 'different'.","outcome":"how-he-learns","best":true},{"text":"Believe the relatives and lose hope","consequence":"'Slow' buries his real ability."},{"text":"Push him to keep up with his cousins","consequence":"A cousin's pace exhausts him and misses his way."}],"debrief":"Understand your child by watching how he learns, not by accepting 'slow' or forcing a pace.","relearn":"Understand your child by observing how he learns, not by trusting 'slow' or forcing a cousin's pace.","persona":"Divya","source":"watch how he learns"},
  {"id":"nd-1387","cat":"understand-your-child","type":"branch","hook":"Your child is fixated on maps and talks about them for hours.","options":[{"text":"Explore maps together and feed the passion","consequence":"Confidence blooms; the interest becomes a strength.","outcome":"feed-it","best":true},{"text":"Tell him to do something 'useful'","consequence":"Shut down, he learns his joy is a flaw."},{"text":"Treat the interest as a symptom","consequence":"Suppressing a passion wastes a real gift."}],"debrief":"An intense interest is a strength to feed and explore together, not an obsession to shut down.","relearn":"Explore your child's passion together; a deep interest is a strength to feed, not a flaw to suppress.","persona":"Meena","source":"feed the passion"},
  {"id":"nd-1388","cat":"understand-your-child","type":"branch","hook":"You keep comparing your child to every kid at the family function.","options":[{"text":"Refocus on your child's own pace and wins","consequence":"You see progress comparison had hidden.","outcome":"own-pace","best":true},{"text":"Keep score against every cousin","consequence":"Scorekeeping only manufactures worry."},{"text":"Decide he must catch up by year-end","consequence":"A forced deadline breeds pressure, not growth."}],"debrief":"Meet your child's own profile and pace; comparison to other children hides the progress that's there.","relearn":"Refocus on your child's own pace and wins; comparing him to others only hides his real progress.","persona":"Meena","source":"own pace not comparison"},
  {"id":"nd-1389","cat":"understand-your-child","type":"branch","hook":"Your child asks, 'Mumma, is something wrong with me?'","options":[{"text":"Say nothing's wrong; his brain works its own way","consequence":"He hears he's whole and loved, worth intact.","outcome":"nothing-wrong","best":true},{"text":"Say 'we're trying to fix it, don't worry'","consequence":"'Fixing it' confirms his fear he's broken."},{"text":"Brush it off and change the subject","consequence":"The scary thought grows alone in his mind."}],"debrief":"Tell your child nothing is wrong; their brain works its own way, with real gifts.","relearn":"Tell your child nothing is wrong; their brain works its own brilliant way, protecting their self-worth.","persona":"Meena","source":"nothing is wrong"},
  {"id":"nd-1390","cat":"understand-your-child","type":"branch","hook":"A teacher calls your son 'a bit abnormal' in front of you.","options":[{"text":"Calmly say his brain works differently, and explain","consequence":"You reframe with dignity and open her up.","outcome":"reframe","best":true},{"text":"Agree and apologise to smooth it over","consequence":"You hand a stranger's label to your child."},{"text":"Snap angrily and storm out","consequence":"Anger ends the talk; her view stays put."}],"debrief":"When someone calls your child 'abnormal', calmly reframe it as a different way of being.","relearn":"When a teacher calls your child 'abnormal', calmly reframe it as different wiring; don't accept it or explode.","persona":"Vikram","source":"reframe abnormal"},
  {"id":"nd-1391","cat":"understand-your-child","type":"branch","hook":"Exhausted, you're tempted to see your child as 'the difficult one'.","options":[{"text":"Pause and name one strength you love in her","consequence":"It reminds you who she really is.","outcome":"name-a-strength","best":true},{"text":"Let 'the difficult one' become your view","consequence":"It becomes a label she'll absorb."},{"text":"Decide the struggles are all there is","consequence":"You erase the whole wonderful child."}],"debrief":"Even when tired, see your child's strengths, not only the struggle; what you notice shapes her.","relearn":"When tired, pause and name a strength in your child; what you keep noticing shapes how she sees herself.","persona":"Divya","source":"name a strength when tired"},
  {"id":"nd-1392","cat":"understand-your-child","type":"spot","hook":"Spot the two lines that misunderstand a neurodiverse child.","scene":[{"id":"a","text":"'His brain works its own way, that's okay'","trick":false},{"id":"b","text":"'He's just doing this for attention'","trick":true},{"id":"c","text":"'Let me learn how he sees the world'","trick":false},{"id":"d","text":"'If I scold him enough, he'll be normal'","trick":true},{"id":"e","text":"'What's he good at? Let's build on that'","trick":false}],"why":"'Doing it for attention' and 'scold him normal' misunderstand him; the others seek to understand and build on strengths.","relearn":"Understand your child by learning how he sees the world and building on strengths, not scolding him 'normal'.","persona":"Meena","source":"two misunderstandings"},
  {"id":"nd-1393","cat":"understand-your-child","type":"spot","hook":"Spot the two myths about neurodivergence in this conversation.","scene":[{"id":"a","text":"'Brains naturally vary, this is human'","trick":false},{"id":"b","text":"'Too much screen time made him this way'","trick":true},{"id":"c","text":"'Every child's profile is their own'","trick":false},{"id":"d","text":"'He'll just grow out of it by ten'","trick":true},{"id":"e","text":"'It comes with real strengths too'","trick":false}],"why":"'Screens caused it' and 'he'll grow out of it' are myths; brains vary, each profile differs, and strengths come too.","relearn":"Screens don't cause neurodivergence and kids don't grow out of it; brains vary and real strengths come too.","persona":"any","source":"two hidden myths"},
  {"id":"nd-1394","cat":"understand-your-child","type":"spot","hook":"Spot the two reactions that turn a diagnosis into a verdict.","scene":[{"id":"a","text":"'This helps me understand and support her'","trick":false},{"id":"b","text":"'Our family's future is ruined now'","trick":true},{"id":"c","text":"'She's the same girl she was yesterday'","trick":false},{"id":"d","text":"'She'll never achieve anything in life'","trick":true},{"id":"e","text":"'Now I know how to get her the right help'","trick":false}],"why":"'Future is ruined' and 'never achieve anything' treat a diagnosis as a verdict; it's information, your child is unchanged.","relearn":"A diagnosis is information to guide support, not a verdict; your child is the same, with help now in reach.","persona":"Divya","source":"diagnosis not a verdict"},
  {"id":"nd-1395","cat":"understand-your-child","type":"spot","hook":"Spot the two deficit-only thoughts in this list of observations.","scene":[{"id":"a","text":"'She remembers everything she reads'","trick":false},{"id":"b","text":"'He's hopeless, can't do anything right'","trick":true},{"id":"c","text":"'He notices what everyone else misses'","trick":false},{"id":"d","text":"'She's nothing but a constant problem'","trick":true},{"id":"e","text":"'Her honesty is actually refreshing'","trick":false}],"why":"'Hopeless' and 'nothing but a problem' see only deficits; the others notice memory, attention and honesty as strengths.","relearn":"Lead with strengths like memory, attention and honesty; 'hopeless' or 'a problem' sees only deficits and wounds a child.","persona":"any","source":"two deficit thoughts"},
  {"id":"nd-1396","cat":"understand-your-child","type":"spot","hook":"Spot the two responses that misread overwhelm as bad behaviour.","scene":[{"id":"a","text":"'The party was too loud, let's step out'","trick":false},{"id":"b","text":"'Stop the drama right now or else'","trick":true},{"id":"c","text":"'You're safe, I'm here, breathe with me'","trick":false},{"id":"d","text":"'He's just being defiant to embarrass us'","trick":true},{"id":"e","text":"'Sudden change is hard for him, I'll warn him'","trick":false}],"why":"'Stop the drama' and 'defiant to embarrass us' misread overwhelm as bad behaviour; the others meet it with calm and warning.","relearn":"Meltdowns are overwhelm, not drama or defiance; meet them with calm, safety and warning, not 'stop it or else'.","persona":"Meena","source":"two misreadings of overwhelm"},
  {"id":"nd-1397","cat":"understand-your-child","type":"spot","hook":"Spot the two things you should never say to a child about their wiring.","scene":[{"id":"a","text":"'I love the way your mind works'","trick":false},{"id":"b","text":"'There's something wrong with you'","trick":true},{"id":"c","text":"'We'll figure this out together'","trick":false},{"id":"d","text":"'Why can't you just be like other kids?'","trick":true},{"id":"e","text":"'Your brain has its own superpowers'","trick":false}],"why":"'Something wrong with you' and 'be like other kids' wound a child; the others affirm their mind is loved and not alone.","relearn":"Never tell a child something's wrong or to be like others; affirm their mind is loved and they're not alone.","persona":"Meena","source":"two things never to say"},
  {"id":"nd-1398","cat":"understand-your-child","type":"spot","hook":"Spot the two beliefs that confuse a child's profile with their worth.","scene":[{"id":"a","text":"'He's a whole, wonderful person'","trick":false},{"id":"b","text":"'He's basically just his diagnosis'","trick":true},{"id":"c","text":"'There's so much more to her than this'","trick":false},{"id":"d","text":"'Her label is the only thing that matters'","trick":true},{"id":"e","text":"'I love him for exactly who he is'","trick":false}],"why":"'Just his diagnosis' and 'the label is all' shrink a child to a profile; the others see the whole, wonderful person they are.","relearn":"A child is a whole person, far more than a diagnosis; never shrink them to a label, love all of who they are.","persona":"Meena","source":"two shrinking beliefs"},
  {"id":"nd-1399","cat":"understand-your-child","type":"spot","hook":"Spot the two 'cure' promises a parent should distrust.","scene":[{"id":"a","text":"'Understanding and support help him thrive'","trick":false},{"id":"b","text":"'This diet will cure his autism fast'","trick":true},{"id":"c","text":"'A professional can guide what helps'","trick":false},{"id":"d","text":"'One course will make him fully normal'","trick":true},{"id":"e","text":"'His wiring is lifelong, and that's okay'","trick":false}],"why":"'A diet that cures autism' and 'a course to make him normal' are false promises; neurodivergence is lifelong, helped by support.","relearn":"Distrust anyone selling a cure; neurodivergence is lifelong and helped by support, not diets or 'normalising' courses.","persona":"Divya","source":"two cure promises"},
  {"id":"nd-1400","cat":"understand-your-child","type":"role-play","hook":"Your mother says your son is 'just spoiled and needs strict discipline'. Set her straight kindly.","setup":"Reply with warmth and truth:","yourLine":[{"text":"\"He isn't spoiled, Ma; his brain works differently, and what he needs is understanding, not strictness.\"","best":true},{"text":"\"Maybe you're right, I'll just be tougher on him.\""}],"relearn":"Telling a relative your child isn't spoiled but wired differently, needing understanding over strictness, protects him from blame.","persona":"Meena","source":"not spoiled, wired differently"},
  {"id":"nd-1401","cat":"understand-your-child","type":"role-play","hook":"Your daughter says, 'Everyone calls me weird at school.' Help her hold her head up.","setup":"Answer her with love:","yourLine":[{"text":"\"Your mind works in its own brilliant way; different isn't weird, and I wouldn't change a thing about you.\"","best":true},{"text":"\"Just try to act more like the other kids so they stop.\""}],"relearn":"Reframing 'weird' as a different, brilliant way of being protects a child's self-worth instead of asking her to mask.","persona":"Divya","source":"different isn't weird"},
  {"id":"nd-1402","cat":"understand-your-child","type":"role-play","hook":"Your husband says 'there's nothing different about him, you're imagining it.' Open the conversation.","setup":"Invite him to understand:","yourLine":[{"text":"\"I'm not imagining it; let's learn how he experiences things together so we can really support him.\"","best":true},{"text":"\"Fine, forget I said anything, I'll handle it alone.\""}],"relearn":"Inviting a co-parent to learn together, rather than going silent, doubles a child's champions instead of leaving one parent alone.","persona":"Meena","source":"invite the co-parent in"},
  {"id":"nd-1403","cat":"understand-your-child","type":"role-play","hook":"Your son proudly explains planets for ten minutes straight. Respond to the passion.","setup":"Honour his interest:","yourLine":[{"text":"\"I love how much you know about this; your curiosity is one of my favourite things about you.\"","best":true},{"text":"\"Okay, that's enough space talk for one day.\""}],"relearn":"Honouring a child's deep interest as a treasured strength feeds his confidence, rather than teaching him his passion is a bother.","persona":"Vikram","source":"honour the passion"},
  {"id":"nd-1404","cat":"understand-your-child","type":"role-play","hook":"A neighbour asks, 'So when will he be cured and normal?' Answer with calm clarity.","setup":"Set the record straight:","yourLine":[{"text":"\"There's nothing to cure; his brain is wired its own way, and with support he's already thriving as himself.\"","best":true},{"text":"\"We're trying lots of treatments, hopefully he'll be normal soon.\""}],"relearn":"Saying there's nothing to cure, just a different wiring supported to thrive, rejects the false cure framing and the shame behind it.","persona":"Meena","source":"nothing to cure"},
  {"id":"nd-1405","cat":"understand-your-child","type":"role-play","hook":"Your child sobs, 'Why am I not like everyone else?' Meet the moment.","setup":"Comfort and reframe:","yourLine":[{"text":"\"Because you're wonderfully you; your mind sees things others can't, and that's a gift, not a flaw.\"","best":true},{"text":"\"Don't say that, just try harder to fit in, okay?\""}],"relearn":"Reframing 'not like everyone' as a gift rather than a flaw to fix protects a child's sense of being whole and valued.","persona":"Divya","source":"wonderfully you"},
  {"id":"nd-1406","cat":"understand-your-child","type":"role-play","hook":"Your sister whispers that you must have 'done something during pregnancy'. Shut the blame down gently.","setup":"Answer without absorbing the blame:","yourLine":[{"text":"\"It's no one's fault, didi; this is simply how his brain is wired, and blame helps him least of all.\"","best":true},{"text":"\"Maybe it was something I did, I keep wondering too.\""}],"relearn":"Stating plainly it's no one's fault, just how the brain is wired, refuses the blame myths that hurt both parent and child.","persona":"Meena","source":"no one's fault"},
  {"id":"nd-1407","cat":"understand-your-child","type":"role-play","hook":"Your older child asks why their sibling 'acts so strange sometimes'. Build understanding, not othering.","setup":"Explain with warmth:","yourLine":[{"text":"\"His brain works in its own way, so loud places overwhelm him; he's not strange, he just feels things more.\"","best":true},{"text":"\"He's just being annoying, ignore him when he's like that.\""}],"relearn":"Explaining a sibling's wiring with warmth teaches the older child acceptance and empathy instead of othering their brother.","persona":"Divya","source":"explain to a sibling"},
];

